INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0001-FUNC-00', 1, 'FUNC', 0, '[R5] Opt-in GitHub integration', 'Validated', 'P1', 'Medium', 'Prevents accidental writes to shared issue trackers. Closes F-04. Evidence: claude-lifecycle-lab/NOTES.md.', 'create_task silently creates a real GitHub issue whenever gh is installed and the server''s working directory has a github.com origin (F-04).', 'GitHub issues are created only when a project explicitly enables the integration.', '["LIFECYCLE_GITHUB=on enables issue creation and sync; the default is off", "When off, no gh or git subprocesses are spawned", "Tool responses state whether GitHub sync is enabled"]', NULL, NULL, NULL, '["With the variable unset, create_task in a repository with a GitHub origin creates no issue", "With LIFECYCLE_GITHUB=on, the existing GitHub tests pass", "README documents the switch"]', NULL, NULL, 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-14 19:37:54', 2, 2, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0001-INTF-00', 1, 'INTF', 0, '[R10] Quiet, structured tool responses', 'Validated', 'P2', 'Low', 'Closes F-05. Evidence: claude-lifecycle-lab/NOTES.md.', 'Every create response carries ''LLM analysis not available'' noise (F-05). Responses are text only, and three *_json tools duplicate their text counterparts.', 'Responses are concise text plus machine-readable structured content, from one tool per operation.', '["Remove the LLM-unavailable warning from create_requirement", "Tools return structuredContent JSON alongside their text summary, without declaring an outputSchema (ADR-0002 budget rule)", "Fold query_requirements_json, query_tasks_json, query_architecture_decisions_json and get_project_metrics into structured results of query_requirements, query_tasks, query_architecture_decisions and get_project_status"]', NULL, NULL, NULL, '["create_requirement''s response is a single status line plus structured data", "query_requirements, query_tasks, query_architecture_decisions and get_project_status return structured results carrying what the folded tools returned", "The tool count drops by four with no loss of capability: 23 tools by default, 24 with LIFECYCLE_GITHUB=on (ADR-0002 target)", "tests/tool_surface_budget.json is lowered to the measured surface"]', NULL, NULL, 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-15 16:22:58', 5, 5, 1, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0001-NFUNC-00', 1, 'NFUNC', 0, '[R14] Ergonomics: short IDs and subtask-aware progress', 'Validated', 'P3', 'Low', 'Closes F-06 and F-22; F-28 is resolved. Evidence: claude-lifecycle-lab/NOTES.md.', 'Verified on 2026-09-15. Per-type numbering makes a bare number ambiguous: in this tracker requirement number 1 is four records (FUNC, INTF, NFUNC, TECH) and number 2 is another four, so the REQ-12 form the finding suggested cannot resolve (F-06). Nothing resolves aliases today: every tool needs the full stored ID. Requirement progress double counts: create_task links every task to its requirements, subtasks included, and the task_count and tasks_completed triggers count all implements links, so a requirement whose one task is split in two reads 3 tasks (F-22). The test-suite part of F-28 is fixed: the default pytest run is green in well under a minute.', 'IDs can be typed without zero padding or the trailing version, and progress counts the work that is actually done.', '["Every tool that takes a record ID also accepts a short form: REQ-12-FUNC for REQ-0012-FUNC-00, TASK-12 for TASK-0012-00-00, TASK-12-1 for TASK-0012-01-00, ADR-4 for ADR-0004", "Full stored IDs keep working exactly as they do now", "An alias matching nothing is refused as unknown; one matching more than one record is refused with the candidates named", "task_count and tasks_completed count leaf tasks only: a task with a parent is counted through its parent rather than twice"]', NULL, '["ADR-0002: no new tool, and the resolver adds no tool parameters, so the budget does not move", "Aliases resolve in one place in BaseHandler so every tool behaves the same way", "Stored IDs never change: an alias is only an input form (owner decision, 2026-09-15)"]', NULL, '["get_details accepts REQ-12-FUNC and TASK-12 and returns the same record as the full ID", "An alias that matches two records is refused, naming both", "A requirement whose only task is split into two Complete subtasks reports 2 of 2 tasks complete", "An existing database gets the corrected counters by migration, with no status touched"]', NULL, '["A fast default test run: done (34 s, green, 2026-09-15)", "Renumbering or renaming records: aliases resolve to the IDs already stored"]', 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-16 11:05:17', 3, 3, 2, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0001-TECH-00', 1, 'TECH', 0, '[R1] Installable again: pin the MCP SDK and check fresh installs in CI', 'Validated', 'P0', 'Low', 'Nobody can adopt the tool if it doesn''t start. Closes F-01. Evidence: claude-lifecycle-lab/NOTES.md.', 'pyproject.toml declares mcp[cli]>=1.0.0 with no upper bound. Fresh installs resolve mcp 2.x, which removed Server.list_tools(), so the server crashes before initialize and clients only see ''Connection closed'' (F-01). The test suite runs against uv.lock (mcp 1.10.1), so CI stays green.', 'A fresh install from source always yields a working server, and CI proves it on every change.', '["Constrain mcp[cli] to >=1.10,<2 in pyproject.toml and refresh uv.lock", "A CI job performs a clean `uv tool install .` and completes an MCP initialize + tools/list handshake", "Track the port to mcp 2.x as separate follow-up work"]', NULL, NULL, NULL, '["`uv tool install --force .` with no extra flags produces a server that answers tools/list", "The CI install job fails when the pin is removed", "README, CLAUDE.md and USAGE_EXAMPLES.md show the working install command"]', NULL, NULL, 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-14 19:37:48', 2, 2, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0002-FUNC-00', 2, 'FUNC', 0, '[R6] Edit records and cover the whole schema', 'Deprecated', 'P2', 'Medium', 'Closes F-09, F-14, F-27. Evidence: claude-lifecycle-lab/NOTES.md.', 'No tool can edit requirement, task or ADR content after creation, or delete a record (F-14). Schema fields such as out_of_scope and test_plan are accepted and silently dropped (F-09). Plans can''t be reshaped once work reveals the code''s real coupling (F-27).', 'Agents can correct and refine records, and every stored field is reachable through a tool.', '["update_requirement, update_task and update_architecture for content fields", "Accept every schema field on create and update, or reject unknown fields with an error", "Re-parent, merge or abandon tasks with history kept in lifecycle_events"]', NULL, NULL, NULL, '["Editing acceptance criteria is reflected in details and export", "Passing an unknown field returns an error that names it", "Every schema column can be set by some tool"]', NULL, NULL, 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-14 20:13:28', 0, 0, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0002-INTF-00', 2, 'INTF', 0, '[R16] Streamline the tool surface to the reviewed target', 'Validated', 'P3', 'Medium', 'Smaller tool definitions leave more context for the project itself and make the right tool easier to pick. Changing the surface once, after review, avoids breaking clients repeatedly.', '39 tools, with overlapping reads (three relationship queries, three *_json duplicates, project status and project metrics), opt-in GitHub sync tools listed even when GitHub is off, and interview and diagram tools whose redesign is pending under R11 and R13.', 'The server exposes the tool surface accepted in the R15 ADR: fewer, clearer tools with no loss of capability, and clients are told what changed.', '["Apply ADR-0002: get_details, delete_record and add_comment replace the per-type ID-only tools; one query_relationships replaces three; one sync_github_tasks registered only when LIFECYCLE_GITHUB=on; the interview tools and the diagrams tool''s interactive parameter are removed; descriptions are trimmed", "Folded capabilities stay reachable through the remaining tools'' parameters", "Renamed tools get no aliases; a changelog lists every removed tool and its replacement, alongside README and CLAUDE.md", "Coordinate with R10 (*_json and project metrics folds), R11 (any interview replacement) and R13 (diagram output) so each tool changes once"]', NULL, NULL, NULL, '["tools/list matches ADR-0002''s target once R10''s folds land: 23 tools with GitHub off, 24 with it on. R16 alone reaches 27 and 28", "tests/tool_surface_budget.json is lowered to the measured surface in each change that folds or removes tools", "Every acceptance test that used a removed or renamed tool passes using its replacement", "The MCP handshake smoke test and the install smoke workflow pass"]', NULL, NULL, 'heffrey78 (drafted by Claude Code)', '2026-09-14 22:56:31', '2026-09-15 16:22:56', 6, 6, 1, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0002-NFUNC-00', 2, 'NFUNC', 0, '[R15] Review the tool surface with evidence before streamlining', 'Validated', 'P2', 'Low', 'Every tool definition costs context on every request and makes choosing the right tool harder for the agent. Measuring first avoids folding tools agents rely on, and a budget stops the surface growing unnoticed.', 'The server registers 39 tools whose definitions add about 16.6k characters (~4.1k tokens) to every request; the three update tools are the largest at about 1.2k characters each. In the lab session an agent used 24 of the 32 tools then available: eight were never called (GitHub sync x2, delete_relationship, query_relationships, query_requirements, three *_json duplicates), and status transitions were 54% of all calls. Nothing tracks tool count or definition size, so each roadmap item adds tools without a view of the whole surface.', 'Decisions to add, fold or remove tools rest on measurements and an accepted ADR describing the target tool surface, and growth of the surface is visible in CI.', '["A script or test reports tool count and tools/list size per handler, and CI fails when either grows past a recorded budget unless the budget is updated in the same change", "An inventory classifies every registered tool as keep, fold, register-only-when-enabled or remove, with the evidence and the capability each fold preserves", "Usage evidence from at least one agent session driving a real project through the lifecycle: calls per tool, never-called tools, failed or retried calls", "An ADR records the target surface and the principles for future tools, such as one tool per operation and conditional registration for opt-in features"]', NULL, NULL, NULL, '["The budget check runs in CI and names the handler and size that exceeded the budget", "The inventory covers every registered tool and states the tool count and definition size the target would reach", "The ADR is Accepted before any tool is removed or renamed", "The usage evidence accounts for every call the server received, including calls refused before a handler runs, so that server-side and client-side call counts agree for the same session"]', NULL, NULL, 'heffrey78 (drafted by Claude Code)', '2026-09-14 22:56:26', '2026-09-16 17:13:18', 4, 4, 1, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0002-TECH-00', 2, 'TECH', 0, '[R2] Keep stdout for the MCP protocol', 'Validated', 'P0', 'Low', 'Removes a source of ''Connection closed'' failures in stricter MCP clients. Closes F-02. Evidence: claude-lifecycle-lab/NOTES.md.', 'migrations.py and github_utils.py print() to stdout, which is the JSON-RPC channel: 19 non-JSON lines on a fresh database and 6 more on every later start (F-02).', 'stdout carries only JSON-RPC; all diagnostics go through logging to stderr.', '["Replace every print() in src/lifecycle_mcp with module loggers", "Enable a lint rule (ruff T20) that forbids print in src/"]', NULL, NULL, NULL, '["A test starts the server on a fresh database, completes a handshake and asserts every stdout line parses as JSON-RPC", "No print( calls remain in src/lifecycle_mcp"]', NULL, NULL, 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-14 19:37:50', 2, 2, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0003-FUNC-00', 3, 'FUNC', 0, '[R7] Answer ''what should I work on next?''', 'Validated', 'P2', 'Low', 'Closes F-21 and F-29; R3 removed F-32''s cause. Evidence: claude-lifecycle-lab/NOTES.md.', 'Task details (get_details) show comments since R16 but not dependencies: blocked-by and blocks need a separate query_relationships call (F-21). No query returns tasks whose dependencies are all Complete. The dashboard''s Blocked Items section works again since R3, but it only lists tasks with dependency links; a task marked Blocked without links shows only in the status count, and there is no field for the reason (F-29). The schema damage behind F-32 can no longer be served: since R3 a failed migration rolls back and stops the server.', 'An agent can ask for the next workable tasks and see why anything is blocked.', '["query_tasks with ready: true returns Not Started tasks whose dependencies are all Complete, highest priority first. A task''s dependencies are the tasks it depends on or requires, and the tasks that block it", "get_details on a task lists Depends On and Blocks", "The comment given when a task moves to Blocked is kept as its blocked reason until it leaves Blocked, and details show it", "get_project_status lists every Blocked task with its reason and unmet dependencies, and every Not Started task waiting on dependencies, in the text and in structuredContent"]', NULL, '["ADR-0002: no new tool. The ready filter is a query_tasks parameter and the reason reuses update_task_status''s comment; the budget rises in the same change", "blocked_reason is a tasks column (migration 15) that only update_task_status writes"]', NULL, '["The ready-to-start query excludes a task until each of its dependencies is Complete", "get_details on a task lists the tasks it depends on and the tasks it blocks", "A task marked Blocked with a reason and no dependency links appears by name, with its reason, on the dashboard"]', NULL, '["A schema health check on the dashboard: since R3 a failed migration rolls back and stops the server, which removed F-32''s cause"]', 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-16 00:21:54', 5, 5, 2, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0003-INTF-00', 3, 'INTF', 0, '[R19] Errors that name the parameter that would have worked', 'Validated', 'P3', 'Low', 'Closes F-54 and continues R4''s honest-errors work into the failure mode that actually cost time. One mis-remembered parameter name cost about 5% of a run''s total tool traffic and sent me writing up a defect that did not exist. Evidence: claude-lifecycle-lab/linkcheck/RUN-NOTES.md.', 'Measured in the linkcheck dogfooding run, 2026-09-16. Bulk status moves take requirement_ids, task_ids and architecture_ids; the single form takes requirement_id, task_id and architecture_id - one character apart. Passing a list to the singular name returns "Input validation error: [''REQ-1-FUNC'', ...] is not of type ''string''", which names the offending value and never mentions that a parameter accepting exactly that value exists in the same schema. Every other tool in the surface takes a singular ID (entity_id, task_id, requirement_id), so singular is the habit the surface teaches. In the run I used the plural form correctly in one phase, reached for the singular two hours later, spent five extra calls recovering, and had begun writing up "bulk moves do not work for requirements" before reading the schema: the message sent me looking in the wrong place.', 'When a call is refused because of a parameter that has a near neighbour in the same schema accepting what was passed, the error names that neighbour.', '["A type error on a parameter whose schema has a sibling accepting the supplied type names that sibling in the message", "The message still names the refused parameter and the type it expects", "The suggestion is drawn from the tool''s own schema rather than a hand-maintained list of pairs"]', NULL, '["ADR-0002: no new tool and no new parameters; this changes message text produced where validation already fails", "Depends on R18: a refused call should be logged as well as explained, and both changes touch the same routing path"]', NULL, '["Passing a list to requirement_id returns an error naming requirement_ids", "The same holds for task_id and architecture_id", "A type error with no such sibling returns the message it returns today, unchanged", "An unknown field is still refused by name, as R6a requires"]', '["Every singular-or-plural ID pair in the surface produces a naming suggestion when the wrong one is used"]', '["Making the singular parameter accept a list as well: ADR-0003 chose distinct names deliberately, and accepting both would make the two forms indistinguishable in schemas and in the call log", "Renaming either form: existing clients depend on both"]', 'Claude (linkcheck dogfooding run, 2026-09-16)', '2026-09-16 16:39:08', '2026-09-17 01:35:36', 2, 2, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0003-NFUNC-00', 3, 'NFUNC', 0, 'Requirement search a large stored set can be reconciled against', 'Draft', 'P1', 'Medium', 'R21 made reconciliation a prompt on the argument that reading a source is the client model''s job and the server only has to be compared against. That argument holds exactly as far as the comparison reaches, and it reaches 5.8% of each record with no term splitting. The prompt already carries three paragraphs of workarounds for this - search again with another wording, do not list the whole set, a duplicate costs more than a question - which is as far as wording can get; the remaining gap is in the server. Until it closes, adopting a body of work that predates the tracker produces the duplicates R21 exists to prevent, and the more requirements are already stored the worse it gets, which is the opposite of how the feature has to behave.', 'query_requirements'' search_text is one substring against two columns: requirement_handler.py builds "(title LIKE ? OR desired_state LIKE ?)" and nothing else. Measured against this tracker''s own 26 requirements on 2026-09-28: title and desired_state hold 4,572 of the 79,488 characters the records contain, so 5.8% of a requirement''s stored text is reachable by search and the 94% that identifies it - functional requirements, acceptance criteria, current state - is not. There is no term splitting, so natural phrasing fails silently: search_text="export resume" returns 0 rows where "export" returns 1. Of 26 queries a model reconciling this repository''s own code would plausibly run, all against features that are stored and Validated, 12 returned nothing, including "staleness" and "stale" against R17 whose subject is staleness, "prompt" against R11 and R21 themselves, "bulk status" against R9, and "dependencies" and "ready to start" against R14''s ready filter. The prompt''s answer to an empty search is to report NEW and flag it, so those 12 are the path that produces duplicates. There is also no limit, offset or field projection: every query returns every field of every match at about 3,057 characters a record, so a search matching 200 requirements is as unusable as the whole-set listing the reconcile prompt already forbids.', 'A candidate requirement can be matched against a large stored set by searching, with a recall figure that is measured rather than assumed.', '["search_text matches the whole record - at least title, desired_state, current_state, functional_requirements and acceptance_criteria - not only the title and desired state", "A multi-word search_text matches records containing its terms, rather than only records containing that exact substring", "query_requirements can return a bounded number of records, and can return the short form without every field of every match, so a broad search is usable at any set size", "A search that matched nothing is distinguishable in the response from a search that was never narrow enough to run, so an empty result says which case it is (R17)"]', '["Recall is a tracked number, measured by a harness in the test suite at 25, 250 and 1,000 stored requirements, not an assumption about the matcher", "A broad search''s response stays within a bound the tests assert, at every one of those set sizes"]', '["Any new index or table is a migration. lifecycle-schema.sql is the version 0 baseline and is never edited to change the schema", "Open: whether SQLite FTS5 is available in every environment the server runs in. If it cannot be relied on, the fallback is splitting search_text into terms and requiring each across the searched columns, which is slower but needs no virtual table", "Adding limit, offset or a short-form parameter to query_requirements costs client context on every request: tests/tool_surface_budget.json is raised in the same change (ADR-0002)", "An FTS table or index must stay current as records are edited, which means triggers or a write path through _apply_edit, not a rebuild anyone has to remember to run", "The recall harness is deterministic and needs no model: it is a fixture corpus plus a table of candidate phrasing to the requirement that covers it. The judgement that needs a model belongs in an eval, not in pytest", "tests/conftest.py fails any test that spawns gh or git, so the harness builds its corpus through the tools"]', NULL, '["Each of the 12 queries that returned nothing on 2026-09-28 returns the requirement that covers it, and that list is a test case rather than a note", "A two-word search_text finds a requirement whose record contains both words apart from each other", "The recall harness reports recall at 25, 250 and 1,000 stored requirements, and the suite fails when recall falls below the figure recorded for a set size", "A search matching every record in a 1,000-requirement corpus returns a response within the asserted size bound", "A requirement edited after it was stored is found by a term the edit introduced, with no rebuild step", "An empty search result states whether nothing matched or the filters excluded everything"]', '["Recall at 1,000 stored requirements is at or above the figure the harness records, and the figure is in the repository rather than in a conversation", "Reconciling this repository''s code against its own requirements proposes no requirement that duplicates a stored one - REQ-0012-FUNC-00''s validation metric, which cannot be met while 12 of 26 plausible searches return nothing"]', '["Vector embeddings or similarity search. The failures measured are exact terms the matcher cannot reach, not paraphrases it cannot understand", "Changing the reconcile prompt''s four buckets or its rule that a contradiction is reported and never resolved", "The model-in-the-loop eval of reconciliation judgement, which needs a prepared corpus with a ground-truth mapping and is not a pytest", "Search over tasks and architecture decisions, which have their own query tools and are not what reconciliation compares against", "A surface for reading results, which REQ-0005-INTF-00 covers"]', 'Claude (measured with Jeff Wikstrom, 2026-09-28)', '2026-09-28 16:42:54', '2026-09-28 16:42:54', 0, 0, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0003-TECH-00', 3, 'TECH', 0, '[R3] One relationships store and atomic migrations', 'Validated', 'P0', 'High', 'Traceability is the headline feature and currently destroys itself. Closes F-03, F-18, F-20. Evidence: claude-lifecycle-lab/NOTES.md.', 'Links are split between legacy tables (requirement_tasks, requirement_architecture, task_dependencies, requirement_dependencies, tasks.parent_task_id) and the unified relationships table, and handlers, views and triggers disagree (F-20). Migration 7 never succeeds on a fresh database (F-03). Once any relationship exists it runs half-way on restart: its DROP TABLEs commit outside the rolled-back transaction, permanently breaking trace_requirement, blocked items and dependency diagrams (F-18). Until this lands, do not create subtasks or relationships in this database; the first restart afterwards triggers the damage.', 'The relationships table is the only place links live, every migration is atomic, a failed migration stops the server, and databases already damaged are repaired automatically.', '["All link writers (create_task, parent tasks, create_architecture_decision, create_relationship) write only to relationships", "All readers (details, trace, export, diagrams, status, views, counter triggers) read only from relationships", "One consolidation migration copies legacy rows unconditionally, then removes legacy tables and tasks.parent_task_id with a table rebuild that preserves constraints", "Each migration runs in a single explicit transaction; a failure aborts startup with a message on stderr", "A repair migration restores views and triggers for databases left at schema 6 without task_dependencies or requirement_dependencies"]', NULL, NULL, NULL, '["Fresh database: create an ADR, a subtask and a dependency, restart, then trace_requirement, blocked items and the dependencies diagram all succeed", "claude-lifecycle-lab/snapshots/before-migration7.db and the damaged claude-lifecycle-lab/lifecycle.db both migrate to the latest schema without losing a link", "A migration with an injected failing statement leaves the schema version and tables unchanged", "tasks keeps its PRIMARY KEY, CHECK constraints and defaults after migration"]', NULL, NULL, 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-14 19:37:51', 6, 6, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0004-FUNC-00', 4, 'FUNC', 0, '[R8] Configurable workflow rules', 'Validated', 'P2', 'Medium', 'Closes F-13, F-24, F-25. Evidence: claude-lifecycle-lab/NOTES.md.', 'Dependencies are recorded but never enforced or warned about (F-24). A parent task can complete while subtasks are open, tasks can jump from Not Started to Complete, and Implemented is ungated (F-25). ADR status has no transition rules beyond R9''s Superseded link (F-13). R7 leaves a task waiting on an Abandoned dependency forever: only Complete releases it, and the dashboard lists the dependency without saying it was abandoned.', 'Each project chooses whether workflow rules are off, warn, or enforce.', '["LIFECYCLE_RULES chooses off, warn or enforce. warn is the default: it changes no outcome and explains the risk. enforce refuses the move and names what blocks it", "Rules cover unmet dependencies, a parent task completing with open subtasks, task skips and reopens (Not Started or Blocked straight to Complete, and reopening a Complete task), a requirement reaching Implemented with open tasks, and ADR status moves", "An abandoned dependency never counts as resolved: a task waiting on one stays blocked, and both the dashboard and the warning say which dependency was abandoned and how to clear it, by deleting the link or abandoning the waiting task too", "Warnings appear in the response text and in structuredContent, once per record moved"]', NULL, '["ADR-0002: no new tool. Strictness is the LIFECYCLE_RULES environment variable (off, warn, enforce), like LIFECYCLE_GITHUB, and warnings ride on the existing status tool responses", "Warn is the default so outcomes stay as they are today; only the explanation is new (owner decision, 2026-09-15)", "Task moves are flagged only for skips and reopens, not through a full transition map (owner decision, 2026-09-15)", "The Validated gate and the R9 Superseded rule stay always on: they are not part of the strictness setting"]', NULL, '["With LIFECYCLE_RULES unset, moving a task straight from Not Started to Complete still succeeds and says the task was never started", "In warn mode, starting a task with unmet dependencies succeeds and names them", "In enforce mode, the same call is refused with the blocking task IDs", "A task whose dependency is Abandoned is reported as waiting on an abandoned task, by name, on the dashboard and in the warning; in enforce mode starting it is refused until the link is deleted or the task is abandoned too", "With LIFECYCLE_RULES=off nothing is warned about and nothing is refused beyond the rules that already exist", "A list move reports its warnings per task"]', NULL, '["Superseding an ADR: R9 ties Superseded to a supersedes link", "Content edits: R6a already limits ADR edits to Proposed and requires a reason for requirement edits at Approved or later", "Cascading abandonment: abandoning a task never abandons the tasks it depends on, which may serve other work, nor the tasks depending on it, which may reach their goal another way (owner decision, 2026-09-15)"]', 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-16 01:02:58', 5, 5, 3, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0004-INTF-00', 4, 'INTF', 0, '[R23] get_details shows what the record actually has', 'Validated', 'P2', 'Low', 'get_details is what an agent reaches for to see one record whole, and CLAUDE.md describes it as giving full details with links and comments. Three fields make that description untrue. Two print storage artefacts, which is a papercut. The third omits links that exist, which is worse because it is silent: a requirement whose only link is to a decision looks unlinked, and nothing in the output lets the reader tell that case from a requirement that genuinely has no links.', 'get_details is the one tool that renders a whole record, and three things it shows do not survive the rendering. An ADR''s Authors prints the stored JSON, brackets and quotes included, while Deciders one line above prints a readable list: architecture_handler.py interpolates the authors column directly and passes deciders through _safe_json_loads. That is F-41, open since the R15 re-run on 2026-09-14. Consequences walks the stored dict and formats each value with a bare interpolation, which assumes the value is a string; a value that is a list of consequences prints as a Python repr, quote style and all, in details and in export_project_documentation alike. And requirement details lists only the tasks implementing it: R9 gave architecture and task details their design-link sections and the requirement end was never added, so a requirement with a decision against it and no tasks yet renders as though nothing links to it at all. All three were observed on 2026-09-17 reading REQ-0012-FUNC-00 and ADR-0005, records created minutes earlier in this tracker.', 'A record''s details show every field it holds and every link it is part of, in the form a person reads rather than the form the database stores.', '["ADR details print Authors as a readable list, the way Deciders already does", "Consequences render as text whether a value is a string or a list, in details and in export alike", "Requirement details show the decisions the requirement addresses and its links to other requirements, alongside the tasks implementing it", "A requirement with no links of a given kind shows no empty section for it, as architecture and task details already manage"]', NULL, '["No new tool and no new parameter: this is rendering only, so tests/tool_surface_budget.json is unchanged", "No schema change: every field involved is already stored and already reachable", "query_relationships already groups a record''s links by type and direction; requirement details should agree with it rather than invent a second grouping"]', NULL, '["An ADR created with a list of authors shows them comma-separated in details, with no brackets or quotes", "An ADR whose consequences hold lists shows each consequence on its own line in details and in exported documentation, with no Python repr", "A requirement addressing a decision names that decision in its details, and a requirement linked to another requirement names it and the link type", "A requirement with no tasks, no decisions and no requirement links shows none of those sections", "The existing design-link assertions for architecture and task details still pass unchanged"]', '["Reading ADR-0005 and REQ-0012-FUNC-00 in this tracker shows the authors, the consequences and the link between them with no storage artefacts and no missing section"]', '["Changing what is stored: consequences stay a free-form object", "Reworking trace_requirement, which already reaches a requirement''s architecture links by another route", "The relationship types that already have their own rendering: parent, supersedes and superseded_by"]', 'Claude (reading records created 2026-09-17)', '2026-09-18 11:18:29', '2026-09-28 16:09:48', 2, 2, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0004-TECH-00', 4, 'TECH', 0, '[R4] Honest errors and working read tools', 'Validated', 'P0', 'Medium', 'Agents can only correct course when failures are visible and specific. Closes F-10, F-12. Evidence: claude-lifecycle-lab/NOTES.md.', 'get_architecture_details fails on every ADR with "''sqlite3.Row'' object has no attribute ''get''" (F-12). Handler errors return isError=false with a generic ''[ERROR] Failed to ...'' message, and the real exception appears only in stderr (F-10).', 'Every read tool works on real data, and failures are flagged as errors with a message an agent can act on.', '["Fix sqlite3.Row .get() usage in architecture_handler.py and audit the other handlers for the same bug", "Handler errors set isError=true and include the exception message", "Domain refusals (gates, invalid transitions) keep their explanatory text and are also flagged as errors"]', NULL, NULL, NULL, '["get_architecture_details returns full details for a stored ADR", "An induced database error surfaces its message in the tool result with isError=true", "A test calls every read and query tool against a populated fixture database and asserts none errors"]', NULL, NULL, 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-15 16:14:11', 4, 4, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0005-FUNC-00', 5, 'FUNC', 0, '[R9] Design traceability and bulk transitions', 'Validated', 'P2', 'Low', 'Closes F-11, F-19, F-30 and the Superseded part of F-13. Evidence: claude-lifecycle-lab/NOTES.md, docs/tool-surface/usage-evidence.md.', 'A task can''t be linked to the ADR it implements: create_relationship rejects task -> architecture (F-19). Moving an ADR to Superseded leaves superseded_by NULL; no tool sets it and no relationship type links the two decisions (F-30, F-13). Status changes were 49% of calls in the original lab session and 47% in the re-run, one record and one step per call (F-11, docs/tool-surface/usage-evidence.md).', 'Design decisions trace to the work that implements them and to the decisions that replace them, and routine status moves take one call.', '["create_relationship accepts task implements ADR and ADR supersedes ADR", "A supersedes link sets the old decision''s superseded_by and moves it to Superseded; update_architecture_status refuses Superseded without one", "The three status tools accept a list of IDs and return a result for each", "update_requirement_status walks the allowed path to the requested status, logging each step; one call never passes through Approved"]', NULL, '["ADR-0002: bulk transitions extend the existing status tools instead of adding a tool; new parameters raise the tool surface budget in the same change", "ADR-0001: links are stored only in relationships"]', NULL, '["get_details on an ADR lists the tasks implementing it and the decision that supersedes it; get_details on a task lists the ADRs it implements", "Approving 8 Draft requirements through Under Review takes one call", "A batch with one refused ID still moves the others and names the refusal"]', NULL, '["Drawing the new links in diagrams (R13)", "Transition rules for the other ADR statuses (R8)"]', 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-15 21:26:43', 5, 5, 2, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0005-INTF-00', 5, 'INTF', 0, '[R24] A surface that renders what the tracker already returns', 'Draft', 'P2', 'Medium', 'The reconciliation that produced this requirement is its own evidence. Six of the seven things asked for already existed, and the person asking did not know. Bulk status moves have been Validated since R9 and were asked for as though new. A capability nobody can find is worth about what an absent one is worth, and no further tool work fixes it, because the tools are not the gap.', 'Every capability the UI discussion asked for already exists as a tool, and none of it is visible to a person without an agent in between. query_requirements and query_tasks return a text list plus structuredContent (R10). The three status tools accept a list of IDs and move each one (R9). query_relationships and get_details name a record''s links, and R23 added the requirement end of them. get_project_status is a dashboard whose signals R17 made trustworthy. create_architectural_diagrams draws the real relationship graph from stored links (R13). What none of them has is a reader: each returns text for an agent to relay, or a file someone opens by hand. The discussion asked for list views, status updates, visible links, bulk status moves, a project dashboard and a graph view - six capabilities that shipped - and one that did not, which is somewhere to see them.', 'A person can see and act on the tracker''s contents directly, without an agent relaying every call.', '["Status moves are made from the surface, including the list form the status tools already accept, and land through the tools so the database and the event log cannot tell them from a move made by an agent", "The surface reaches a record from the dashboard''s own sections - blocked and waiting work, work complete and decision pending, staleness - so the thing a signal names is the thing that can then be acted on", "Reading, filtering and navigating the records is a given rather than a deliverable here: REQ-0006-INTF-00 provides it as a generated file, and this requirement adds the ability to act on what is being read", "Whatever form the surface takes, it is a client of the MCP server and holds no lifecycle rule of its own"]', NULL, '["No new tools. Everything here is served by tools that already exist and already return structuredContent for exactly this purpose (R10, ADR-0002). A surface that needed new tools would be redesigning the server rather than reading it", "The server keeps no session. Server-side state is what sank the interview tools (F-08) and what R16 removed; this is a client of the MCP server, not a mode of it", "Every figure shown comes from the definition that already computes it - WORK_COMPLETE_WHERE, TASK_DEPENDENCIES_SQL, the staleness derivation - never a reimplementation, or the surface and the tools will disagree about the same record", "Open: what the acting surface is. A terminal client, a local web app, or a rendering inside the MCP client that already receives the structured responses. The read-only case is settled and is not one of these: REQ-0006-INTF-00 is a generated file with no connection at all, which is precisely why it cannot act", "Acting requires a live connection to the server, which is the whole of the difference in cost between this requirement and REQ-0006-INTF-00"]', NULL, '["A status move made in the surface is indistinguishable, in the database and in the event log, from the same move made through the tool", "Moving several records at once uses the list form the status tools already accept rather than a loop", "A refusal from a rule or a gate is shown as the server worded it, rather than reinterpreted", "Acting on a record is reachable from the dashboard signal that named it", "tools/list is unchanged: no tool is added by this requirement"]', '["The surface adds no tool and no schema change: tests/tool_surface_budget.json is untouched by the work that satisfies this requirement"]', '["Any change to the tools, the schema or the stored data", "Editing record content, which the update tools already do and which a first surface does not need", "Reading, listing, filtering and navigating the tracker, which REQ-0006-INTF-00 delivers without a server", "Replacing the MCP interface: an agent driving the tracker stays the primary path"]', 'Claude (reconciled from a UI discussion, 2026-09-19)', '2026-09-19 12:35:29', '2026-09-28 17:17:19', 0, 0, 1, 'derived-from-transcript');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0005-TECH-00', 5, 'TECH', 0, '[R6b] Curate the schema: expose useful fields, drop dead ones', 'Validated', 'P2', 'Medium', 'Tools match the data model, and the model stops advertising fields nobody can use. Refines R6 (REQ-0002-FUNC-00) and depends on R6a''s update tools. Evidence: claude-lifecycle-lab/NOTES.md F-09.', '30 columns across requirements, tasks and architecture cannot be set by any tool. Some are useful (out_of_scope, test_plan, definition_of_done); many belong to features that were never wired up (LLM decomposition, technical design documents).', 'Every remaining column is settable and readable through the tools, and columns with no use are gone.', '["Expose on create and update, and show in details and export: requirements out_of_scope, nonfunctional_requirements, technical_constraints, business_rules, validation_metrics; tasks test_plan, definition_of_done, implementation_plan; ADRs deciders, implementation_notes, validation_criteria, risk_assessment", "A migration drops: requirements decomposition_metadata, decomposition_source, complexity_score, scope_assessment, decomposition_level, architecture_review, gap_analysis, impact_of_not_acting, interface_requirements; tasks behavioral_specs, context_research; architecture executive_summary, system_design, key_decisions, performance_considerations, pros_cons", "Remove or rework the views, triggers and LLM decomposition code that depend on dropped columns (decomposition_candidates, requirement_hierarchy, decomposition-level triggers)"]', NULL, NULL, NULL, '["Each exposed field round-trips through create, update, details and export", "After the migration no dropped column exists, and every view and trigger works on a migrated copy of a real database", "No tool schema, handler or test references a dropped column"]', NULL, NULL, 'Claude, reviewed with heffrey78 (2026-09-14)', '2026-09-14 20:13:27', '2026-09-15 16:22:54', 4, 4, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0006-FUNC-00', 6, 'FUNC', 0, '[R11] Fields that get filled, and requirements that stay fresh', 'Validated', 'P3', 'Medium', 'Closes F-07, F-08 and F-15 by answering them with evidence rather than a rebuild, and targets what the tracker shows is actually missing: unfilled curated fields and requirement drift. Evidence: field counts measured 2026-09-16, claude-lifecycle-lab/NOTES.md.', 'Measured in this tracker on 2026-09-16. Guided capture is not the gap: every requirement has its core filled by calling create_requirement directly (18/18 current_state, desired_state, functional_requirements, acceptance_criteria, business_value), and the interview tools R16 removed produced worse records than typing them out (F-07, F-08, F-15). The gap is one field-set down: the curated fields R6b made reachable are mostly empty. nonfunctional_requirements 0/18, business_rules 0/18, validation_metrics 0/18; out_of_scope 5/18 and technical_constraints 7/18, both only because they were filled during a re-review. Tasks: definition_of_done 0/69, implementation_plan 4/69, test_plan 12/69. Decisions: validation_criteria 1/4, risk_assessment 1/4, implementation_notes 0/4. validation_metrics being empty is the one that bites, since it is where a measurable target like ''p95 under 50 ms'' would live. Requirements also drift: six needed their current_state re-verified against the code this session, and R14''s own finding was stale by the time it was reached. Separately, the LLM sampling code can never run: nothing calls set_mcp_client, so about 766 lines are dead (requirement_handler 418-692, architecture_handler 581-752, llm_decomposition_prompts.py).', 'The fields worth filling get filled, a client that wants guided capture has it without server-side conversation state, and a requirement shows when it was last checked against reality.', '["create_requirement and create_task warn when a record is thin for its kind, through the existing workflow rules: an NFUNC requirement with no validation_metrics, a P0 task with no test_plan, and the like", "An MCP prompt offers guided capture: it returns a template the client''s own model fills in and then passes to create_requirement in one call, with no session kept on the server", "A requirement shows when it was last verified against reality, and the dashboard lists the ones that have gone stale, the way it lists requirements changed since review", "The dead sampling, decomposition and diagram-suggestion code paths and llm_decomposition_prompts.py are removed"]', NULL, '["ADR-0002: no new tool. MCP prompts are a separate primitive and do not count against the tool budget, which is what removed the four interview tools (owner decision, 2026-09-16)", "Thin-record warnings reuse BaseHandler._rule_warnings from R8, so off, warn and enforce behave as they already do", "Staleness is derived from lifecycle events, not stored, the way changes_since_review is"]', NULL, '["Creating an NFUNC requirement with no validation_metrics succeeds and names the missing field; with LIFECYCLE_RULES=enforce it is refused", "Creating a P0 task with no test_plan warns the same way", "With LIFECYCLE_RULES=off neither warns", "prompts/list offers the capture prompt, and the requirement produced by following it has the curated fields filled", "A requirement whose content changed after its last verification shows as stale in its details and on the dashboard", "A requirement untouched since it was created is not reported as stale or as never verified, in its details or on the dashboard: creation starts the clock rather than tripping the alarm", "No handler references mcp_client or MCP sampling"]', NULL, '["Reviving the interview tools or any multi-step conversation with state on the server (F-08)", "Making any field mandatory: the rules warn, and a project chooses to enforce"]', 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-16 17:13:15', 5, 5, 3, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0006-INTF-00', 6, 'INTF', 0, 'A single-file viewer for the tracker that needs no server', 'Validated', 'P2', 'Low', 'The tracker is dogfooded on several projects at once, and on every one of them looking at the records means starting an agent and asking it to relay them. A file that opens by double-clicking removes the agent from reading, which is the cheap half of REQ-0005-INTF-00''s surface and the half that needs no session, no connection and no permissions. It also makes the record portable: a snapshot can be read on a machine that has never had lifecycle-mcp installed, which is what makes it shareable with someone who is not going to install an MCP server to see a requirement.', 'Reading the tracker requires an agent in between. Every read tool returns text for a model to relay: query_requirements and query_tasks return a list plus structuredContent (R10), get_details renders one record with its links from its own end (R23), get_project_status is a dashboard R17 made trustworthy, and export_project_documentation and create_architectural_diagrams write markdown and mermaid to files. What none of them is, is something a person opens and looks at. The exported documents are the closest thing and they are a set of flat files with no navigation between records, no filtering and no way to follow a link from a requirement to the decision against it. REQ-0005-INTF-00 already names this gap, and leaves open what the surface should be - a terminal client, a local web app, or a rendering inside the MCP client - each of which is something to install and keep running. A person who just wants to look at their own project''s records has nothing to open, and on a machine with no lifecycle-mcp installed at all, nothing is readable.', 'One HTML file, opened by double-clicking it, shows the whole tracker and lets a person navigate it, with nothing installed and nothing running.', '["A script generates one self-contained HTML file with the tracker''s contents embedded in it, read through SQLite read-only so the WAL is included without a checkpoint", "The file opens from the filesystem with no server, no install, no network and no build step, and works with networking switched off", "It holds no write path at all: no form, no request, no SQLite in the page. Opening it cannot change the database, because the database is not there", "Requirements, tasks and decisions are listed, filtered and opened individually, and a record shows every field it holds", "A record shows its links from its own end, in both directions, and each link is navigable to the record at the other end, as R23 made get_details do", "The dashboard''s sections - blocked and waiting work, work complete and decision pending, staleness, ready to start - appear as they do in get_project_status", "Every derived figure is computed by the generator from the server''s own definitions - WORK_COMPLETE_WHERE, TASK_DEPENDENCIES_SQL, the staleness derivation - and embedded as data. The page filters and presents; it never computes a lifecycle judgement of its own", "The page states when it was generated, so a reader can tell how stale the snapshot is", "A free-text filter searches every embedded field, not only the title and desired state"]', NULL, '["Data is embedded in the file rather than fetched from it. A browser will not fetch a local .db from a file:// page, so the alternative - SQLite compiled to WASM plus a file picker for the database - costs about a megabyte of wasm, an extra step for the reader, and handing over the database file itself. Embedding is chosen; the wasm variant is the fallback if reading the live database without regenerating ever matters more than opening one file", "The page is a snapshot and says so. Keeping it current means regenerating it, which is a Makefile target and can ride the same hook as the text dump", "Unlike the committed dump in REQ-0007-TECH-00, this output is deliberately not byte-deterministic: it states its own generation time, which a snapshot needs and a tracked file cannot have. The two can differ because this one is never committed", "Generated into exports/, which .gitignore already ignores. It is a build artefact, so no commit carries a diff of it", "No CDN, no external stylesheet, no web font: one file that works offline, from a USB stick, on a machine that has never seen this project", "The file embeds the whole tracker as plaintext, so it is exactly as sensitive as the database it came from and is not something to publish or attach casually", "The generator reads the handlers'' own definitions rather than copying their SQL, so the page and the tools cannot disagree about the same record. Open: whether it imports those constants from the package or drives a running server through the MCP client", "No new tool and no schema change: tests/tool_surface_budget.json is unchanged"]', NULL, '["Double-clicking the generated file in a file manager shows the tracker, with no server started, nothing installed and networking disabled", "The file contains no form, no fetch, no XMLHttpRequest and no SQLite, and the database is unchanged after the file has been opened and browsed", "Every requirement, task and decision in the database is reachable in the page, and each shows every field it holds", "Following a link from a requirement to a decision, and from a task to the requirement it implements, works in both directions without leaving the page", "The dashboard figures in the page match get_project_status against the same database, figure for figure", "The free-text filter finds a requirement by a term that appears only in its acceptance criteria - text query_requirements'' search_text cannot reach", "The page names its generation time", "A generated file placed on a machine with no Python, no uv and no lifecycle-mcp still opens and shows the same records", "exports/ is the output directory and no commit contains the generated file"]', '["Someone given only the HTML file can say what work is blocked, what is awaiting a decision and what is ready to start, without an agent and without asking the owner"]', '["Every kind of editing: status moves, comments, creating and amending records. That is REQ-0005-INTF-00, which needs a live connection and the tools, and is what this requirement deliberately leaves to it", "Live data. The page is a snapshot of the moment it was generated and never polls, reconnects or refreshes", "Hosting it anywhere, or any authentication. It is a local file whose only access control is the filesystem''s", "Writing a second definition of any lifecycle rule in JavaScript", "Comparing two trackers, or viewing several projects in one page", "Charts and visual analytics beyond the dashboard figures the server already computes"]', 'Claude (brainstorm with Jeff Wikstrom, 2026-09-28)', '2026-09-28 17:16:59', '2026-09-28 20:37:06', 6, 6, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0006-TECH-00', 6, 'TECH', 0, '[R18] The call log sees every call, including the refused ones', 'Validated', 'P2', 'Medium', 'Closes F-53 and repairs the evidence base R15 rests on. Every tool-surface decision and every call-mix figure across three dogfooding runs is drawn from this log, and it cannot see the calls where a client got the interface wrong - which is the most informative signal it could carry. Evidence: claude-lifecycle-lab/linkcheck/RUN-NOTES.md.', 'Measured in the linkcheck dogfooding run, 2026-09-16. A call refused by JSON-schema validation never reaches a handler, and only handlers write to LIFECYCLE_CALL_LOG, so the rejection leaves no trace. Passing a list to requirement_id returned "Input validation error: [...] is not of type ''string''"; the lab driver''s own client-side log recorded it with isError true, while server-calls.jsonl jumped straight from the preceding call to the next successful one. The run ended with 9 errors in the server log and 11 in the client''s, and only the client''s log can explain the difference. R15 (REQ-0002-NFUNC-00) asks its usage evidence to cover "failed or retried calls" and that functional requirement is therefore not met in substance; docs/tool-surface/usage-evidence.md and the 54%, 47% and 26% status-move figures all rest on the same blind instrument.', 'Every tool call the server receives appears in the call log, including calls refused before a handler runs, and the usage report tells a refusal apart from a handler error.', '["A call refused by input validation is logged with its tool name, its argument names, the rejection reason and isError true", "A call naming an unknown tool is logged the same way", "scripts/tool_usage_report.py counts validation rejections separately from handler errors and names the tools attracting them", "The log records enough to tell which parameter was refused, without recording argument values"]', NULL, '["ADR-0002: no new tool. Logging moves to where schema validation already runs, in server._route_tool_call", "No argument values in the log, as today: tool name, argument names, timing, isError and response size only"]', NULL, '["A call passing the wrong type for a declared parameter appears in the call log with isError true", "A call naming a tool that does not exist appears in the call log", "The usage report shows those calls under validation rejections rather than handler errors, and the totals add up to every call the server received", "docs/tool-surface/usage-evidence.md records that figures measured before this change undercount refused calls"]', '["For a session containing refused calls, the server-side call count equals the client-side call count", "Rejections and handler errors are reported as separate totals and sum to the number of calls with isError true"]', '["Rewriting the historical figures in docs/tool-surface/usage-evidence.md: they are marked as undercounts rather than re-derived from logs that cannot be recovered"]', 'Claude (linkcheck dogfooding run, 2026-09-16)', '2026-09-16 16:38:56', '2026-09-17 01:35:36', 3, 3, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0007-FUNC-00', 7, 'FUNC', 0, '[R12] Evidence and decision records on tasks', 'Validated', 'P3', 'Low', 'Closes F-26, F-31. Evidence: claude-lifecycle-lab/NOTES.md.', 'Verified on 2026-09-16. Test results, commits and files have no structured home: the tasks table has no column for them, so evidence goes into free-text comments (F-26), as it did in the lab where ''21 tests passing'' was a comment. Since R16 add_comment works on tasks and comments show in get_details and get_entity_history, but export_project_documentation contains no reference to comments at all, so none of it reaches the exported docs. Investigations and the decisions they lead to have nowhere structured to live (F-31). R7 set the precedent for this shape: blocked_reason is a task column that only update_task_status writes.', 'A task carries the commit and the evidence behind its status, and both reach the exported documentation.', '["update_task_status accepts an optional commit and an optional evidence summary, kept on the task the way blocked_reason is", "Both show in get_details and in get_entity_history''s record of the move", "export_project_documentation includes a task''s commit and evidence, and the comments already stored against records"]', NULL, '["ADR-0002: no new tool. Two parameters on update_task_status raise the budget in the same change (owner decision, 2026-09-16)", "commit and evidence are task columns that only update_task_status writes, as blocked_reason is (migration 17)"]', NULL, '["Completing a task with a commit and a test summary shows both in its details", "The exported task documentation contains that commit and summary", "The exported documentation contains comments made with add_comment", "A later status move without those fields leaves the recorded commit and evidence in place"]', NULL, '["A typed evidence table with one row per commit, file or test run: reconsider if free-text evidence proves too loose", "Attaching files or pull requests as first-class records"]', 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-16 11:36:46', 3, 3, 2, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0007-INTF-00', 7, 'INTF', 0, 'No refusal calls a link invalid that the server itself creates', 'Validated', 'P3', 'Low', '', 'create_relationship refuses a task''s parent link with "Invalid relationship: task -> task (parent)". The link is not invalid. _validate_relationship in relationship_handler.py holds a table of 17 permitted triples, and task to task parent is not among them, while create_task and update_task both create exactly that link through BaseHandler._link, which never consults the table. Of the six pairs the handlers create through _link, it is the only one the table refuses. The schema stores it, the prevent_circular_dependencies trigger guards it, CLAUDE.md documents child to parent as a direction convention, and migration 8 made relationships the only place parenthood lives. So the server creates the link, stores it, protects it and documents it, and one tool reports it as invalid. The two lists have no connection to each other, so nothing would notice if another pair drifted the same way. Found on 2026-09-28 writing a subtask into a test for REQ-0014-FUNC-00: the call failed, the message said the relationship was invalid, and the truth was that this tool does not make it.', 'A refused link either names the tool that does make it, or is not refused, and no message calls a link invalid that the server stores elsewhere.', '["create_relationship keeps refusing a task''s parent link, because re-parenting is more than a link: update_task routes it through _apply_edit, which bumps the revision and logs a field_edit event, and a link written straight into the table would move a task in the hierarchy with nothing in its history saying so", "The refusal says that, and names update_task''s parent_task_id as the way to do it, following R19''s rule that an error names what would have worked", "No refusal describes as invalid a link the server creates elsewhere: the wording distinguishes a link this tool does not make from a link that cannot exist", "The permitted table and the links the handlers actually create cannot drift apart unnoticed: a pair created through _link is either in the table or on an explicit list of pairs a dedicated tool owns, with the reason and the tool named, the way tests/test_schema_coverage.py already handles a column that no tool exposes", "Every pair that is permitted today keeps working unchanged"]', NULL, '["The alternative was to add the pair to the table and let create_relationship make parent links. It was rejected on the event log: _move_to_parent runs inside _apply_edit, so re-parenting is recorded as a field_edit on the task, and staleness, verification and changes-since-review all read those events. A link inserted directly would leave the hierarchy changed and the history silent", "Subtask numbering is not the reason. create_task derives a subtask''s TASK-NNNN-SS-00 id from its parent, but update_task re-parents without renumbering and says so - the ID never changes - so an id already is not a statement of parenthood and the link is already the source of truth", "The drift test needs the explicit-exception shape rather than a plain equality: task to task parent is deliberately absent from the table, so the test asserts every _link pair is permitted or listed as owned by a named tool", "No new tool and no schema change: tests/tool_surface_budget.json is unchanged", "prevent_circular_dependencies already guards parent cycles whichever way this is resolved, so nothing here weakens that"]', NULL, '["Asking create_relationship for a task''s parent link is refused with a message naming update_task and its parent_task_id parameter, and not with the word invalid", "A test fails when a pair any handler creates through _link is neither in _validate_relationship''s table nor on the list of pairs a dedicated tool owns", "That list names, for each entry, the tool that owns the pair and why create_relationship does not make it", "update_task''s parent_task_id still re-parents a task, and still records the move as a field_edit in the task''s history", "Every relationship type that create_relationship accepts today still works, including the reversed forms it normalizes", "A genuinely impossible pair - a requirement superseding a task, say - is still refused as invalid, because it is"]', '["No pair the handlers create through _link is reported by any tool as invalid"]', '["Renumbering a task''s id when it is re-parented. update_task already says the ID never changes, and changing that would break every reference to the old id", "Adding relationship types or pairs beyond reconciling the two lists that already exist", "delete_relationship, which is generic and removes a parent link today without the same inconsistency", "The requirement to requirement pairs, which are in the table and work"]', 'Claude (found writing a test for REQ-0014-FUNC-00, 2026-09-28)', '2026-09-28 18:03:30', '2026-09-28 18:23:37', 2, 2, 0, 'derived-from-code');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0007-TECH-00', 7, 'TECH', 0, 'The tracker travels with the repository as a text dump', 'Implemented', 'P1', 'Medium', 'The tracker is the project''s record of why the code is the way it is, and it is the one part of this project not in version control. Losing that disk loses 27 requirements, 5 decisions and 534 events, and no commit currently says which requirement a change satisfied at the moment it landed. Text in the repository also makes the record reviewable and restorable: a requirement that changed shows up in a diff next to the code that changed with it, which is the same argument that put the roadmap in the tracker rather than in a notebook.', 'The tracker''s contents are in no version control at all. .gitignore ignores *.db, *.db-shm and *.db-wal, so lifecycle.db - 27 requirements, 89 tasks, 5 decisions, 154 relationships and 534 lifecycle events - exists only on one disk, while the repository it describes is fully tracked. Committing the file as it stands would not fix it: database_manager.py:59 sets PRAGMA journal_mode=WAL, so a copy of lifecycle.db captures only what has been checkpointed. Measured 2026-09-28: the main file held 26 requirements and 531 events with an mtime of Sep 22, while the same database read through SQLite held 27 and 534. This session''s own work - REQ-0003-NFUNC-00, the R23 validation and the R21 comment - was in the -wal file and in no other place. A binary database is also the wrong thing to track: it produces no reviewable diff, cannot be merged, and rewrites every byte on every commit.', 'Every commit carries a deterministic text dump of the tracker, so the project record is versioned alongside the code it describes and can be restored from any clone.', '["A script exports the tracker to one text file of INSERT statements, read through SQLite read-only rather than by copying the database file, so the WAL is included without a checkpoint step", "The dump carries data and the schema_version rows only, and no CREATE TABLE, CREATE TRIGGER or CREATE VIEW: lifecycle-schema.sql plus migrations.py stay the single definition of the schema", "A restore script rebuilds a usable database from the dump alone: it initialises an empty database so the migrations run, then loads the dump in one transaction. It needs no running server, no MCP client and no existing database", "Restore refuses to overwrite a database that already holds records. It names what it would destroy, by table and count, and proceeds only on an explicit flag from the caller", "Restore can build into a path the caller names, so a rebuild can be inspected and compared before it replaces anything", "Restore refuses a dump whose schema_version rows are ahead of the migrations present in the checkout, rather than loading records the code cannot read", "Restore verifies itself: the table counts after loading match the counts the dump contains, or it fails and leaves no partly loaded database behind", "The export is byte-identical when run twice against an unchanged database: rows are ordered by primary key and nothing about the export itself - a timestamp, a hostname, a row count - is written into the file", "A local hook in .pre-commit-config.yaml regenerates the dump on every commit, stages it when its content changed, and does nothing at all when it did not, so a commit that touched no tracker data carries no dump diff", "The hook exports the repository''s own database rather than whatever LIFECYCLE_DB points at, so a session pointed at another database cannot overwrite the committed dump with a different tracker", "README documents what the file is, that the database itself is local and deliberately ignored, how to export and how to rebuild one from a clone, and that the dump is generated and never hand-edited"]', NULL, '["Determinism is the requirement the rest depends on. An export that varies between identical runs puts a diff in every commit, which is the signal that always fires and teaches the reader to ignore it (roadmap R17)", "Never copy the database file. Reading through SQLite with file:lifecycle.db?mode=ro sees the WAL and takes a consistent read snapshot even while the server is running; copying the file is the bug this requirement exists to fix", "Restore runs the migrations and then loads data. It never executes DDL from the dump, because that is what keeps the schema single-sourced in lifecycle-schema.sql and migrations.py, and the schema_version rows in the dump are what tell it where those migrations left off", "The load is one transaction, so a failure rolls back and leaves no half-populated database - the same discipline migrations.py already applies to each migration", "No CI can verify the export is current. The database is local by design, so nothing in a pull request can tell that a dump is stale, and the hook is the only enforcement point. That makes it an honour-system rule like the configurable workflow rules, and ADR-0004 is the precedent for accepting one deliberately", "The full dump measures 451,062 characters today. .pre-commit-config.yaml already runs check-added-large-files, whose default limit is 500 KB, so the data-only dump has to stay under it or the limit has to be raised deliberately", "lifecycle_events is 534 of the 809 stored rows and grows without bound. It cannot be dropped from the dump to save space: staleness, verification and changes-since-review are all derived from events rather than stored in a column", "The hook goes in the existing local hooks section of .pre-commit-config.yaml, not a hand-installed .git/hooks/pre-commit that a fresh clone would silently lack", "tests/conftest.py fails any test that spawns git or gh, so the round-trip test exercises the export and restore scripts against a temporary database and never the hook itself", "scripts/ holds the repository''s existing tooling and is where these belong; the Makefile gets targets so export and restore are runnable without a commit"]', NULL, '["Changing the tracker and then committing leaves a dump at HEAD containing that change, with no checkpoint, restart or manual export step", "Running the export twice against an unchanged database produces byte-identical files", "A commit that changes only code produces no diff in the dump", "Export, import into a freshly migrated database, and export again produces a file identical to the first, with the same row counts in every table and the same schema_version rows", "A clone containing only the dump yields a working tracker whose requirement, task, decision, relationship and event counts match the database it came from", "The restored database is usable with no further step: the server starts against it and a tool call returns the restored records", "Restore run against a database that already holds records exits non-zero, writes nothing, and names the counts it would have destroyed", "Restore run with the explicit flag against that same database replaces it and reports what it replaced", "Restore of a dump whose schema_version is ahead of the checkout''s migrations is refused, naming both versions, and nothing is written", "A restore interrupted partway leaves no database that a later run or the server would treat as complete", "The dump contains no CREATE TABLE, CREATE TRIGGER or CREATE VIEW statement", "Pointing LIFECYCLE_DB at a different database and committing does not change the dump of the repository''s tracker", "README has a section covering what the file is, how to export it, how to rebuild a database from it, and that it is generated"]', '["After one roadmap pass, the dump at HEAD restores to a database whose table counts and schema_version rows match the live one", "Across that pass, no commit contains a dump diff that is not explained by a tracker change in the same commit"]', '["Making the dump the source of truth. The database stays authoritative and the dump is a derivative; a text file that had to be edited to change a requirement would bypass the tools, the rules and the event log", "Committing the binary database, in any form, including alongside the dump", "Restoring individual records or a subset of the tracker. Restore rebuilds a whole database from a whole dump; recovering one requirement from an old dump is a manual job", "Migrating a dump backwards into an older schema than it was written from", "Resolving a merge conflict inside the dump. Two divergent trackers produce a conflict that is visible, which is already better than a binary file, but reconciling them by hand is not a workflow this requirement provides", "Concurrent editing by several people, which the single local database does not support and which this does not change", "Backups anywhere outside the repository", "Pruning or compacting the event log, which would be a change to what the tracker stores rather than to how it travels"]', 'Claude (brainstorm with Jeff Wikstrom, 2026-09-28)', '2026-09-28 16:51:41', '2026-09-28 22:50:36', 4, 4, 1, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0008-FUNC-00', 8, 'FUNC', 0, '[R13] Diagrams that show structure', 'Validated', 'P3', 'Low', 'Closes F-16, F-17. Evidence: claude-lifecycle-lab/NOTES.md.', 'Verified on 2026-09-15 against export_handler.py. The architecture diagram draws ADR boxes with no edges. full_project hangs records off category nodes, silently keeps the first 10 requirements, 10 tasks and 5 ADRs, draws at most 20 edges and only requirement-to-task ones, and includes deprecated records (only styling them grey). The requirements, tasks and dependencies diagrams cut titles at 30 characters without escaping mermaid punctuation. directory_structure returns a hard-coded src/docs/tests stub that has nothing to do with the project. Every call writes a new timestamped file into exports/ (F-16, F-17). Since the finding was written, R9 added two more link types the diagrams ignore: task implements ADR, and ADR supersedes ADR.', 'Diagrams show the real graph from relationships, completely unless a limit is asked for, at stable paths.', '["Edges come from relationships: requirement to task (implements), requirement to ADR (addresses), task to ADR (implements), ADR to ADR (supersedes), task to task (parent and dependencies)", "Nothing is dropped silently: everything is drawn unless a limit is requested, and whatever is left out is stated in the response", "Deprecated requirements and decisions are left out by default, and the response says so", "Each diagram type writes to a stable filename that overwrites the previous render", "directory_structure is removed rather than returning a hard-coded stub", "Node labels keep enough of the title to be readable and escape the punctuation that breaks mermaid"]', NULL, '["ADR-0002: no new tool. A limit parameter on create_architectural_diagrams raises the budget in the same change; removing directory_structure lowers it", "Breaking for anyone parsing timestamped diagram filenames or calling directory_structure: the CHANGELOG records both"]', NULL, '["The full-project diagram shows requirement-to-ADR and requirement-to-task edges for every non-deprecated record, with no limit given", "A task implementing an ADR and an ADR superseding another are drawn as edges", "With a limit, the response says how many of each kind were drawn and how many were left out", "Two calls of the same diagram type leave one file, not two", "directory_structure is refused as an unknown diagram type, naming the types that exist", "A title containing quotes or brackets renders without breaking the diagram"]', NULL, NULL, 'Claude (lifecycle field test, 2026-09-14)', '2026-09-14 16:37:15', '2026-09-16 01:41:27', 4, 4, 3, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0009-FUNC-00', 9, 'FUNC', 0, '[R6a] Edit records safely', 'Validated', 'P2', 'Medium', 'Agents can fix and refine plans as work reveals reality without bypassing review. Refines R6 (REQ-0002-FUNC-00). Deferred by owner decision: a strict mode where edits reopen review belongs in R8 as a configurable rule; a requirement ''supersedes'' relationship (for a newly discovered requirement that replaces an earlier one) belongs in R9. Evidence: claude-lifecycle-lab/NOTES.md F-09, F-14, F-27.', 'Requirements, tasks and ADRs cannot be edited after creation; only status (and a task''s assignee) can change. Unknown fields are silently dropped because tool schemas allow additional properties (F-09). No record can be deleted, and lifecycle_events is written but no tool reads it (F-14). Task structure cannot be reshaped (F-27).', 'Agents correct records in a single call, every change is attributable and visible, and approval keeps its meaning without extra round trips.', '["update_requirement, update_task and update_architecture change content fields in place in one call", "Every change is recorded in lifecycle_events with field, before and after values, actor and reason", "Edits to a requirement at Approved or later require a reason and set a ''changed since approval'' marker shown in details, trace and project status; re-approval clears it", "ADR content is editable only while Proposed; otherwise the error points to superseding the ADR", "update_task can change a task''s parent link; task IDs never change", "Every create and update tool rejects unknown fields (additionalProperties: false)", "Draft requirements, Not Started tasks and Proposed ADRs can be deleted when nothing depends on them (no tasks, subtasks, dependencies or refining links); their own links are removed with them; anything else is refused with the reason", "get_entity_history returns creation, edits, status changes and comments for a record in order", "Records carry an integer revision incremented on every update; updates accept an optional if_revision and fail without writing when it is stale"]', NULL, NULL, NULL, '["An acceptance-criteria edit to an Approved requirement succeeds in one call with a reason, appears in details, trace and export, and is flagged as changed since approval until re-approved", "The same edit without a reason is refused with an error saying a reason is required", "Editing an Accepted ADR is refused with guidance to supersede it", "Moving a subtask to a new parent keeps its ID, and both parents list their subtasks correctly", "Passing an unknown field to any create or update tool returns an error naming the field", "Deleting an unlinked Draft requirement succeeds; deleting a requirement that has tasks is refused with the reason", "get_entity_history shows before and after values for every edit, in order, alongside status changes and comments", "An update with a stale if_revision fails and leaves the record unchanged"]', NULL, NULL, 'Claude, reviewed with heffrey78 (2026-09-14)', '2026-09-14 20:13:27', '2026-09-15 16:22:52', 9, 9, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0010-FUNC-00', 10, 'FUNC', 0, '[R17] Signals worth trusting on the dashboard', 'Validated', 'P2', 'Low', 'Closes F-43 and F-52. A badge that fires on every record from day one, and a headline reading 0% at the moment the work finishes, both teach the reader to stop reading the dashboard. Evidence: claude-lifecycle-lab/linkcheck/RUN-NOTES.md.', 'Measured in the linkcheck dogfooding run, 2026-09-16. Two shipped signals report the wrong thing at the moment that matters most. A requirement written seconds ago already carries "Never verified: nobody has commented on this or moved it since it was written" and appears on the dashboard under Not Verified Since Last Change, so a fresh project wears the badge on every record from day one; the R11 tests asserted the message appears and never that it should not (F-43). At the other end, the instant the last task of a project completed, get_project_status reported "Tasks Overview: Complete 8 (100.0%)" and "Requirements Overview: Approved 6 (100.0%) - Avg 100.0% complete" directly above "Requirements Completion: 0.0% (0/6)", because a requirement counts as complete only at Implemented or Validated and nothing had moved them. The tracker held every fact needed to notice - it knew each requirement''s tasks were all Complete and that the requirement was still Approved - and surfaced none of it (F-52). The ready filter answers "which task now?" all run; nothing answers "which record now?".', 'A signal fires when it carries information and stays quiet otherwise: creating a record starts its verification clock rather than tripping the alarm, and a requirement whose work is finished is surfaced as the next thing needing a decision.', '["Creation starts the verification clock: a record untouched since it was created is not reported as never verified, in its details or on the dashboard", "Staleness is judged against an age threshold rather than the bare absence of a verifying event, and the report says how long it has been", "The staleness line in get_details states the two facts it holds rather than inventing a third: when the content changed, and when it was last checked. It never labels the last-checked time as the moment the record went stale, which is what it does today. get_project_status already renders this correctly and is the wording to follow", "The changed-since-review line carries the time of the edit it reports", "get_project_status names every requirement whose linked tasks are all Complete but whose status is earlier than Implemented, as work awaiting a decision", "query_requirements can filter for those requirements, the way query_tasks filters for ready to start", "An empty ready-to-start result says which case it is: no tasks remain, every remaining task is blocked, or the only startable work is already in progress"]', NULL, '["ADR-0002: no new tool. The requirement filter is a query_requirements parameter and the new dashboard section rides on get_project_status; the tool surface budget rises in the same change", "Staleness stays derived from lifecycle events rather than a stored column, as R11 established, and ordering uses event ids because timestamps are second-resolution", "Staleness and changed-since-review stay two signals on two lines rather than one merged line, and the dashboard keeps both sections. They answer different questions: a comment clears staleness but not re-review, and a Draft requirement can go stale but can never be changed since review, which covers reviewed statuses only. Only the wording was ever at fault (owner decision, 2026-09-16)"]', NULL, '["A requirement created and left alone is not listed as never verified, in get_details or on the dashboard", "A requirement untouched past the staleness threshold is listed, and the entry says how long since it was last verified", "A stale requirement''s details give the time its content changed and the time it was last checked, and no label claims it has been stale since the moment it was checked", "A requirement edited at a reviewed status shows the time of that edit on its changed-since-review line", "A Validated requirement edited in place shows both warnings; commenting on it afterwards clears the staleness warning and leaves the review warning standing", "A project whose tasks are all Complete and whose requirements are all Approved names those requirements on the dashboard instead of reporting 0% complete", "query_requirements returns exactly those requirements when asked for the ones whose work is done", "Asking for ready-to-start tasks when the only startable task is already In Progress says so, rather than answering that no tasks were found"]', '["No record is reported as never verified within the staleness threshold of its own creation timestamp", "On a project with every task Complete and no requirement past Approved, the dashboard names all such requirements and the count matches the number of requirements in that state"]', '["Moving requirements automatically when their tasks complete: the tracker prompts and the person decides", "Changing what counts as a verification event (a comment or a status move), which R11 settled"]', 'Claude (linkcheck dogfooding run, 2026-09-16)', '2026-09-16 16:38:43', '2026-09-17 21:19:00', 4, 4, 5, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0011-FUNC-00', 11, 'FUNC', 0, '[R20] Amending an accepted decision', 'Validated', 'P3', 'Medium', 'Closes F-51. Without a middle weight between an invisible comment and a whole superseding ADR, accepted decisions drift into disagreeing with the systems they describe, which is the failure mode decision records exist to prevent. Evidence: claude-lifecycle-lab/linkcheck/RUN-NOTES.md.', 'Observed in the linkcheck dogfooding run, 2026-09-16. That project''s ADR-0001 records that the thread pool defaults "to something modest like 16". The benchmark the same ADR called for measured 32, and the shipped code now says 32, so the accepted record contradicts the system it describes. ADRs are editable only while Proposed (R6a), which is correct - a decision record that can be quietly rewritten is worthless as a record - so the available remedies are a comment, which renders below the decision rather than with it and which a reader scanning the Decision field will miss, or a superseding ADR, which is heavy machinery for correcting one number and buries the change under a second document. Nothing in between exists.', 'A decision carries dated amendments that render with the decision they correct, leaving the original text intact and visible.', '["update_architecture records an amendment against an Accepted decision: dated, attributed, carrying its reason, appended rather than replacing any decision field", "The original decision text is never altered by an amendment; the record shows the original and the correction together", "get_details renders amendments with the decision, in order, marked as later corrections rather than as the original text, and export_project_documentation carries them", "get_entity_history shows an amendment as its own event, distinct from a field edit and from a comment"]', NULL, '["ADR-0002: no new tool. Amendments ride on update_architecture, which already owns decision content and already refuses edits once a decision leaves Proposed (owner decision, 2026-09-16)", "R6a''s immutability rule is unchanged: update_architecture still refuses to rewrite an Accepted decision''s content fields, and an amendment is a distinct operation rather than a relaxation of that rule", "Where an amendment lives is open - a column on architecture, or a distinct lifecycle event the way staleness and changes-since-review are derived from events. It has to survive export and render with the decision, which rules out anything that only get_details can reach"]', NULL, '["Amending an Accepted ADR through update_architecture leaves the original Decision text byte-identical and shows the amendment with it in get_details", "A reader of the exported documentation sees the amendment without following a link or scrolling to the comments", "Amending a Proposed ADR is refused with guidance to edit it instead", "Editing an Accepted decision''s content fields is still refused, with guidance naming both amendment and supersession", "An amendment appears in get_entity_history as its own event"]', '["A decision with an amendment shows both the original and the correction in details and in export, with no edit recorded against the original text"]', '["Relaxing the immutability of accepted decision text", "Replacing the supersedes mechanism: a genuine change of direction still warrants a new decision"]', 'Claude (linkcheck dogfooding run, 2026-09-16)', '2026-09-16 16:39:21', '2026-09-17 21:19:00', 3, 3, 3, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0012-FUNC-00', 12, 'FUNC', 0, '[R21] Reconcile requirements from an existing source', 'Implemented', 'P2', 'Medium', 'Makes it possible to adopt a body of work that predates the tracker, which is the condition every real project starts in and the condition this one is in about itself. The extraction is the client model''s job and it is already good at it; what is missing is the discipline of comparing before creating. Without that, importing existing work either duplicates the requirements already there or quietly overwrites them.', 'Requirements enter this tracker one at a time through create_requirement, typed by someone who already knows the requirement is new. Nothing compares a body of text against what is already stored. Two sources go unserved as a result: a conversation transcript about requirements, where some of what was said restates an existing requirement, some amends one and some is genuinely new; and an existing codebase, whose behaviour is a requirement set nobody ever wrote down. This tracker is its own example. Its 22 requirements are the R1-R20 roadmap - the delta work of one improvement pass - and not one of them says what the server does. Pasting a transcript today produces duplicates or nothing, because the only available move is to create.', 'Text about requirements - a transcript, a design document, a reading of the code - is reconciled against what is already stored and comes back sorted into new, amended, already covered and contradicted.', '["A prompt guides the client''s model to read the stored requirements first, then classify each candidate it found in the source as new, an amendment to a named requirement, already covered, or in conflict with a stored one", "An amendment names the requirement it amends and the fields it changes, so it lands through update_requirement rather than as a second near-duplicate record", "A contradiction - the source asserts something a stored requirement denies - is reported and not resolved; resolving it is the reader''s job", "A requirement derived from a source rather than stated by a person is marked as derived and is created in Draft, whatever the model''s confidence", "The prompt takes the source text as an argument and serves a transcript and a reading of the code alike, because the two differ only in where the text came from"]', NULL, '["ADR-0002 and R11: the comparison is a prompt, not a tool. The server keeps no session and performs no extraction; the client''s model reads the source. Server-side intelligence is exactly what sank the interview tools (F-07, F-08) and what R16 removed", "Derived provenance is a field on requirements, not a status. A new status would break requirement_path() and REQUIREMENT_TRANSITIONS, which are always-on rules outside the configurable set (ADR-0004). More importantly, a derived requirement that arrives already approved destroys the one property that makes a requirement worth storing: that it can disagree with the code", "Any new column must be settable through create and update and visible in details and export, or listed in tests/test_schema_coverage.py with its reason", "Matching candidates against stored requirements uses query_requirements'' existing search_text. At this size the model reading the list beats similarity search; embeddings stay out until the set is large enough that reading it is impractical", "Code is evidence of behaviour and silent about intent. CLAUDE.md''s ''Don''t add a marker column or an acknowledgement tool (owner decision, TASK-0019)'' is a requirement no reading of the code recovers, so docs and decision records are sources beside the code rather than after it"]', NULL, '["A transcript that restates one stored requirement, amends a second and introduces a third produces exactly one create and one update, and names the restated one as already covered", "A derived requirement is distinguishable from a stated one in get_details and in export_project_documentation", "Reconciling a source against an empty tracker creates requirements and says the set was empty, rather than reporting everything as new without having looked", "Running the prompt over this repository''s code and CLAUDE.md produces candidate requirements for the server''s own behaviour that a person can review in one sitting", "tools/list is unchanged by this requirement: no new tool appears"]', '["Over a transcript prepared with known overlaps, reconciliation proposes no requirement that duplicates one already stored"]', '["Parsing code on the server. An AST gives structure without meaning, and a requirement is meaning; the client''s model reads the code", "Applying amendments without review. The output is proposed changes, and Draft plus the Approved gate is where a person still signs off", "Similarity search or vector embeddings over the requirement set", "Drift between a requirement and the code that implements it once both exist, which REQ-0013-FUNC-00 covers"]', 'Claude (brainstorm with Jeff Wikstrom, 2026-09-17)', '2026-09-17 22:45:35', '2026-09-18 11:28:30', 2, 2, 1, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0013-FUNC-00', 13, 'FUNC', 0, '[R22] Requirements that point at code and notice when it moves', 'Draft', 'P2', 'Medium', 'Turns staleness from a timer into evidence. R17''s rule is that a signal which always fires teaches the reader to ignore it, and a 14-day clock fires on every requirement eventually whether or not anything happened. A drift signal fires only when the code under a requirement actually moved, which is the case that is worth a person''s attention and the case the calendar currently cannot see.', 'A requirement''s relationship to the code that satisfies it is carried only through its tasks, and a task''s evidence (migration 17) is a commit reference and free text recorded once, at the moment that task moved. Nothing points from a requirement to the files or symbols that implement it, so nothing can tell that the code beneath it has changed since anyone last looked. What exists instead is a calendar: requirement_handler.verification derives when a requirement was last checked and stale_requirements lists those unchecked for longer than LIFECYCLE_STALE_AFTER, 14 days by default. That fires for a requirement nobody happened to touch over a quiet fortnight, and stays silent for one whose implementation was rewritten yesterday.', 'A requirement names the code that implements it, and the tracker reports when that code has changed since the requirement was last checked.', '["A requirement carries anchors: the paths and symbols that implement it, each with the content hash recorded when that anchor was last confirmed", "Drift is derived rather than stored: an anchor whose current content differs from the recorded hash, on a requirement whose last verification predates that change", "query_requirements reports the drifted set alongside the filters it already carries", "get_project_status names drifted requirements where it already names blocked, work-complete and stale ones, and both read one definition the way WORK_COMPLETE_WHERE serves the dashboard and the query together", "An anchor whose path or symbol no longer exists is reported as unresolved and named, rather than dropped or silently re-bound to something else"]', NULL, '["No new tool. The filter rides on query_requirements the way work_complete did (TASK-0077), and tests/tool_surface_budget.json is raised in the same change", "Anchors key on path and symbol name, not line numbers, so ordinary edits above a symbol do not break them. A rename is expected to break an anchor, and breaking loudly is the required behaviour", "Open: whether the server hashes the working tree itself or takes the hash from the caller. Either way it must work without spawning git or gh, which tests/conftest.py fails any test for", "The recorded hash has to be stored, but drift itself is computed at read time, following staleness and changes-since-review, which are derived from lifecycle events rather than kept in a column", "Any new column must be settable through create and update and visible in details and export, or listed in tests/test_schema_coverage.py with its reason"]', NULL, '["Changing a file a requirement anchors to puts that requirement in the drifted set, and moving its status or commenting on it clears it", "A requirement with no anchors is absent from the drifted set rather than reported as clean", "Renaming an anchored symbol reports that anchor as unresolved and names it, rather than reporting the requirement as drifted or as clean", "The drifted filter and the dashboard section never disagree, because both read one definition", "An empty drifted result says which case it is: nothing anchored, or nothing changed"]', '["Over one roadmap pass, every requirement reported as drifted had code beneath it that had in fact changed"]', '["Vector embeddings or textual similarity between a requirement and the code", "Parsing code on the server: an anchor is a name and a hash, not a syntax tree", "Deciding what a drifted requirement should now say. The report is the deliverable and the rewrite is the reader''s", "Anchors on tasks or ADRs", "Replacing the calendar staleness signal, which still covers requirements that have no anchors"]', 'Claude (brainstorm with Jeff Wikstrom, 2026-09-17)', '2026-09-17 22:45:50', '2026-09-17 22:45:50', 0, 0, 0, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0014-FUNC-00', 14, 'FUNC', 0, 'Abandoned work does not block validation forever', 'Validated', 'P1', 'Medium', 'Abandoning a task is the honest way to record that work was dropped, and today it costs the requirement its ability to ever reach Validated. That makes the honest move the expensive one and rewards the two dishonest alternatives: deleting the link, which erases that the work was ever planned, or marking abandoned work Complete, which writes a false status change into the event log that staleness and verification then read as evidence. It is also the same inconsistency ADR-0005 identified in the other direction - the tracker punishing an accurate negative result - and the fix is the one that decision already argues for: use the statuses that exist and let a record say what happened.', 'Abandoned is one of the five task statuses in the schema, and the Validated gate does not know it exists. The gate in requirement_handler.py selects a requirement''s implementing tasks WHERE t.status != ''Complete'' and refuses the move with \"All tasks must have ''Complete'' status before requirement validation\", so an Abandoned task blocks validation permanently: abandoning work means deciding it will not be done, and the gate will only accept Complete. The two ways out are both damaging. Deleting the link loses the record that the work was ever planned, and marking an abandoned task Complete puts a false status change in lifecycle_events, which is where staleness, verification and changes-since-review are all derived from. The rest of the system already disagrees with the gate: status_handler.py mentions Abandoned eight times and task_handler.py nine, counting open work as NOT IN (''Complete'', ''Abandoned'') and reporting \"No tasks remain: every task is Complete or Abandoned\", while requirement_handler.py mentions it not once. _dependency_reasons already shows the intended shape, separating unfinished dependencies from abandoned ones and giving the abandoned case its own advice. The counters have the same blind spot: _LEAF_TASKS_COMPLETED in migrations.py counts only t.status = ''Complete'', so one abandoned task holds tasks_completed below task_count forever, which keeps the requirement out of the dashboard''s Work Complete, Decision Pending section and out of query_requirements(work_complete=True), and understates its progress percentage for good.', 'A requirement whose remaining work was abandoned rather than finished can be validated, and says so.', '["A requirement whose implementing tasks are all Complete or Abandoned, with at least one Complete, can move to Validated", "The always-on gate narrows to the case with no evidence: a requirement with tasks but not one Complete is still refused, naming the abandoned tasks and pointing at Deprecated rather than Validated", "A requirement with a task that is Not Started, In Progress or Blocked is refused exactly as it is today", "The abandoned case becomes a configurable rule through BaseHandler._rule_warnings: off checks nothing, warn moves the requirement and names the abandoned tasks in the response text and structuredContent, enforce raises StatusRefused before anything is written", "The Implemented gate stops counting Abandoned as open work. It is a warning rather than a block, but a warning that can never be cleared is the signal that always fires, so an abandoned task is named as abandoned and not reported as a task that is not Complete", "tasks_completed keeps meaning Complete, so no progress figure reports work that was abandoned as work that was done", "Whether a requirement has open work is derived rather than stored - no counter column, no trigger change and no migration - so it cannot go stale and existing databases need nothing done to them", "One definition of being ready to validate - tasks exist, at least one is Complete, none is open - is read by the Validated gate, the dashboard''s Work Complete, Decision Pending section and query_requirements(work_complete=True), so all three agree about the same requirement", "A requirement whose every task is Abandoned is absent from Work Complete, Decision Pending, because nothing was completed and the decision it awaits is to deprecate it rather than to validate it", "Both the refusal and the warning name the tasks and their statuses, in the style the gate''s message already uses"]', NULL, '["No migration and no new column. WORK_COMPLETE_WHERE is a WHERE fragment on requirements, so having no open work is expressible as a correlated NOT EXISTS over relationships and tasks - the same choice CLAUDE.md records for staleness and changes-since-review, which are derived from events rather than kept in a column", "The leaf rule keeps one home. The subquery reuses the same is-leaf condition migration 16''s counter triggers use, rather than restating it, so a parent task is still counted through its subtasks (F-22)", "This narrows the always-on gate rather than removing it. The always-on set stays the Validated gate, R9''s Superseded link and the requirement transition map (ADR-0004); what moves into the configurable rules is the abandoned case alone", "Two definitions would let the gate and the dashboard disagree about one requirement, which is the failure WORK_COMPLETE_WHERE was introduced to prevent", "No new tool and no new parameter: tests/tool_surface_budget.json is unchanged by this requirement", "An enforce refusal raises StatusRefused before the transaction opens, so a refused multi-ID status move leaves nothing written for that record"]', NULL, '["A requirement with one Complete and one Abandoned implementing task moves to Validated, and the response names the abandoned task", "Under LIFECYCLE_RULES=enforce that same move is refused and nothing is written; under off it succeeds with no mention of the abandoned task", "A requirement whose every implementing task is Abandoned is refused, the message names those tasks and says to deprecate it instead", "A requirement with a Not Started, In Progress or Blocked task is refused with the same message it gives today", "A requirement with an abandoned task and no open tasks moving to Implemented is not told that tasks are not Complete; the abandoned task is named as abandoned", "A requirement whose only unfinished tasks are abandoned appears in the dashboard''s Work Complete, Decision Pending section and in query_requirements(work_complete=True)", "A requirement whose every task is Abandoned appears in neither", "That requirement''s progress figure reports its Complete tasks over its total and does not read 100%", "The gate, the dashboard section and the work_complete filter never disagree about whether one requirement is ready to validate, because all three read one definition", "No migration is added: schema_version is unchanged by this work, and an existing database needs no recomputation", "tests/tool_surface_budget.json is unchanged"]', '["No requirement in the tracker is unvalidatable for any reason other than work that is still open"]', '["A column recording why a task was abandoned. The warning names which tasks were abandoned, not why; a reason column would have to be settable through the tools and visible in details and export, or listed in tests/test_schema_coverage.py", "Changing what Abandoned means anywhere else: task dependencies, subtask rules and the open-work counts already treat it as finished and stay as they are", "Deprecating an all-abandoned requirement automatically. The refusal names Deprecated as the move to make; making it is the reader''s decision", "Reopening an abandoned task, which the task status tool already allows and which the workflow rules already comment on"]', 'Claude (brainstorm with Jeff Wikstrom, 2026-09-28)', '2026-09-28 17:06:15', '2026-09-28 18:26:58', 3, 3, 1, 'stated');
INSERT INTO "requirements" ("id", "requirement_number", "type", "version", "title", "status", "priority", "risk_level", "business_value", "current_state", "desired_state", "functional_requirements", "nonfunctional_requirements", "technical_constraints", "business_rules", "acceptance_criteria", "validation_metrics", "out_of_scope", "author", "created_at", "updated_at", "task_count", "tasks_completed", "revision", "origin") VALUES ('REQ-0015-FUNC-00', 15, 'FUNC', 0, 'Projects: groups of requirements with a stated purpose', 'Implemented', 'P1', 'Medium', 'A person reading a group of requirements learns what the group is about from the tracker itself. Epics, roadmap items and layers can be managed in lifecycle without encoding them in titles.', 'Requirements are one flat set. Nothing groups them into an epic, a roadmap item or a layer, and nothing records what a group is for. Roadmap membership lives in title prefixes like [R17]. Exported documents list requirements by type with no owning concept, so whoever hands an export on writes the summary by hand afterwards, outside the tracker.', 'Requirements can be organised into projects. Each project carries a stored purpose that is canonical to it, and exported documents open with that purpose rather than with a summary composed after the fact.', '["A project is a record with a title and a required purpose, and optional success criteria and out-of-scope lists", "A requirement can belong to several projects at once", "Membership can be set when a project is created, when a requirement is created, and changed later", "Requirements, tasks and decisions can be queried by project", "Export of the whole tracker opens with every project, its purpose and its requirements", "Export of one project holds only its requirements, their tasks and their decisions, and opens with its purpose", "Diagrams can be drawn for one project", "The capture and reconcile prompts place a new requirement in its projects", "Project details show its purpose, its requirements and how far they have got", "The dashboard lists active projects with their progress", "Projects take comments, history, short IDs and delete like other records", "Projects travel in the tracker dump and appear in the viewer"]', NULL, '["relationships stays the only place links are stored (ADR-0001)", "The requirement transition map and its gates are not changed (ADR-0004)", "Tool surface growth is recorded in tests/tool_surface_budget.json in the same change"]', NULL, '["create_project refuses a blank purpose and an unknown requirement, writing nothing", "A requirement in two projects lists both in its details and in export", "update_project changes content and membership in one revision, logged in history", "export_project_documentation(project_id) writes three documents titled with the project and opening with its stored purpose, holding none of another project''s records", "A tracker with no projects exports and reports exactly as before", "Migration 19 keeps every link, every comment id and the task-count triggers on an existing tracker", "A dump holding projects restores and exports back byte for byte", "The viewer reads a tracker from before migration 19"]', NULL, '["Scoping get_project_status to one project", "A tool that lists projects, including Closed ones", "Nested projects", "Tasks or decisions as direct members of a project"]', 'Jeff Wikstrom', '2026-10-01 23:12:33', '2026-10-01 23:53:38', 7, 7, 1, 'stated');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0001-00-00', 1, 0, 0, 'Pin mcp[cli]>=1.10,<2 and refresh uv.lock', 'Complete', 'P0', 'XS', 'As someone installing lifecycle-mcp, I want a dependency range that actually works so the server starts.', '["pyproject.toml constrains mcp[cli] to >=1.10,<2 and uv.lock is regenerated", "`uv tool install --force .` then tools/list returns all tools", "Install docs show the plain command"]', NULL, NULL, NULL, NULL, '2026-09-14 16:37:15', '2026-09-14 16:59:17', '2026-09-14 16:59:17', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
