INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0013-00-00', 13, 0, 0, 'Smoke-test every read tool against a populated database', 'Complete', 'P1', 'S', 'As a maintainer, I want every read path exercised on real rows. Depends on: TASK-0011-00-00, TASK-0012-00-00.', '["A fixture database with requirements, tasks, ADRs and links is built by the test", "Every get_*, query_*, trace, status, export and diagram tool succeeds on it"]', NULL, NULL, NULL, NULL, '2026-09-14 16:37:15', '2026-09-14 16:59:23', '2026-09-14 16:59:23', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
