INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0015-00-00', 15, 0, 0, 'Stop the test suite from creating real GitHub issues', 'Complete', 'P0', 'S', 'As the repo owner, running pytest must never write to GitHub. On 2026-09-14 two local runs from the repo root with gh authenticated created 342 real issues (#1802-#2184); 1,049 "Test Task" issues exist in total since 2025-07-10. Do this before any other task that runs the suite.', '["An autouse conftest fixture disables GitHubUtils (or sets LIFECYCLE_GITHUB off) for every test", "A test asserts no gh subprocess is spawned during create_task and update_task_status", "GitHub behaviour is covered only by mocked tests", "Running the full suite from the repo root with gh authenticated creates zero issues (check gh issue list before/after)"]', NULL, NULL, NULL, NULL, '2026-09-14 16:38:25', '2026-09-14 16:59:58', '2026-09-14 16:59:58', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0016-00-00', 16, 0, 0, 'Migration 9: edit-tracking schema', 'Complete', 'P1', 'S', 'As the edit tools, I need somewhere to record revisions, per-field changes and approval drift.', '["requirements, tasks and architecture gain revision INTEGER NOT NULL DEFAULT 0", "lifecycle_events gains field and reason columns; existing events are untouched", "requirements gains a changed-since-approval marker that defaults to not set", "Migration is atomic and covered by tests/test_migrations.py, including a migrated copy of a real database"]', NULL, NULL, NULL, NULL, '2026-09-14 20:17:55', '2026-09-14 20:33:34', '2026-09-14 20:33:34', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0017-00-00', 17, 0, 0, 'Shared edit engine in BaseHandler', 'Complete', 'P1', 'M', 'As a handler, I want one code path that applies edits safely so every update tool behaves the same.', '["One transaction: check optional if_revision, apply changed fields, bump revision, write one lifecycle_events row per changed field with before, after, actor and reason", "A stale if_revision fails without writing anything and says which revision is current", "Unchanged values produce no event and no revision bump", "JSON list/object fields are validated and stored consistently with create"]', NULL, NULL, NULL, NULL, '2026-09-14 20:17:55', '2026-09-14 20:48:04', '2026-09-14 20:48:04', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
