INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0019-00-00', 19, 0, 0, 'update_requirement with reason and changed-since-approval marker', 'Complete', 'P1', 'M', 'As an agent refining a plan, I want to correct a requirement in one call without silently undermining its approval.', '["update_requirement edits content fields in one call; the change appears in details, trace and export", "At Approved or later a reason is required; without one the call is refused with that message", "A requirement shows as changed since last review when a content edit comes after its latest status change; shown in get_requirement_details, trace_requirement and get_project_status", "The next status transition clears the marker and its comment serves as the acknowledgement; no stored marker and no acknowledgement tool"]', NULL, NULL, NULL, NULL, '2026-09-14 20:17:55', '2026-09-14 22:19:57', '2026-09-14 22:19:57', NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0020-00-00', 20, 0, 0, 'update_task with parent moves and requirement relinking', 'Complete', 'P2', 'M', 'As an agent reshaping work, I want to edit tasks and move subtasks without breaking references.', '["update_task edits content fields (title, priority, effort, user_story, acceptance_criteria, assignee) in one call", "Changing parent_task_id replaces the parent link; the task ID never changes; self-parenting and cycles are refused", "Changing requirement_ids replaces implements links and applies the same approval gate as create_task", "Both old and new parents list their subtasks correctly; requirement task counters stay correct"]', NULL, NULL, NULL, NULL, '2026-09-14 20:17:55', '2026-09-14 22:19:59', '2026-09-14 22:19:59', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0021-00-00', 21, 0, 0, 'update_architecture editable only while Proposed', 'Complete', 'P2', 'S', 'As a reviewer, I want accepted decisions to stay as accepted and changes to go through supersession.', '["update_architecture edits content fields while the ADR is Proposed", "Any other status is refused with guidance to create a superseding ADR", "Edits are logged with before/after values like other records"]', NULL, NULL, NULL, NULL, '2026-09-14 20:17:55', '2026-09-14 22:20:01', '2026-09-14 22:20:01', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
