INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0024-00-00', 24, 0, 0, 'R6a acceptance test through the MCP layer and docs', 'Complete', 'P2', 'S', 'As a maintainer, I want R6a''s acceptance criteria pinned by one end-to-end test and documented.', '["One test file walks every R6a acceptance criterion through the MCP server layer", "README and CLAUDE.md list the new tools and the edit, reason and acknowledgement rules", "CI green"]', NULL, NULL, NULL, NULL, '2026-09-14 20:17:55', '2026-09-14 23:13:44', '2026-09-14 23:13:44', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0025-00-00', 25, 0, 0, 'Expose the curated fields on create, update, details and export', 'Complete', 'P2', 'M', 'As an agent writing a plan, I want to record scope limits, test plans and decision details the schema already has room for.', '["Requirements: out_of_scope, nonfunctional_requirements, technical_constraints, business_rules, validation_metrics", "Tasks: test_plan, definition_of_done, implementation_plan", "ADRs: deciders, implementation_notes, validation_criteria, risk_assessment", "Each field round-trips through create, update, details and export"]', NULL, NULL, NULL, NULL, '2026-09-14 20:17:55', '2026-09-14 23:25:45', '2026-09-14 23:25:45', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0026-00-00', 26, 0, 0, 'Rework views and triggers that depend on decomposition columns', 'Complete', 'P2', 'S', 'As the migration, I need nothing to reference the columns about to be dropped.', '["decomposition_candidates view and the decomposition-level triggers are removed; requirement_hierarchy no longer selects decomposition columns", "The circular-parent check on requirement parent links still works", "Handler code that read or wrote decomposition columns is removed"]', NULL, NULL, NULL, NULL, '2026-09-14 20:17:55', '2026-09-14 20:33:37', '2026-09-14 20:33:37', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0027-00-00', 27, 0, 0, 'Migration 10: drop dead columns', 'Complete', 'P2', 'M', 'As the data model, I want to stop advertising fields nobody can set.', '["Drops requirements decomposition_metadata, decomposition_source, complexity_score, scope_assessment, decomposition_level, architecture_review, gap_analysis, impact_of_not_acting, interface_requirements; tasks behavioral_specs, context_research; architecture executive_summary, system_design, key_decisions, performance_considerations, pros_cons", "Drops idx_requirements_decomposition first; uses ALTER TABLE DROP COLUMN inside the migration transaction", "Migrating copies of the lab and roadmap databases succeeds with every view and trigger working"]', NULL, NULL, NULL, NULL, '2026-09-14 20:17:55', '2026-09-14 20:48:04', '2026-09-14 20:48:04', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0028-00-00', 28, 0, 0, 'Schema coverage test', 'Complete', 'P2', 'S', 'As a maintainer, I want CI to fail if a column becomes unreachable or a tool writes a column that no longer exists.', '["A test compares each table''s columns with the create/update tool schemas: every non-system column is settable, and no schema property lacks a column", "The system-column allowlist is explicit in the test"]', NULL, NULL, NULL, NULL, '2026-09-14 20:17:55', '2026-09-15 00:42:38', '2026-09-15 00:42:38', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0029-00-00', 29, 0, 0, 'Tool surface budget checked in CI', 'Complete', 'P2', 'S', 'As a maintainer, I want CI to fail when the tool surface grows past a recorded budget, so every increase is a deliberate decision.', '["A test lists tools through the MCP layer and measures tool count and tools/list JSON size per handler", "Budgets are recorded in one file in the repository; exceeding one fails with the handler, its measured size and its budget named", "Raising a budget means changing that file in the same change", "scripts/tool_surface_report.py prints tool count and definition size per handler and per tool"]', NULL, NULL, NULL, NULL, '2026-09-15 00:44:31', '2026-09-15 11:17:18', '2026-09-15 11:17:18', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0030-00-00', 30, 0, 0, 'Record tool usage from real agent sessions', 'Complete', 'P2', 'M', 'As a maintainer reviewing the tool surface, I want per-tool call counts, errors and retries from real sessions rather than guesses.', '["An opt-in LIFECYCLE_CALL_LOG path makes the server append one JSON line per tool call (tool, argument names, duration, isError, response size) for any MCP client; off by default and never written to stdout", "A script summarises one or more call logs: calls per tool, tools never called compared with the current tools/list, errors, and calls repeated within a short window", "Evidence from at least one agent session driving a real project with the current tools, reported alongside the earlier lab log (322 calls across 25 tools)"]', NULL, NULL, NULL, NULL, '2026-09-15 00:44:33', '2026-09-15 11:17:20', '2026-09-15 11:17:20', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0031-00-00', 31, 0, 0, 'Inventory and classify every tool', 'Complete', 'P2', 'S', 'As the owner, I want every tool classified with evidence before deciding what to fold or remove.', '["Every registered tool is classified keep, fold, register-only-when-enabled or remove, with its usage and definition-size evidence", "Each fold names the tool and parameter that keeps the capability", "The inventory states the tool count and definition size the target would reach", "Overlaps with R10, R11 and R13 are called out so each tool changes once"]', NULL, NULL, NULL, NULL, '2026-09-15 00:44:36', '2026-09-15 11:17:21', '2026-09-15 11:17:21', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0032-00-00', 32, 0, 0, 'ADR for the target tool surface', 'Complete', 'P2', 'S', 'As the owner, I want the target tool surface and the rules for future tools decided once and recorded, so R16 and later roadmap items follow them.', '["An architecture decision addressing REQ-0002-NFUNC-00 records the target surface from the inventory and principles for future tools (for example one tool per operation, conditional registration for opt-in features, how budgets move)", "The owner accepts the ADR before any tool is removed or renamed"]', NULL, NULL, NULL, NULL, '2026-09-15 00:44:39', '2026-09-15 01:45:58', '2026-09-15 01:45:58', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0033-00-00', 33, 0, 0, 'Status tools store the literal text CURRENT_TIMESTAMP in updated_at (F-42)', 'Complete', 'P2', 'S', 'As anyone reading a record, I want its Updated time to be a real timestamp after a status change, not the text CURRENT_TIMESTAMP.', '["update_requirement_status, update_task_status and update_architecture_status set updated_at to the current time instead of binding the string ''CURRENT_TIMESTAMP'' (architecture_handler.py, requirement_handler.py, task_handler.py)", "A migration repairs stored rows whose updated_at is the literal string, using the record''s latest lifecycle event time or else created_at", "A test changes an architecture decision''s status through the MCP layer and asserts updated_at is a parseable timestamp", "After migrating, ADR-0001 and ADR-0002 in the tracker and the 5 ADRs in the lab database show real dates"]', NULL, NULL, NULL, NULL, '2026-09-15 13:39:12', '2026-09-15 16:14:11', '2026-09-15 16:14:11', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0034-00-00', 34, 0, 0, 'ID-based tools: get_details, delete_record and add_comment', 'Complete', 'P2', 'M', 'As an agent, I want one tool per ID-only operation across record types, so I choose tools by operation rather than by record type.', '["get_details(entity_id) returns the same report as get_requirement_details, get_task_details or get_architecture_details did for that ID; those three tools are removed", "delete_record(entity_id) applies the same rules and refusals as delete_requirement, delete_task and delete_architecture; those three tools are removed", "add_comment(entity_id, comment, author) records a comment on a requirement, task or architecture decision that shows in its details and history; add_architecture_review is removed", "A malformed or unknown ID is refused with the expected ID formats named", "Tests that used the removed tools use the replacements, and the tool surface budget is lowered to the measured size"]', NULL, NULL, NULL, NULL, '2026-09-15 13:40:27', '2026-09-15 14:20:30', '2026-09-15 14:20:30', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0035-00-00', 35, 0, 0, 'One query_relationships for all link queries', 'Complete', 'P2', 'S', 'As an agent, I want a single tool that answers every link question, from one record''s links to the whole graph.', '["query_relationships(entity_id, relationship_type, direction, entity_types), all optional, covers get_entity_relationships (one record''s links) and query_all_relationships (every link, optionally by entity type); both tools are removed", "With entity_id, direction selects incoming, outgoing or both links (default both)", "Tests cover one record''s links filtered by type and direction, and the full graph filtered by entity type; the tool surface budget is lowered to the measured size"]', NULL, NULL, NULL, NULL, '2026-09-15 13:40:31', '2026-09-15 14:20:32', '2026-09-15 14:20:32', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0036-00-00', 36, 0, 0, 'GitHub sync: one tool, registered only when enabled', 'Complete', 'P2', 'S', 'As an agent on a project without GitHub integration, I don''t want tool definitions for a feature that is switched off.', '["sync_github_tasks(task_id) syncs one task, or every linked task when task_id is omitted; sync_task_from_github and bulk_sync_github_tasks are removed", "With LIFECYCLE_GITHUB unset or off, tools/list omits sync_github_tasks and a call to it is refused as an unknown tool", "A test confirms the tool is listed with LIFECYCLE_GITHUB=on without running gh; the budget test measures the default surface and the budget is lowered to it"]', NULL, NULL, NULL, NULL, '2026-09-15 13:40:35', '2026-09-15 14:20:33', '2026-09-15 14:20:33', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0037-00-00', 37, 0, 0, 'Remove the interview tools and the diagrams tool''s interactive parameter', 'Complete', 'P2', 'S', 'As an agent, I don''t want tools listed that produce only placeholders.', '["start_requirement_interview, continue_requirement_interview, start_architectural_conversation and continue_architectural_conversation are no longer listed or routed, and InterviewHandler plus any code only it uses are removed", "create_architectural_diagrams no longer accepts interactive, and diagram suggestions no longer point to interactive mode", "Tests for the removed tools are removed, README and CLAUDE.md no longer document them, and the tool surface budget is lowered to the measured size"]', NULL, NULL, NULL, NULL, '2026-09-15 13:40:38', '2026-09-15 14:20:34', '2026-09-15 14:20:34', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0038-00-00', 38, 0, 0, 'Trim tool and parameter descriptions', 'Complete', 'P2', 'S', 'As an agent, I want tool descriptions that state what I need to call the tool correctly and nothing more.', '["Every remaining tool and parameter description is reviewed, and total description text drops as measured by scripts/tool_surface_report.py", "Descriptions keep the rules agents need: a reason at Approved or later, Proposed-only architecture edits, what delete refuses, GitHub being opt-in", "The tool surface budget is lowered to the measured size"]', NULL, NULL, NULL, NULL, '2026-09-15 13:40:41', '2026-09-15 14:20:35', '2026-09-15 14:20:35', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0039-00-00', 39, 0, 0, 'Changelog, docs and the R16 surface check', 'Complete', 'P2', 'S', 'As a client maintainer, I want one place that tells me which tools were removed or renamed and what replaces each.', '["CHANGELOG.md lists every removed or renamed tool with its replacement", "README and CLAUDE.md tool lists and counts match tools/list", "tools/list shows 27 tools with GitHub off and 28 with it on, and tests/tool_surface_budget.json matches the measured surface", "The MCP handshake smoke test, the R6a acceptance test and the schema coverage test pass"]', NULL, NULL, NULL, NULL, '2026-09-15 13:40:44', '2026-09-15 14:20:37', '2026-09-15 14:20:37', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0040-00-00', 40, 0, 0, 'Structured results and a quiet create_requirement', 'Complete', 'P2', 'S', 'As an agent, I want tool results as data I can read directly, and a create response without noise.', '["A handler can return text plus a dict, and the server sends the dict as structuredContent next to the text", "No tool declares an outputSchema (ADR-0002 budget rule), checked by a test", "create_requirement drops the LLM-unavailable warning and returns one status line plus structured id, type, title, priority and status"]', NULL, NULL, NULL, NULL, '2026-09-15 14:28:24', '2026-09-15 16:14:12', '2026-09-15 16:14:12', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0041-00-00', 41, 0, 0, 'Query tools return structured results; fold the *_json tools', 'Complete', 'P2', 'M', 'As an agent or UI, I want one query tool per record type that gives me both a readable list and the full records as data.', '["query_requirements, query_tasks and query_architecture_decisions return structured results with the full matching records, JSON fields parsed, as the *_json tools did", "query_requirements_json, query_tasks_json and query_architecture_decisions_json are removed, and each pair shares one query implementation", "Tests and docs use the remaining tools, and the tool surface budget is lowered to the measured size"]', NULL, NULL, NULL, NULL, '2026-09-15 14:28:28', '2026-09-15 16:14:14', '2026-09-15 16:14:14', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0042-00-00', 42, 0, 0, 'Project status returns structured metrics; fold get_project_metrics', 'Complete', 'P2', 'S', 'As an agent or UI, I want the project dashboard and its metrics from one call.', '["get_project_status returns the metrics get_project_metrics returned (by status, priority and assignee, totals, completion percentages) as structured data next to its report", "get_project_metrics is removed", "Tests and docs use get_project_status, and the tool surface budget is lowered to the measured size"]', NULL, NULL, NULL, NULL, '2026-09-15 14:28:31', '2026-09-15 16:14:15', '2026-09-15 16:14:15', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0043-00-00', 43, 0, 0, 'Create and update tools return structured IDs and revisions', 'Complete', 'P2', 'S', 'As an agent, I want the ID and revision of what I just created or changed without parsing text.', '["create_task and create_architecture_decision return the new record''s id and status as structured data", "update_requirement, update_task and update_architecture return the id, the changed fields and the new revision as structured data", "Status tools return the id and the old and new status as structured data"]', NULL, NULL, NULL, NULL, '2026-09-15 14:28:34', '2026-09-15 16:14:16', '2026-09-15 16:14:16', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
