INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0045-00-00', 45, 0, 0, 'Status tools accept a list of IDs with a result per ID', 'Complete', 'P2', 'M', 'As an agent moving several records through the same state, I make one status call instead of one per record.', '["update_requirement_status, update_task_status and update_architecture_status accept requirement_ids, task_ids or architecture_ids instead of the single ID", "Each ID moves independently; the text lists every ID and structuredContent carries results with moved and refused counts", "Some refused: WARNING and the rest still move; all refused: isError", "Passing both ID forms or neither is refused by name", "A single-ID call returns what it returns today"]', '["Extract each handler''s status change into a per-ID function that raises StatusRefused", "A BaseHandler helper runs one or many and builds the response", "Schemas gain the *_ids arrays and require only new_status; raise the budget"]', '["tests/test_bulk_status.py: all moved, partly refused, all refused, both or neither ID forms, single-ID shape unchanged"]', NULL, NULL, '2026-09-15 17:04:20', '2026-09-15 21:26:43', '2026-09-15 21:26:43', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0046-00-00', 46, 0, 0, 'update_requirement_status walks the allowed path to the requested status', 'Complete', 'P2', 'M', 'As an agent approving a Draft requirement, I ask for Approved and the server steps through Under Review for me, recording both steps.', '["Draft to Approved in one call passes through Under Review and logs two status changes", "Approved to Validated in one call passes through Ready and Implemented", "A path through Approved is refused, naming Approved as the stop: Draft to Validated is still an invalid transition", "Implemented to Deprecated passes through Ready, never Validated", "Gates apply to the whole move: Ready to Validated with an open task is refused and the requirement stays Ready", "A target with no allowed path is refused, naming the statuses it can move to", "The text and structuredContent show the path of a multi-step move; one-step results are unchanged"]', '["Breadth-first search over the transition map", "Apply every step in one transaction so each status UPDATE fires the logging trigger"]', '["tests/test_bulk_status.py: multi-step path, atomic refusal, no path"]', NULL, NULL, '2026-09-15 17:04:20', '2026-09-15 21:26:43', '2026-09-15 21:26:43', NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0047-00-00', 47, 0, 0, 'Supersedes and task-implements-ADR links (migration 14)', 'Complete', 'P2', 'M', 'As an agent changing a design mid-implementation, I link the new ADR to the one it replaces and the tasks to the decision they implement.', '["create_relationship accepts task implements ADR in either order, stored task -> ADR", "create_relationship accepts ADR supersedes ADR (new -> old); in one transaction the old ADR gets superseded_by and moves to Superseded", "Refused: an ADR superseding itself, an ADR that is already superseded, and a superseding ADR that is itself Superseded", "update_architecture_status refuses Superseded without a supersedes link and refuses leaving Superseded while one exists", "Deleting a supersedes link clears superseded_by", "Migration 14 rebuilds relationships with the new type, keeps its views, triggers and indexes, and back-fills links from existing superseded_by values"]', NULL, '["tests/test_design_links.py", "tests/test_migrations.py: migration 14 on a populated version-13 database"]', NULL, NULL, '2026-09-15 17:04:20', '2026-09-15 21:26:43', '2026-09-15 21:26:43', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
