INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0062-00-00', 62, 0, 0, 'Stable filenames, an honest limit, and no directory_structure', 'Complete', 'P3', 'S', NULL, '["Each diagram type writes {type}-diagram.mmd or .md, overwriting the previous render, so two calls leave one file", "A limit parameter caps each record kind; the response says how many of each kind were drawn and how many were left out", "Without a limit nothing is capped and nothing is omitted silently", "directory_structure is gone from the enum and refused as an unknown type, naming the types that exist", "The tool surface budget moves in the same change: the limit parameter adds, the removed type subtracts"]', NULL, '["tests/test_diagrams.py: repeated calls leave one file; limit reports omissions; directory_structure refused"]', NULL, NULL, '2026-09-16 01:17:27', '2026-09-16 01:41:18', '2026-09-16 01:41:18', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
