INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0064-00-00', 64, 0, 0, 'Short IDs resolve everywhere a record ID is taken', 'Complete', 'P3', 'M', 'As someone typing an ID into a tool, I write REQ-12-FUNC instead of REQ-0012-FUNC-00 and it finds the same record.', '["A resolver in BaseHandler turns REQ-12-FUNC, TASK-12, TASK-12-1 and ADR-4 into stored IDs", "Full stored IDs pass through unchanged", "An unknown alias is refused as no record matching it; an ambiguous one is refused naming the candidates", "Every tool that takes an ID uses it: details, delete, comment, history, the relationship tools, the update and status tools, trace, and the requirement and parent links on create_task", "No tool gains a parameter, so the tool surface budget does not move"]', NULL, '["tests/test_short_ids.py: each shape, full IDs, unknown and ambiguous aliases, and one alias through each tool family"]', NULL, NULL, '2026-09-16 01:43:31', '2026-09-16 11:05:12', '2026-09-16 11:05:12', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0065-00-00', 65, 0, 0, 'Count leaf tasks only in requirement progress (migration 16)', 'Complete', 'P3', 'M', 'As someone reading a requirement, its task count matches the work rather than counting a parent and its subtasks separately.', '["The task_count and tasks_completed triggers ignore tasks that have a parent link", "Migration 16 rebuilds those triggers and recomputes the stored counters, touching no status", "A requirement whose only task is split into two Complete subtasks reports 2 of 2 tasks complete", "Details, trace_requirement and the dashboard all show the corrected numbers"]', NULL, '["tests/test_leaf_progress.py through the MCP layer", "tests/test_migrations.py style check of migration 16 on a populated version-15 database"]', NULL, NULL, '2026-09-16 01:43:31', '2026-09-16 11:05:12', '2026-09-16 11:05:12', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0066-00-00', 66, 0, 0, 'R14 acceptance test, docs and changelog', 'Complete', 'P3', 'S', NULL, '["tests/test_r14_acceptance.py covers each R14 acceptance criterion through the MCP layer", "README and CLAUDE.md describe the short ID forms and that progress counts leaf tasks", "CHANGELOG records the counter change as a correction, with the migration that applies it to existing databases"]', NULL, NULL, NULL, NULL, '2026-09-16 01:43:31', '2026-09-16 11:05:12', '2026-09-16 11:05:12', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0067-00-00', 67, 0, 0, 'Carry a commit and evidence on a task''s status move (migration 17)', 'Complete', 'P3', 'M', 'As someone completing a task, I record the commit and the test result with the move, and they stay on the task.', '["Migration 17 adds tasks.commit_ref and tasks.evidence", "update_task_status accepts optional commit and evidence and stores them, as it does blocked_reason", "A later move that omits them leaves the stored values alone", "get_details shows both on the task", "The schema coverage test lists both among the columns the status tools maintain", "The budget rises for the two parameters in the same change"]', NULL, '["tests/test_evidence.py through the MCP layer, plus migration 17 on a populated version-16 database"]', NULL, NULL, '2026-09-16 11:07:46', '2026-09-16 11:36:16', '2026-09-16 11:36:16', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0068-00-00', 68, 0, 0, 'Export evidence and comments', 'Complete', 'P3', 'S', 'As someone reading the exported docs, I see the commit and evidence behind each task, and the comments people left.', '["Exported task documentation includes a task''s commit and evidence when set", "Exported documentation includes the comments stored against requirements, tasks and decisions", "Records without either export exactly as they do now"]', NULL, '["tests/test_evidence.py: export contains the commit, the evidence and a comment"]', NULL, NULL, '2026-09-16 11:07:46', '2026-09-16 11:36:16', '2026-09-16 11:36:16', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0069-00-00', 69, 0, 0, 'R12 acceptance test, docs and changelog', 'Complete', 'P3', 'S', NULL, '["tests/test_r12_acceptance.py covers each R12 acceptance criterion through the MCP layer", "README and CLAUDE.md describe the commit and evidence fields and that export carries comments", "CHANGELOG records the two parameters, the migration and the fuller export"]', NULL, NULL, NULL, NULL, '2026-09-16 11:07:46', '2026-09-16 11:36:16', '2026-09-16 11:36:16', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0070-00-00', 70, 0, 0, 'Warn when a new record is thin for its kind', 'Complete', 'P3', 'M', 'As someone writing a requirement, I am told which field that kind of record usually needs before it goes stale in the tracker.', '["create_requirement warns when a record is thin for its kind: an NFUNC requirement without validation_metrics, any requirement without acceptance_criteria", "create_task warns when a P0 or P1 task has no test_plan", "The warnings go through BaseHandler._rule_warnings, so enforce refuses and off says nothing", "Warnings appear in the response text and in structuredContent, alongside the created record''s ID", "No tool gains a parameter and the budget does not move"]', '["A table of which fields matter for which kind of record", "Collect reasons in the create handlers and hand them to the existing rules helper"]', '["tests/test_thin_records.py: each rule in warn, enforce and off"]', NULL, NULL, '2026-09-16 11:37:22', '2026-09-16 12:34:48', '2026-09-16 12:34:48', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0071-00-00', 71, 0, 0, 'Serve a requirement capture prompt over MCP', 'Complete', 'P3', 'M', 'As a client that wants guided capture, I fetch a prompt that tells my own model what a good requirement looks like, and it calls create_requirement once.', '["The server answers prompts/list and prompts/get; it serves none today", "A capture prompt returns the fields create_requirement takes, what each is for, and a worked example", "The prompt carries no state: it is text the client''s model fills in, so nothing is kept between calls (F-08)", "The tool count stays 23: prompts are a separate primitive and do not count against the budget", "The handshake smoke script reports the prompt count alongside the tool count"]', NULL, '["tests/test_prompts.py through the MCP layer: prompts/list, prompts/get, and that following the prompt yields a requirement with curated fields filled"]', NULL, NULL, '2026-09-16 11:37:22', '2026-09-16 12:34:48', '2026-09-16 12:34:48', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0072-00-00', 72, 0, 0, 'Show when a requirement was last verified', 'Complete', 'P3', 'M', 'As someone reading the roadmap, I see which requirements have not been checked against the code since they were written.', '["A requirement''s details show when it was last verified, or that it never has been", "Verification is recorded by a comment or a status move, derived from lifecycle events rather than stored in a column", "get_project_status lists requirements whose content changed after their last verification, the way it lists ones changed since review", "A requirement verified after its last content change is not listed"]', NULL, '["tests/test_staleness.py through the MCP layer"]', NULL, NULL, '2026-09-16 11:37:22', '2026-09-16 12:34:48', '2026-09-16 12:34:48', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0073-00-00', 73, 0, 0, 'Delete the dead LLM sampling code', 'Complete', 'P3', 'S', 'As someone reading the handlers, I do not have to work out whether the sampling paths ever run.', '["No handler references mcp_client or MCP sampling, and set_mcp_client is gone from the server", "llm_decomposition_prompts.py is deleted", "create_requirement and create_architecture_decision behave exactly as before, minus the dead branches", "About 766 lines go: requirement_handler 418-692, architecture_handler 581-752, and the prompts module"]', NULL, '["The existing suite covers both create tools; a grep for mcp_client and sampling comes back empty"]', NULL, NULL, '2026-09-16 11:37:22', '2026-09-16 12:34:48', '2026-09-16 12:34:48', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0074-00-00', 74, 0, 0, 'R11 acceptance test, docs and changelog', 'Complete', 'P3', 'S', NULL, '["tests/test_r11_acceptance.py covers each R11 acceptance criterion through the MCP layer", "README and CLAUDE.md describe the thin-record warnings, the capture prompt and the staleness signal", "CHANGELOG records the prompt as the first one the server serves, and the removal of the dead sampling code"]', NULL, NULL, NULL, NULL, '2026-09-16 11:37:22', '2026-09-16 12:34:48', '2026-09-16 12:34:48', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL);
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0075-00-00', 75, 0, 0, 'Validate in the server''s own routing path and log every refused call', 'Complete', 'P2', 'M', 'As someone reading the call log for evidence, I want the calls a client got wrong to be in it, so the log''s totals describe the session rather than the subset that reached a handler.', '["A call refused by its schema is logged with isError true, error_kind validation, and the rule and parameter it was refused by", "A call naming a tool that does not exist is logged with error_kind unknown_tool", "No argument value reaches the log: jsonschema quotes the offending value in its message, so the message is never logged", "The MCP layer''s own validation is turned off (validate_input=False) so the refusal reaches the server''s logging at all"]', NULL, NULL, NULL, NULL, '2026-09-17 00:46:07', '2026-09-17 00:50:25', '2026-09-17 00:50:25', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite on branch roadmap/r18-r19-honest-refusals: 378 passed, 3 skipped, against a 368-passed baseline on main — the 10 added are tests/test_r18_acceptance.py and tests/test_r19_acceptance.py, one test per acceptance criterion plus each requirement''s validation metric. ruff check src tests --select E,F,I clean; ruff format clean. scripts/tool_usage_report.py run against a log containing both refusal kinds prints "errors: 3 = 2 refused before a handler ran + 1 handler" and names the refusing tools.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0076-00-00', 76, 0, 0, 'Count refusals apart from handler errors in the usage report', 'Complete', 'P2', 'S', NULL, '["scripts/tool_usage_report.py reports refused calls as their own column and totals them apart from handler errors", "The two totals sum to the calls with isError true", "Tools attracting refusals are named", "A log written before this change still loads, its errors counted as handler errors"]', NULL, NULL, NULL, NULL, '2026-09-17 00:46:08', '2026-09-17 00:50:25', '2026-09-17 00:50:25', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite on branch roadmap/r18-r19-honest-refusals: 378 passed, 3 skipped, against a 368-passed baseline on main — the 10 added are tests/test_r18_acceptance.py and tests/test_r19_acceptance.py, one test per acceptance criterion plus each requirement''s validation metric. ruff check src tests --select E,F,I clean; ruff format clean. scripts/tool_usage_report.py run against a log containing both refusal kinds prints "errors: 3 = 2 refused before a handler ran + 1 handler" and names the refusing tools.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0077-00-00', 77, 0, 0, 'Name the parameter that would have taken the value', 'Complete', 'P3', 'S', 'As a client that reached for the singular parameter out of habit, I want the refusal to name the plural one beside it, so I look at my call rather than at the server for the defect.', '["A type error on a parameter with a close-named sibling that accepts the value names that sibling", "The message names the refused parameter and the type it expects", "The suggestion comes from the tool''s own schema, not a list of known pairs", "A type error with no such sibling is byte-identical to the message the MCP layer produced"]', NULL, NULL, NULL, NULL, '2026-09-17 00:46:11', '2026-09-17 00:50:25', '2026-09-17 00:50:25', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite on branch roadmap/r18-r19-honest-refusals: 378 passed, 3 skipped, against a 368-passed baseline on main — the 10 added are tests/test_r18_acceptance.py and tests/test_r19_acceptance.py, one test per acceptance criterion plus each requirement''s validation metric. ruff check src tests --select E,F,I clean; ruff format clean. scripts/tool_usage_report.py run against a log containing both refusal kinds prints "errors: 3 = 2 refused before a handler ran + 1 handler" and names the refusing tools.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0078-00-00', 78, 0, 0, 'Document the refusal log and the near-neighbour suggestion', 'Complete', 'P3', 'S', NULL, '["README and CLAUDE.md say the call log holds refused calls and what error_kind means", "docs/tool-surface/usage-evidence.md records that its figures undercount refused calls", "Both roadmap items have an acceptance test in the repository''s convention"]', NULL, NULL, NULL, NULL, '2026-09-17 00:46:13', '2026-09-17 00:50:25', '2026-09-17 00:50:25', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite on branch roadmap/r18-r19-honest-refusals: 378 passed, 3 skipped, against a 368-passed baseline on main — the 10 added are tests/test_r18_acceptance.py and tests/test_r19_acceptance.py, one test per acceptance criterion plus each requirement''s validation metric. ruff check src tests --select E,F,I clean; ruff format clean. scripts/tool_usage_report.py run against a log containing both refusal kinds prints "errors: 3 = 2 refused before a handler ran + 1 handler" and names the refusing tools.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0079-00-00', 79, 0, 0, 'Start the verification clock when a requirement is written', 'Complete', 'P2', NULL, 'As a reader of the dashboard, I want a badge that only fires when it carries information, so that I keep reading the dashboard', '[]', NULL, '["tests/test_r17_acceptance.py::test_1 - a requirement left alone since it was written is not chased", "tests/test_staleness.py - writing a requirement counts as checking it"]', NULL, NULL, '2026-09-17 13:20:16', '2026-09-17 13:22:22', '2026-09-17 13:22:22', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'tests/test_r17_acceptance.py::test_1 and tests/test_staleness.py pass: a requirement left alone since it was written shows Last Verified, not Never verified, and the dashboard does not list it. The "Never verified" line is gone from requirement_handler.py.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0080-00-00', 80, 0, 0, 'Judge staleness by age, and state only the two times the record holds', 'Complete', 'P2', NULL, 'As a reader of a requirement, I want its staleness line to tell me when it changed and when it was last checked, so that I am not told a third thing the tracker cannot know', '[]', NULL, '["tests/test_r17_acceptance.py::test_2 - untouched past the threshold, listed with its age, threshold configurable", "tests/test_r17_acceptance.py::test_3 - both times and no invented ''stale since''", "tests/test_r17_acceptance.py::test_4 and test_5 - the review line carries its edit time and stands after a comment"]', NULL, NULL, '2026-09-17 13:20:19', '2026-09-17 13:22:24', '2026-09-17 13:22:24', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'tests/test_r17_acceptance.py::test_2, test_3, test_4, test_5 pass: age threshold via LIFECYCLE_STALE_AFTER (default 14) with the age reported, both times on the staleness line and no invented "stale since", and the review line carrying its edit time and surviving a comment.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0081-00-00', 81, 0, 0, 'Name the requirements whose work is done and only the decision is missing', 'Complete', 'P2', NULL, 'As someone running a project, I want the tracker to tell me which requirement is waiting on my decision, so that finished work does not sit reported as 0% complete', '[]', NULL, '["tests/test_r17_acceptance.py::test_6 - the dashboard names them and counts them", "tests/test_r17_acceptance.py::test_7 - query_requirements(work_complete) returns exactly those"]', NULL, NULL, '2026-09-17 13:20:22', '2026-09-17 13:22:26', '2026-09-17 13:22:26', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'tests/test_r17_acceptance.py::test_6 and test_7 pass: the dashboard names them under Work Complete, Decision Pending and query_requirements(work_complete=True) returns exactly those. One definition, WORK_COMPLETE_WHERE, behind both.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0082-00-00', 82, 0, 0, 'Say which case an empty ready-to-start result is', 'Complete', 'P3', NULL, 'As an agent asking what to work on next, I want to know whether nothing is left, everything is waiting, or the work is already under way, so that I can act on the answer', '[]', NULL, '["tests/test_r17_acceptance.py::test_8 - blocked, already in progress, and nothing left, each named"]', NULL, NULL, '2026-09-17 13:20:24', '2026-09-17 13:22:27', '2026-09-17 13:22:27', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'tests/test_r17_acceptance.py::test_8 passes: an empty ready result names the case - 1 Blocked, 1 task(s) already In Progress, or no tasks remain - instead of "No tasks found".');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0083-00-00', 83, 0, 0, 'Record an amendment against an Accepted decision', 'Complete', 'P3', NULL, 'As the author of an accepted decision, I want to correct one number in it without rewriting the record or raising a whole superseding ADR, so that the decision stops contradicting the system it describes', '[]', NULL, '["tests/test_r20_acceptance.py::test_1 - the Decision text stays byte-identical and the amendment shows with it", "tests/test_r20_acceptance.py::test_5 - the amendment is its own event in get_entity_history"]', NULL, NULL, '2026-09-17 18:28:35', '2026-09-17 18:34:45', '2026-09-17 18:34:45', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'tests/test_r20_acceptance.py::test_1 and test_5 pass: amending an Accepted decision records a lifecycle event, leaves the Decision text and revision 0 untouched, and appears in get_entity_history as "amended decision_outcome" with its reason - not a field edit, not a comment. No migration was needed: lifecycle_events.event_type has no CHECK constraint.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0084-00-00', 84, 0, 0, 'Render amendments with the decision in details and export', 'Complete', 'P3', NULL, 'As a reader of a decision, I want the correction to appear with the decision it corrects, so that I cannot read the outdated text without seeing the amendment', '[]', NULL, '["tests/test_r20_acceptance.py::test_2 - the exported documentation carries it, not only the comments"]', NULL, NULL, '2026-09-17 18:28:37', '2026-09-17 18:34:47', '2026-09-17 18:34:47', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'tests/test_r20_acceptance.py::test_2 passes: the exported architecture document carries "### Amendments (1)" between the Decision and the Comments, so a reader meets the correction before the comments. amendments() and format_amendments() in architecture_handler.py render both details and export from one definition.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0085-00-00', 85, 0, 0, 'Refuse the wrong operation with guidance naming the right one', 'Complete', 'P3', NULL, 'As someone who reached for the wrong tool, I want the refusal to name the operation I wanted, so that immutability teaches rather than blocks', '[]', NULL, '["tests/test_r20_acceptance.py::test_3 - amending a Proposed decision says to edit it instead", "tests/test_r20_acceptance.py::test_4 - editing an Accepted one names both amendment and supersession", "tests/test_update_tools.py and tests/test_r6a_acceptance.py - R6a''s immutability wording still holds"]', NULL, NULL, '2026-09-17 18:28:40', '2026-09-17 18:34:49', '2026-09-17 18:34:49', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'tests/test_r20_acceptance.py::test_3, test_4 and test_6 pass: amending a Proposed decision says to edit it instead, editing an Accepted one names both amendment and supersession, and an amendment passed beside a field edit is refused. R6a''s existing wording assertions in tests/test_update_tools.py and tests/test_r6a_acceptance.py still pass, so the immutability rule was extended rather than relaxed.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0086-00-00', 86, 0, 0, 'Record where a requirement came from', 'Complete', 'P2', 'M', 'As a reader of the tracker, I want to tell a requirement someone stated from one a model derived from a source, so that I never mistake a reading of the code for a decision a person made.', '["A requirement created with origin derived-from-code says so in get_details and in exported documentation", "A requirement created without origin reads exactly as it does today, in details and in export", "tests/test_schema_coverage.py passes with origin on neither allowlist", "The tool surface budget test passes against the raised number"]', '["Migration 18 adds an origin column to requirements, defaulting to stated so every existing row keeps its meaning", "create_requirement and update_requirement declare origin with its enum; the handler passes it through like any other column", "Requirement details and export print the origin when it is not stated, so an ordinary requirement gains no noise", "Raise tests/tool_surface_budget.json for the two added properties in the same change"]', '["Migration test: an existing database gains the column with every row at stated", "Round trip through create, details and export for each origin value", "Schema coverage and tool surface budget suites"]', NULL, NULL, '2026-09-18 11:19:04', '2026-09-18 11:28:22', '2026-09-18 11:28:22', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Migration 18 adds requirements.origin defaulting to stated; tests/test_migrations.py::test_existing_requirements_are_stated_when_the_origin_column_arrives confirms every pre-existing row keeps its meaning. tests/test_r21_acceptance.py tests 4, 5, 6 and 7 cover details, export, Draft on creation, correction through update_requirement and refusal of an unknown value. tests/test_schema_coverage.py passes with origin on neither allowlist. Tool surface budget raised to 23 tools / 13185 chars for the two added properties (+182), tool count unchanged.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0087-00-00', 87, 0, 0, 'Offer a prompt that reconciles a source against the stored requirements', 'Complete', 'P2', 'M', 'As someone with a transcript or an existing codebase, I want to hand it to the client''s model and get back what is new, what amends an existing requirement and what is already covered, so that importing existing work does not duplicate or overwrite what is stored.', '["prompts/list offers the prompt with its arguments, and prompts/get renders the source text into it", "The prompt text names query_requirements, create_requirement and update_requirement, and says derived requirements are created in Draft", "The prompt tells the model to report contradictions rather than resolve them", "tools/list is unchanged: no tool is added by this task"]', '["Add a reconcile_requirements prompt to prompts.py taking the source text and an optional note on what kind of source it is", "The text instructs: query first, then classify each candidate as new, amendment, already covered or contradicted, and name the requirement for each of the last three", "Amendments land through update_requirement naming the fields they change; new ones through create_requirement with origin set", "Contradictions are reported, never resolved; nothing is created above Draft", "Wire nothing new into server.py: prompt_definitions and render_prompt already serve the list and get handlers"]', '["Prompt listing and rendering tests beside the existing capture prompt tests", "An unknown prompt still names everything offered, now two prompts", "A tool-surface assertion that the tool count did not change"]', NULL, NULL, '2026-09-18 11:19:11', '2026-09-18 11:28:25', '2026-09-18 11:28:25', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'reconcile_requirements added to prompts.py with source and source_kind arguments; server.py needed no change, since prompt_definitions and render_prompt already serve both handlers. tests/test_r21_acceptance.py tests 1, 2, 3, 8 and 9 cover the ordering (query before create), amendments through update_requirement, contradictions reported and not resolved, the source text carried in, and that no tool was added. tests/test_prompts.py updated for the second prompt and passing.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0088-00-00', 88, 0, 0, 'Render an ADR''s authors and consequences as text', 'Complete', 'P2', 'S', 'As a reader of a decision record, I want its authors and consequences to read as prose, so that I am not decoding JSON brackets and Python quoting to find out who decided what.', '["Authors shows a comma-separated list with no brackets or quotes, and Not specified when empty", "A consequences value holding a list shows one entry per line in details and in export, with no Python repr", "A consequences value holding a string renders unchanged", "ADR-0005 in this tracker reads correctly on both counts"]', '["Pass authors through _safe_json_loads and join it, exactly as deciders is handled one line above (F-41)", "Render a consequences value that is a list as one line per entry, in the details renderer and in the export renderer, which carry the same code today", "Leave a string value rendering as it does now, so existing records are untouched"]', '["Details and export assertions for an ADR with list authors and list-valued consequences", "A regression assertion that a string-valued consequences entry is unchanged"]', NULL, NULL, '2026-09-18 11:19:21', '2026-09-18 11:28:14', '2026-09-18 11:28:14', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'tests/test_r23_acceptance.py tests 1, 1b, 2 and 2b pass. Authors now goes through _safe_json_loads and a join, as deciders already did (F-41 closed). The consequences renderer moved to BaseHandler._format_consequences, so details and export share one implementation instead of two identical copies; a value holding a list renders one entry per line, a string value is unchanged.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0089-00-00', 89, 0, 0, 'Show a requirement''s decisions and requirement links in its details', 'Complete', 'P2', 'M', 'As a reader of a requirement, I want its details to name the decisions it addresses and the requirements it is linked to, so that a requirement with a decision and no tasks does not read as though nothing links to it.', '["A requirement addressing a decision names it, with its status, in get_details", "A requirement linked to another requirement names it and the link type", "A requirement with no tasks, decisions or requirement links shows none of those headings", "The R9 assertions in tests/test_design_link_details.py pass unchanged"]', '["Add the addresses link section to requirement details, beside the existing Linked Tasks section, following the shape R9 gave architecture and task details", "Add the requirement-to-requirement links, naming the link type, in the direction stored", "Show a section only when it has rows, as the design-link sections already do"]', '["Details assertions for a requirement with a decision, with a sibling requirement, and with neither", "Re-run the existing design-link suite unchanged"]', NULL, NULL, '2026-09-18 11:19:26', '2026-09-18 11:28:16', '2026-09-18 11:28:16', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'tests/test_r23_acceptance.py tests 3, 3b and 4 pass, and tests/test_design_link_details.py passes unchanged, so R9''s architecture and task sections are untouched. Requirement details gained an Addresses Decisions section through the existing _format_linked helper, plus a Linked Requirements section that names each link''s type and direction, since the type varies per row. Empty sections are still omitted.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0090-00-00', 90, 0, 0, 'Read the tracker into a snapshot without touching it', 'Complete', 'P2', 'M', 'As the generator, I need every record the viewer will show, read from a database that may be in use, so that the snapshot is complete and the database is unaffected.', '["Reads through SQLite with file:...?mode=ro, so the WAL is included and no checkpoint, copy or server shutdown is needed", "Never uses immutable=1, which would tell SQLite to ignore the WAL and reintroduce the stale read this exists to avoid", "Captures requirements, tasks, architecture decisions, relationships, comments and the lifecycle events the derived figures need", "JSON columns arrive parsed rather than as stored strings, using the handlers'' own field lists so the viewer and get_details agree about which columns those are", "A JSON column that will not parse is reported as missing rather than as an empty list, because an empty list reads as a field nobody filled in", "The database file and its -wal are byte-identical after the generator runs. The -shm is excluded deliberately: it is the WAL''s shared-memory index, SQLite writes a read mark into it whenever any reader attaches, and it holds no records", "The whole snapshot is one read transaction, so the tables cannot be read either side of another process''s write and disagree with each other", "Runs against a database being written by a live server without failing or blocking it", "A missing or unreadable database is reported rather than rendered as an empty project"]', NULL, '["Snapshot a fixture database and assert every record and link is present", "Assert the three database files'' bytes are identical before and after", "Write to the database from a second connection during the snapshot and assert the run still completes"]', NULL, NULL, '2026-09-28 17:28:34', '2026-09-28 18:34:41', '2026-09-28 18:34:41', NULL, NULL, NULL, NULL, 1, NULL, NULL, 'src/lifecycle_mcp/viewer/snapshot.py with a viewer package docstring saying the viewer is a reader of a database, not a mode of the server. read_snapshot() opens file://...?mode=ro and reads all seven tables in one transaction ordered by primary key, so two snapshots of an unchanged tracker are identical. JSON_FIELDS is built from REQUIREMENT_JSON_FIELDS, TASK_JSON_FIELDS and ARCHITECTURE_JSON_FIELDS rather than a fourth list. A Snapshot dataclass carries the rows plus counts(). Verified against this repository''s live tracker while its -wal held 2.1 MB against a 610 KB main file six days old: 31 requirements, 100 tasks, 5 decisions, 173 relationships, 318 comments, 588 events, schema_version up to 18, and the db and -wal hashes unchanged across the read. 9 tests in tests/test_viewer_snapshot.py, including a write from a second connection landing in the snapshot, and a test asserting the URI never says immutable - the flag that would ignore the WAL and reintroduce the stale read. The -shm criterion was wrong as written and was corrected in revision 1: SQLite writes a read mark into the shared-memory index whenever a reader attaches, so no read-only snapshot can leave it untouched.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0091-00-00', 91, 0, 0, 'Derive the dashboard figures from the server''s own definitions', 'Complete', 'P2', 'M', 'As a reader of the page, I need its figures to be the same figures the tools give, so that I never have to work out which of the two is telling the truth.', '["Work complete and decision pending comes from WORK_COMPLETE_WHERE, waiting and blocked work from TASK_DEPENDENCIES_SQL, staleness from the existing verification derivation, ready to start from the same filter query_tasks uses", "Those definitions are imported from the package, never copied into the generator: the SQL and the thresholds have one home", "Every figure is computed here and embedded as data, so the page performs no lifecycle judgement of its own", "LIFECYCLE_STALE_AFTER is honoured, so the page''s staleness agrees with the server''s", "An empty section says which case it is, as R17 requires of the dashboard"]', NULL, '["Against one fixture database, assert every embedded figure equals what get_project_status reports, figure for figure", "Grep the generator for copied fragments of the handlers'' SQL and fail if any are found", "Vary LIFECYCLE_STALE_AFTER and assert the embedded staleness moves with it"]', NULL, NULL, '2026-09-28 17:28:34', '2026-09-28 18:44:47', '2026-09-28 18:44:47', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'src/lifecycle_mcp/viewer/figures.py derives every dashboard section by importing and running the server''s own definitions: WORK_COMPLETE_WHERE, BLOCKED_TASKS_SQL, READY_TASKS_WHERE, stale_requirements(), changes_since_review() and describe_age(). Two supporting changes were needed. The ready filter was an inline f-string inside _query_tasks, so it could not be imported without copying it: extracted as READY_TASKS_WHERE and READY_TASKS_ORDER in task_handler.py and used by the tool, which now reads one definition. And the derivation functions take a DatabaseManager, which a viewer must not construct - its __init__ calls _ensure_database_exists, which runs apply_all_migrations on the target and creates a whole new tracker from the baseline if the path is absent - so snapshot.py gained a ReadOnlyDatabase adapter exposing execute_query''s signature over a mode=ro connection. That lets the viewer run the real functions rather than copies. 10 tests compare the figures with get_project_status, query_requirements(work_complete=True) and query_tasks(ready=True) figure for figure, plus a test that reads the viewer''s source and fails on fragments a reimplementation would contain. Against the live tracker: 4 blocked, 4 stale, 2 changed since review, and an empty ready list explaining itself as "1 already under way, 4 waiting on a dependency".');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0092-00-00', 92, 0, 0, 'Emit one self-contained HTML file that works offline', 'Complete', 'P2', 'M', 'As someone with the file and no tooling, I need it to open by double-clicking on any machine, so that reading the tracker costs nothing to set up.', '["One HTML file with the snapshot embedded, opening from file:// with no server, no install and no build step", "Nothing external: no CDN script, no stylesheet link, no web font, no image fetched over the network", "No write path in the page: no form, no fetch, no XMLHttpRequest, no SQLite, no service worker", "The page names the time it was generated, so a reader can judge how stale the snapshot is", "Readable at a laptop and a phone width, and legible in both light and dark colour schemes", "Opens and shows the same records on a machine with no Python, no uv and no lifecycle-mcp"]', NULL, '["Assert the page''s own markup - everything outside the embedded data block - names no host and contains no fetch, XMLHttpRequest, form, WebAssembly, service worker or localStorage. Asserted against the whole file it would fail on a record that merely mentions one, and a task''s github_issue_url is a stored column", "Assert nothing in the file is loaded at all: no src, no href, no link element, no @import", "Assert a record whose text contains a URL keeps it, so preserving content and naming no host are separately true", "Assert a record''s title cannot inject markup: exactly one script block in the page, and the data block cannot be closed early by a value containing its closing tag", "Open the file with networking disabled and assert the records render", "Two runs against an unchanged database differ only in the generation time, and two runs at the same instant are byte-identical", "Move the written file away from the database and assert it still shows the records"]', NULL, NULL, '2026-09-28 17:28:34', '2026-09-28 19:18:51', '2026-09-28 19:18:51', NULL, NULL, NULL, NULL, 1, NULL, NULL, 'src/lifecycle_mcp/viewer/render.py emits one HTML document: inline styling with light and dark tokens, a viewport meta and a phone-width breakpoint, the dashboard''s five signal sections rendered from figures.py with their R17 empty-state sentences, count tiles, status bars, the generation time, and the whole snapshot embedded in a single application/json block for TASK-0093 and TASK-0094 to read. No src, href, link element or @import anywhere, so nothing is loaded; no form, fetch, XMLHttpRequest or WebAssembly in the page''s own markup. Record text is escaped and the data block''s angle brackets and ampersands are unicode-escaped, so a title containing a script tag renders as text and cannot close the block early - there is exactly one script block in the output. 16 tests, full suite 469 passed. Generated from the live tracker: 434 KB, into exports/, which .gitignore already covers, and git status stays clean. Two tests in the plan were wrong as written and were corrected in revision 1: asserting no http:// or XMLHttpRequest anywhere in the file fails on this repository''s own tracker, because TASK-0092''s test plan is stored in it and contains both strings, and tasks carry a github_issue_url column. The property is that the page''s own markup names no host and loads nothing; a URL inside an escaped data block is inert text.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0093-00-00', 93, 0, 0, 'Browse, filter and search every field in the page', 'Complete', 'P2', 'M', 'As someone looking for a record, I need to narrow the list and search text the tools cannot reach, so that finding a requirement does not depend on guessing its title.', '["Requirements, tasks and decisions are each listed, with status, priority and type visible without opening a record", "Lists filter by status, priority and type, and the filters combine", "Opening a record shows every field it holds, including the ones the dashboard never prints", "Free-text search matches every embedded field, so a requirement is found by a term appearing only in its acceptance criteria - text search_text cannot reach", "A search or filter matching nothing says so, and says which filter excluded everything", "Comments on a record are shown with it, as export already carries them"]', NULL, '["Search a term present only in one requirement''s acceptance criteria and assert that requirement is the result, and that query_requirements'' search_text finds nothing for the same term", "Assert every record in the fixture database is reachable through the lists", "Combine two filters and assert the result is their intersection"]', NULL, NULL, '2026-09-28 17:28:34', '2026-09-28 19:28:45', '2026-09-28 19:28:45', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'src/lifecycle_mcp/viewer/browse.py renders every requirement, task and decision server-side as a details element: a summary line with id, title, status, priority, type and effort readable without opening it, then every filled field (lists as lists, objects as definition lists, text with its line breaks), a "Not filled" line naming the empty ones, the record''s comments, and bookkeeping last. The page is complete with scripting off; the script only hides and shows. Controls are an input and four selects with no form. Search matches every field and every comment, word by word in any order, so "export resume" finds "export resumes after a crash" where search_text finds nothing. An empty result names the query that matched nothing, or the filter that on its own excludes everything (R17). Tests: Python asserts what the page contains, including a term only in acceptance criteria that query_requirements'' search_text returns 0 for and the page finds; node runs the two pure functions, visible() and emptyReason(), that decide what a reader sees; and headless Chrome runs the real page and confirms init() completes, turning the server-rendered "N records" into "Showing N of N records". Two corrections to earlier work: the snapshot returned None for both an empty and an unparseable JSON column, so the page could not tell them apart despite #2209 saying it could - an unreadable column now keeps its stored text and is named in _unreadable. And TASK-0091''s copied-definition guard tripped on browse.py listing tasks_completed as a column to display; it now looks for the comparison, tasks_completed >=, and was re-verified by planting a reimplemented rule in the package and watching it fail. 483 passed, 3 skipped; CI''s own ruff invocation clean.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0094-00-00', 94, 0, 0, 'Navigate a record''s links from its own end', 'Complete', 'P2', 'S', 'As someone reading one record, I need to follow its links to the records at the other end, so that the relationships are navigable rather than named.', '["A record shows its links from its own end, grouped by type and direction, the way R23 made get_details do and agreeing with query_relationships", "Every link is clickable through to the record at the other end, without leaving the page", "Both directions are reachable: a requirement to the decision that addresses it, and that decision back to the requirement", "A record with no links of a kind shows no empty section for it", "Parent, supersedes and superseded_by keep the distinct rendering they already have"]', NULL, '["For each record in a fixture database, assert the page''s link groups match query_relationships for that record", "Follow a requirement to an ADR and back and assert both targets exist in the page", "Assert a record with no tasks renders no task section"]', NULL, NULL, '2026-09-28 17:28:34', '2026-09-28 20:00:12', '2026-09-28 20:00:12', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'src/lifecycle_mcp/viewer/links.py renders each record''s links from its own end, grouped by type and direction as query_relationships groups them, with the tool''s own arrows on every entry. Headings are get_details'' where it has one; they are looked up by type, direction and the kind of record, because implements flips its direction convention with the pair (requirement to task has the target implementing, task to architecture the source), and fall back to the type plus the arrow. Every link is an in-page anchor; a link to a record the page does not hold is named with "not in this tracker" rather than linked. The page''s script opens the record an anchor names, clearing the filters first if they were hiding it. Dashboard rows link to their records too. The central test compares every record''s links in the page with query_relationships'' output, entry by entry, across implements, addresses, depends, parent and supersedes, with a guard that fails if the comparison covered nothing. Headless Chrome confirms arriving at a record''s anchor opens that record and only that one. Also removed the JSON data block from TASK-0092, which nothing read: the page fell from 1127 KB to 798 KB on this repository''s tracker, and a test keeps a second copy of the records from returning. Against the live tracker: 357 links, every one an in-page anchor landing on a record, 135 of 136 records with a links section. Found while checking that: the anchor test and one browse test matched the word "open" or "hidden" anywhere in a record''s tag, and the tag carries the record''s search text, so on real data the open check counted 36 records. Both now match the attribute, and the anchor test seeds a record that says "open" so the fragile form would fail. 493 passed, 3 skipped; CI''s ruff invocation clean.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0095-00-00', 95, 0, 0, 'A documented make target that writes to exports/', 'Complete', 'P2', 'S', 'As the owner, I need one command that regenerates the viewer, so that refreshing the snapshot is not something I have to remember how to do.', '["A make target regenerates the file in one command, with no arguments needed for the default case", "Output goes to exports/, which .gitignore already covers, so no commit carries a diff of the generated file", "The target reads the repository''s own database by default, and takes an explicit path for another project''s", "README says what the file is, how to regenerate it, that it is a snapshot rather than live, and that it embeds the whole tracker in plaintext and is therefore as sensitive as the database", "The script is in scripts/, beside the repository''s existing tooling, and never prints to stdout in a way that would break a protocol channel if it were ever imported"]', NULL, '["Run the target against a fixture database and assert the file appears in exports/", "Assert git status is clean after generating, so the artefact is genuinely ignored", "Point the explicit path at a second database and assert the output describes that one"]', NULL, NULL, '2026-09-28 17:28:34', '2026-09-28 20:18:47', '2026-09-28 20:18:47', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'scripts/tracker_viewer.py plus a make viewer target (DB= for another tracker, OUT= for another destination), a README section, and a CLAUDE.md entry. make viewer against this repository wrote exports/lifecycle-mcp-tracker.html, 801 KB, and git status stayed clean because exports/ is ignored. Output is named for the project so viewers of different trackers do not overwrite each other. The default tracker is this repository''s lifecycle.db and LIFECYCLE_DB is deliberately not consulted, because with the tracker dogfooded on several projects it routinely points elsewhere. A missing path is reported and never created: make viewer DB=<mistyped> exits 1 with the path named and not even the parent directory appears, the DatabaseManager hazard from TASK-0091. generate() is importable and prints nothing; only main() writes to stdout. The README covers what the file is, how to regenerate it, that it is a snapshot not a live view, that it is read-only, and that it embeds the whole tracker in plaintext and is as sensitive as the database. CLAUDE.md now names the viewer and the rule easiest to break: open trackers through ReadOnlyDatabase, never DatabaseManager, and import definitions rather than restating their SQL. 12 tests, full suite 505 passed. Also on this branch: #2212, #2213 and #2214 cherry-picked onto main, because they were merged into viewer/req-0006-figures-to-main after that branch had already been squashed into main, so none of them had reached it.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0096-00-00', 96, 0, 0, 'One derived definition of being ready to validate', 'Complete', 'P1', 'S', 'As the gate and the dashboard, we need one definition of whether a requirement''s work is finished, so that we cannot disagree about the same record.', '["A single WHERE fragment expresses: the requirement has leaf tasks, at least one is Complete, and none is Not Started, In Progress or Blocked", "It is a correlated NOT EXISTS over relationships and tasks, so nothing is stored and nothing can go stale", "It reuses the same is-leaf condition the counter triggers use rather than restating it, so a parent task is counted through its subtasks", "WORK_COMPLETE_WHERE is rebuilt on it, so the dashboard section and query_requirements(work_complete=True) both follow with no change of their own", "A requirement whose every task is Abandoned does not satisfy it", "No migration, no new column, no trigger change: schema_version is untouched"]', NULL, '["A requirement with one Complete and one Abandoned task satisfies the predicate; one with an open task does not; one with only abandoned tasks does not; one with no tasks does not", "A parent task with open subtasks keeps the requirement from satisfying it, and the parent alone does not", "Assert schema_version is unchanged after the suite runs"]', NULL, NULL, '2026-09-28 17:39:51', '2026-09-28 17:51:18', '2026-09-28 17:51:18', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'requirement_handler.py: OPEN_TASK_STATUSES, _has_leaf_task_with_status(), VALIDATION_READY_WHERE and WORK_COMPLETE_WHERE rebuilt on it. Derived as a correlated NOT EXISTS over relationships and tasks, so no column, no trigger and no migration - MIGRATIONS stays at 18, asserted by a test. migrations.py: _IS_LEAF renamed IS_LEAF_TASK and imported by the handler, so the leaf rule has one home rather than two copies. Verified against the repository''s own database: the new and old WORK_COMPLETE_WHERE return the same set, and the predicate names the 23 requirements with completed work. Tests in tests/test_abandoned_work.py cover the four cases (one complete plus one abandoned, an open task, all abandoned, no tasks) and the parent-counted-through-subtasks rule.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0097-00-00', 97, 0, 0, 'Narrow the Validated gate to the case with no evidence', 'Complete', 'P1', 'M', 'As someone whose work was abandoned rather than finished, I need to validate the requirement anyway, so that recording the truth does not cost the requirement its ending.', '["An open task - Not Started, In Progress or Blocked - still refuses the move, with the message it gives today", "A requirement with tasks but not one Complete is refused, the message names the abandoned tasks and says to deprecate it instead of validating it", "A requirement with at least one Complete task and no open tasks moves to Validated even when some tasks are Abandoned", "The abandoned tasks are passed to _rule_warnings rather than refused outright: off is silent, warn moves it and names them, enforce raises StatusRefused before the transaction opens", "The always-on part of the gate reads the predicate from the first task rather than its own copy of the SQL"]', NULL, '["One Complete plus one Abandoned validates and the response names the abandoned task", "The same move under enforce is refused and the requirement''s status is unchanged; under off it succeeds with no mention", "All tasks Abandoned is refused and the message contains Deprecated", "An open task is refused with today''s wording", "A refused move in a multi-ID call leaves that requirement untouched"]', NULL, NULL, '2026-09-28 17:40:07', '2026-09-28 17:51:18', '2026-09-28 17:51:18', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'requirement_handler._validation_gate() replaces the inline gate. It decides with VALIDATION_READY_WHERE - the same SQL the dashboard section and query_requirements(work_complete=True) read, so a refusal cannot contradict either - and uses the task rows only to word the message. Refuses an open task with the existing wording plus a line saying abandoned tasks do not block; refuses an all-abandoned requirement and names Deprecated; returns the abandoned tasks as _rule_warnings reasons otherwise, so off is silent, warn moves and names them, enforce raises StatusRefused before the transaction opens. A requirement with no tasks stays validatable as before.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0098-00-00', 98, 0, 0, 'Stop the Implemented gate warning about abandoned work forever', 'Complete', 'P1', 'S', 'As someone moving a requirement to Implemented, I need the warning to be about work that is still open, so that it means something when it fires.', '["OPEN_TASKS_SQL stops treating Abandoned as open work", "An abandoned task is named as abandoned in its own reason line, not reported as a task that is not Complete, following the shape _dependency_reasons already uses for abandoned dependencies", "A requirement whose only unfinished tasks are abandoned reaches Implemented with no warning that tasks are not Complete", "Tasks that are genuinely open warn exactly as they do today"]', NULL, '["A requirement with one Complete and one Abandoned task reaches Implemented without a not-Complete warning", "A requirement with a Blocked task keeps today''s warning text", "Under enforce, an open task still refuses and an abandoned one does not"]', NULL, NULL, '2026-09-28 17:40:07', '2026-09-28 17:51:18', '2026-09-28 17:51:18', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'OPEN_TASKS_SQL removed in favour of LEAF_TASKS_SQL plus _leaf_tasks(). _implemented_gate_reasons now partitions on OPEN_TASK_STATUSES, following the shape _dependency_reasons already used for abandoned dependencies: open tasks keep the existing "Tasks not Complete" line, abandoned ones get "Tasks abandoned rather than completed". The abandoned line is suppressed when the move carries on to Validated, because _validation_gate gives its own and saying it twice for one move is the noise R17 is about - covered by a test asserting exactly one warning names the abandoned task on a Ready to Validated move.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0099-00-00', 99, 0, 0, 'Refuse a task''s parent link by naming the tool that makes one', 'Complete', 'P3', 'XS', 'As someone who asked create_relationship for a subtask link, I need to be told which tool does it, so that a refusal ends the problem instead of starting one.', '["A task to task parent request names update_task and its parent_task_id parameter, and says the move is recorded in the task''s history", "The word invalid does not appear in that refusal", "A pair that genuinely cannot exist is still refused as invalid", "The reversed form - asking for parent with the parent as source - gets the same helpful refusal rather than a different message"]', NULL, '["Request a task parent link and assert the message names update_task and parent_task_id and omits the word invalid", "Request an impossible pair and assert it is still called invalid", "Assert update_task with parent_task_id still creates the link and logs a field_edit"]', NULL, NULL, '2026-09-28 18:03:47', '2026-09-28 18:07:16', '2026-09-28 18:07:16', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'relationship_handler.py: LINKS_OWNED_BY_A_TOOL maps a pair to the tool that owns it and why, checked in _create_relationship before _validate_relationship because these pairs are deliberately absent from the permitted table. A task parent request now reads "A task''s parent link is made with update_task and its parent_task_id, not create_relationship" plus the reason - re-parenting goes through _apply_edit, so it bumps the revision and logs a field_edit, which a bare row would skip. tests/test_parent_link_refusal.py: the message names update_task and parent_task_id and never says invalid; the reversed request gets the same message, since direction is normalized after validation; a requirement superseding a task is still called invalid; update_task still makes the link and the move still appears in the task''s history.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0100-00-00', 100, 0, 0, 'Stop the permitted table and the created links from drifting apart', 'Complete', 'P3', 'S', 'As the next person to add a link type, I need the suite to tell me when a link the handlers create is one create_relationship refuses, so that the inconsistency cannot be introduced silently again.', '["A test collects the pairs the handlers create through _link and fails when one is neither permitted by _validate_relationship nor on an explicit list of pairs a dedicated tool owns", "Each entry on that list names the owning tool and the reason create_relationship does not make it, following the shape tests/test_schema_coverage.py uses for a column no tool exposes", "The test fails if the task to task parent entry is removed from the table without being added to the list, and vice versa", "The collection reflects what the code does rather than a second hand-written copy of it, so adding a _link call in a handler is enough to trip it"]', NULL, '["Assert the six pairs the handlers create today are all accounted for", "Temporarily add a _link call for an unlisted pair and assert the test fails", "Assert the explicit list is non-empty and every entry names a tool"]', NULL, NULL, '2026-09-28 18:03:47', '2026-09-28 18:07:16', '2026-09-28 18:07:16', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'tests/test_link_pairs.py reads the handlers'' _link calls out of the source with ast, so adding one in a handler is enough to trip the test rather than needing a hand-kept list. It found 4 distinct pairs across 6 call sites. Asserts every pair is permitted by _validate_relationship or listed in LINKS_OWNED_BY_A_TOOL, that no pair is both, and that each listed entry names a tool and gives a reason. Verified the guard is not decoration: adding a _link call for an unlisted pair (task -> requirement blocks) to export_handler.py made it fail, and the file was reverted with no diff. A first test asserts the AST walk still finds the known pairs, so the suite cannot pass vacuously if the walk ever stops matching.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0101-00-00', 101, 0, 0, 'Export the tracker''s rows as deterministic SQL', 'Complete', 'P1', 'M', 'As the owner, I need the tracker written out as text that changes only when the tracker does, so that it can live in git beside the code it describes.', '["Reads through SQLite read-only, so the WAL is included and nothing is checkpointed, copied or written", "Holds INSERT statements and schema_version rows only: no CREATE, no DROP, no trigger, no view", "Every data table is exported, found from the database rather than a hand-kept list, so a table a future migration adds is not silently left behind", "Each INSERT names its columns, so a schema with more columns can still take the row", "Rows come in primary-key order, one statement per row, and nothing about the export itself - no time, no host, no count - is in the file, so two exports of an unchanged tracker are byte-identical", "Text keeps its line breaks and quotes exactly, and a round trip through SQLite reproduces every value"]', NULL, '["Export twice against an unchanged database and assert the files are identical", "Assert the file contains no CREATE, DROP, TRIGGER or VIEW", "Assert a value with quotes, newlines and unicode survives loading the file into a fresh database", "Assert a table added to the database appears in the export without code changes"]', NULL, NULL, '2026-09-28 20:41:00', '2026-09-28 20:43:26', '2026-09-28 20:43:26', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'src/lifecycle_mcp/dump.py export_rows() reads through a mode=ro connection in one read transaction, finds every data table from sqlite_master (a table a future migration adds is exported with no code change, tested by adding one), writes each INSERT with named columns in primary-key order, and puts no time, host or path in the file - an export of the same tracker VACUUMed to another path is byte-identical. Each row is exactly one line: line breaks inside values are spliced as char(10) and char(13), because this repository''s pre-commit config runs trailing-whitespace, end-of-file-fixer and mixed-line-ending, and two stored comments already contain line breaks those fixers would have rewritten. write_dump() leaves the file untouched, not rewritten, when nothing changed. Against the live tracker: deterministic, 1276 statements across 7 tables, every one an INSERT INTO, and every value round-trips into a fresh copy of the schema. 719 KB, over check-added-large-files'' 500 KB default - handled in TASK-0103. An early check "found" CREATE and TRIGGER in the dump; they were inside records that discuss them, so the tests assert statement structure rather than substrings. 20 tests.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0102-00-00', 102, 0, 0, 'Rebuild a tracker from the dump, safely', 'Complete', 'P1', 'L', 'As someone with a clone and no database, I need to rebuild the tracker from the committed dump without being able to destroy a tracker I already have.', '["Builds the schema to the dump''s own schema_version from the baseline, loads the rows, then applies the checkout''s remaining migrations, so an older dump is carried forward the way an existing database is", "Refuses a dump whose schema_version is ahead of the checkout''s migrations, naming both versions, and writes nothing", "Executes only INSERT statements into tables the schema has; any other statement in the file is refused before anything is written", "Refuses a target that already holds records, naming them by table and count, unless --force is given", "Can build into any path with --into, so a rebuild can be inspected before it replaces anything", "Builds beside the target and moves it into place only after it verifies, so an interrupted restore leaves the target as it was", "Removes the target''s stale -wal and -shm when it replaces it, because an old write-ahead log beside a new database would be applied to it", "Verifies itself: row counts match the dump for every table, and when the dump is at the checkout''s version, re-exporting the rebuilt tracker reproduces the dump byte for byte", "Refuses to replace a tracker a running server holds open, or documents plainly that the server must be stopped first"]', NULL, '["Export, restore into a fresh path, export again: byte-identical", "Restore over a populated database without --force: refused, counts named, database unchanged", "Restore a dump with a schema_version one above the checkout: refused, nothing written", "Restore a dump made at an older schema version: loads, migrates forward, counts match", "A dump containing a CREATE or DELETE statement: refused before any write", "A failure mid-load leaves the original target byte-identical"]', NULL, NULL, '2026-09-28 20:41:00', '2026-09-28 20:50:12', '2026-09-28 20:50:12', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'restore() in src/lifecycle_mcp/dump.py plus scripts/tracker_dump.py. It parses the dump and refuses any statement that is not an INSERT into a named table before writing anything (DELETE, CREATE, PRAGMA and a DROP smuggled after an INSERT on the same line are all tested); refuses a dump newer than the checkout''s migrations, naming both versions; and refuses a target holding records unless --force, naming them by table and count. It builds beside the target as <name>.restoring.db, which the *.db ignore rule covers if a restore is killed: create_baseline() (extracted from DatabaseManager so both create databases one way), migrations to the dump''s own version, the rows in one transaction, then the remaining migrations - so a version-17 dump comes back with migration 18''s origin column filled, the same path an existing database takes. It verifies counts, and at the current version that re-exporting reproduces the dump byte for byte, then swaps the file in with os.replace after checkpointing the old tracker and removing its -wal and -shm, so an old log is never applied to the new file and an interrupted restore leaves the original whole. The byte check caught a real bug on its first run against this repository''s tracker: loading relationships fired the counter triggers, whose UPDATE on requirements fires update_requirement_timestamp, and 27 requirements came back edited at the moment of the restore. Records now load last, so those triggers find nothing to touch. A test sets a 2020 timestamp with the trigger out of the way and was checked against the old order, where it fails; the plain round trip does not, because in a fixture everything happens in one second. The live tracker rebuilds in 0.39 s and exports back byte-identical. 14 restore tests, full suite 539 passed.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0103-00-00', 103, 0, 0, 'Keep the dump current on every commit', 'Complete', 'P1', 'S', 'As the owner, I need each commit to carry the tracker as it stood, without remembering to export it.', '["A local hook in .pre-commit-config.yaml regenerates the dump on every commit and stages it only when its content changed", "When the content is unchanged it writes nothing and stages nothing, so a code-only commit carries no dump diff", "It exports this repository''s lifecycle.db and never the database LIFECYCLE_DB names", "A clone with no lifecycle.db commits normally; the hook has nothing to export and says so without failing", "The dump fits check-added-large-files, or that hook''s limit is raised for this one file deliberately and the reason is written beside it"]', NULL, '["Unchanged tracker: the hook''s export step reports nothing to stage", "Changed tracker: the file is rewritten and the stage step is asked to add exactly that file", "LIFECYCLE_DB set elsewhere: the repository''s tracker is exported regardless", "No lifecycle.db: exits 0 with a note"]', NULL, NULL, '2026-09-28 20:41:00', '2026-09-28 22:47:38', '2026-09-28 22:47:38', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'A tracker-dump hook in the local section of .pre-commit-config.yaml runs `scripts/tracker_dump.py export --stage` on every commit (always_run, since the tracker changes without any tracked file changing). run_export writes and stages the dump only when its content changed; an unchanged tracker writes nothing and stages nothing; a clone with no lifecycle.db exits 0 with a note and creates nothing; LIFECYCLE_DB is never read. Run for real from the repository root: the first run wrote lifecycle-data.sql (723 KB) and staged it, the second reported it current and did nothing. The dump is excluded from check-added-large-files, with the reason beside it (diffable text that grows with an event log that cannot be trimmed), and from trailing-whitespace, end-of-file-fixer and mixed-line-ending, which the one-row-per-line format already gives nothing to change. .gitattributes marks it linguist-generated so GitHub collapses its diffs. 12 tests, git staging exercised through an injected recorder because the suite may not spawn git; full suite 551 passed. NOT YET EFFECTIVE, and this matters: pre-commit is not a declared dependency and is not installed, so no hook in this config runs on any commit today. Installing it would also activate the existing mypy hook, which runs --strict and finds 175 errors, blocking every commit, and pytest-check, which runs the full suite (about 90 s) per commit. Activation is the owner''s decision, raised with the PR.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0104-00-00', 104, 0, 0, 'Make targets, docs, and the first committed dump', 'Complete', 'P1', 'S', 'As anyone cloning the repository, I need to know the dump exists, what it is for, and how to rebuild a tracker from it.', '["make tracker-export and make tracker-restore run the two halves without a commit", "README says what the file is, that the database is local and ignored, that the file is generated and never hand-edited, how to rebuild from a clone, and to stop the server before restoring over a live tracker", "CLAUDE.md names the dump and its rule: the schema lives in migrations, never in the dump", "This repository''s own tracker is exported and committed, so the work recorded so far is finally in version control"]', NULL, '["Assert both make targets call the script with the arguments passed through", "Assert the README section covers regenerating, rebuilding, never hand-editing, and stopping the server before a restore", "Assert CLAUDE.md names the dump and says the schema is never in it", "Restore the committed dump into a scratch path and assert its counts match the live tracker it came from"]', NULL, NULL, '2026-09-28 20:41:00', '2026-09-28 22:50:36', '2026-09-28 22:50:36', NULL, NULL, NULL, NULL, 1, NULL, NULL, 'make tracker-export and make tracker-restore (INTO= and FORCE= passed through); a README section "The Tracker in Git" covering why the database cannot simply be committed, that the dump is generated and never hand-edited, rows not schema, determinism, rebuilding from a clone, the refusal to overwrite records, stopping the server before replacing a live tracker, older dumps carried forward and newer refused, LIFECYCLE_DB not consulted, and that the hook needs pre-commit installed; CLAUDE.md commands plus the dump''s rules. A test restores the committed lifecycle-data.sql in CI, so a hand-edited or corrupted dump fails the build rather than someone''s restore - CI cannot see the tracker, but it can see the dump. This repository''s tracker is exported as the final step, after this status change, and the committed file is checked to restore to the live tracker''s counts. 16 command tests, full suite 555 passed.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0105-00-00', 105, 0, 0, 'Migration 19: projects table, part_of links, comments on projects', 'Complete', 'P1', 'M', NULL, '["projects table exists with a required purpose", "relationships and reviews admit the project type and part_of, keeping every row, comment id and trigger", "The dump lists projects before requirements and round-trips", "PROJ-1 resolves as a short ID"]', NULL, NULL, NULL, NULL, '2026-10-01 23:13:07', '2026-10-01 23:13:14', '2026-10-01 23:13:14', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite 581 passed, 3 skipped on 2026-09-30, including the 26 tests in tests/test_projects.py; scripts/mcp_handshake_smoke.py clean with 25 tools; lifecycle-data.sql restored to a scratch tracker migrated 18 to 19 with 181 links and 322 comments intact, and both export modes produced the expected documents.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0106-00-00', 106, 0, 0, 'create_project and update_project, with details, delete, comments and history for projects', 'Complete', 'P1', 'M', NULL, '["A blank purpose or unknown requirement refuses the call and writes nothing", "update_project edits content, status and membership in one revision", "get_details, add_comment, get_entity_history and delete_record take a PROJ id", "A project holding requirements is not deleted", "Tool budget and schema coverage tests cover the projects table"]', NULL, NULL, NULL, NULL, '2026-10-01 23:13:07', '2026-10-01 23:13:14', '2026-10-01 23:13:14', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite 581 passed, 3 skipped on 2026-09-30, including the 26 tests in tests/test_projects.py; scripts/mcp_handshake_smoke.py clean with 25 tools; lifecycle-data.sql restored to a scratch tracker migrated 18 to 19 with 181 links and 322 comments intact, and both export modes produced the expected documents.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0107-00-00', 107, 0, 0, 'Membership from the requirement end: project_ids, part_of in create_relationship, project filters', 'Complete', 'P1', 'S', NULL, '["create_requirement takes project_ids and refuses an unknown project", "create_relationship accepts part_of from either end", "query_requirements and query_tasks take project_id", "Requirement details list its projects"]', NULL, NULL, NULL, NULL, '2026-10-01 23:13:07', '2026-10-01 23:13:14', '2026-10-01 23:13:14', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite 581 passed, 3 skipped on 2026-09-30, including the 26 tests in tests/test_projects.py; scripts/mcp_handshake_smoke.py clean with 25 tools; lifecycle-data.sql restored to a scratch tracker migrated 18 to 19 with 181 links and 322 comments intact, and both export modes produced the expected documents.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0108-00-00', 108, 0, 0, 'Export opens with project purpose; export one project by project_id', 'Complete', 'P1', 'M', NULL, '["The whole-tracker requirements document opens with each project, its purpose and its requirements, then those in no project", "project_id writes three documents opening with the stored purpose and holding only that project''s records", "An empty project still exports its purpose", "A tracker with no projects exports as before"]', NULL, NULL, NULL, NULL, '2026-10-01 23:13:07', '2026-10-01 23:13:14', '2026-10-01 23:13:14', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite 581 passed, 3 skipped on 2026-09-30, including the 26 tests in tests/test_projects.py; scripts/mcp_handshake_smoke.py clean with 25 tools; lifecycle-data.sql restored to a scratch tracker migrated 18 to 19 with 181 links and 322 comments intact, and both export modes produced the expected documents.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0109-00-00', 109, 0, 0, 'Projects on the dashboard and in the viewer', 'Complete', 'P2', 'S', NULL, '["get_project_status lists active projects with requirement and task progress, counts closed ones and requirements in no project", "No Projects section when the tracker has none", "The viewer shows projects and part_of links from both ends", "The viewer reads a tracker from before migration 19"]', NULL, NULL, NULL, NULL, '2026-10-01 23:13:07', '2026-10-01 23:13:14', '2026-10-01 23:13:14', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite 581 passed, 3 skipped on 2026-09-30, including the 26 tests in tests/test_projects.py; scripts/mcp_handshake_smoke.py clean with 25 tools; lifecycle-data.sql restored to a scratch tracker migrated 18 to 19 with 181 links and 322 comments intact, and both export modes produced the expected documents.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0110-00-00', 110, 0, 0, 'Document projects in README, CLAUDE.md and CHANGELOG', 'Complete', 'P2', 'XS', NULL, '[]', NULL, NULL, NULL, NULL, '2026-10-01 23:13:07', '2026-10-01 23:13:14', '2026-10-01 23:13:14', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite 581 passed, 3 skipped on 2026-09-30, including the 26 tests in tests/test_projects.py; scripts/mcp_handshake_smoke.py clean with 25 tools; lifecycle-data.sql restored to a scratch tracker migrated 18 to 19 with 181 links and 322 comments intact, and both export modes produced the expected documents.');
INSERT INTO "tasks" ("id", "task_number", "subtask_number", "version", "title", "status", "priority", "effort", "user_story", "acceptance_criteria", "implementation_plan", "test_plan", "definition_of_done", "assignee", "created_at", "updated_at", "completed_at", "github_issue_number", "github_issue_url", "github_etag", "github_last_sync", "revision", "blocked_reason", "commit_ref", "evidence") VALUES ('TASK-0111-00-00', 111, 0, 0, 'project_id on query_architecture_decisions and create_architectural_diagrams; projects in both prompts', 'Complete', 'P2', 'S', NULL, '["query_architecture_decisions(project_id) returns the decisions the project''s requirements address", "status and type filters apply together with requirement_id or project_id", "create_architectural_diagrams(project_id) draws only that project''s records; an empty project draws nothing rather than everything", "capture_requirement and reconcile_requirements name project_ids and where to find the projects"]', NULL, NULL, NULL, NULL, '2026-10-01 23:53:31', '2026-10-01 23:53:38', '2026-10-01 23:53:38', NULL, NULL, NULL, NULL, 0, NULL, NULL, 'Full suite 586 passed, 3 skipped on 2026-10-01, including five new tests in tests/test_projects.py for the decision query, the diagram and the prompts; handshake smoke clean with 25 tools and 2 prompts.');
INSERT INTO "architecture" ("id", "type", "title", "status", "context", "decision_drivers", "considered_options", "decision_outcome", "consequences", "implementation_notes", "validation_criteria", "risk_assessment", "authors", "deciders", "created_at", "updated_at", "superseded_by", "revision") VALUES ('ADR-0001', 'ADR', 'Unified relationships table as the single link store, with atomic migrations', 'Accepted', 'Links are currently split between four legacy tables plus tasks.parent_task_id and the relationships table introduced in commit a964311. Handlers, views and triggers read and write inconsistently, and migration 7 drops legacy tables non-atomically, which broke trace_requirement and blocked-item reporting in the field test (F-18, F-20).', '["One source of truth for traceability", "No partial schema changes, ever", "Existing user databases must upgrade without losing links"]', '["Revert to the legacy link tables", "Keep both stores and sync them with triggers", "Finish the move to relationships with atomic migrations"]', 'Make relationships the only store for links between requirements, tasks and ADRs. Finish the refactor by moving every writer and reader to it. Replace migrations 6 and 7 with one consolidation migration that copies all legacy rows, rebuilds tasks without parent_task_id while preserving constraints, and drops legacy tables. Run every migration inside one explicit transaction and abort server startup on failure. Add a repair migration for databases left damaged by the partial migration 7.', '{"good": ["Readers and writers agree", "New relationship types need no schema change", "Upgrades are all-or-nothing"], "bad": ["Touches every handler and several views and triggers", "A repair path is needed for databases already damaged"]}', NULL, NULL, NULL, '["Claude (lifecycle field test, 2026-09-14)"]', NULL, '2026-09-14 16:37:15', '2026-09-14 16:37:15', NULL, 0);
INSERT INTO "architecture" ("id", "type", "title", "status", "context", "decision_drivers", "considered_options", "decision_outcome", "consequences", "implementation_notes", "validation_criteria", "risk_assessment", "authors", "deciders", "created_at", "updated_at", "superseded_by", "revision") VALUES ('ADR-0002', 'ADR', 'Tool surface target: per-type tools only where inputs differ', 'Accepted', 'lifecycle-mcp lists 39 tools whose definitions add 17,136 characters (about 4.3k tokens) to every request. Usage evidence from two Quire lifecycle sessions (docs/tool-surface/usage-evidence.md) found nine tools never called (15% of the size), requirement and task status changes about half of all calls, interviews producing only placeholders, and the three update tools at 23% of the size. The inventory (docs/tool-surface/inventory.md) classifies every tool with that evidence, and tests/tool_surface_budget.json now fails CI when the surface grows.', '["Tool definitions cost client context on every request", "Decisions rest on usage evidence from real sessions", "No loss of capability except the interviews, which produce nothing usable", "Each tool changes once across R9, R10, R11, R13 and R16"]', '["Keep all 39 tools and rely on the budget to stop growth", "Generic tools with an entity_type parameter for every operation", "Fold ID-only operations across record types; keep per-type tools where inputs differ", "Also fold the three status tools into one update_status"]', 'Adopt the inventory''s target surface: 23 tools and about 12.7k definition characters with GitHub off, 24 with it on. Create, update, status and query tools stay per record type. ID-only operations fold into get_details, delete_record and add_comment; the three relationship queries merge into query_relationships; the *_json tools and get_project_metrics fold into structured results (R10); one sync_github_tasks is registered only when LIFECYCLE_GITHUB=on; the four interview tools and the diagrams tool''s interactive parameter are removed; descriptions are trimmed. Renamed tools get no aliases, and R16''s changelog lists each removal and its replacement. Rules for future tools: one tool per record type only where inputs differ; one tool per operation, not per output format, returning structuredContent without an outputSchema unless the budget allows; opt-in features register their tools only when enabled; no multi-step conversation tools without persisted state; the budget moves in the same change as the surface, and each fold lowers it.', '{"good": ["About 26% less definition size and 16 fewer tools by default", "Requirements and tasks can be commented on through add_comment (F-39)", "A clear rule for where new tools go"], "bad": ["Clients break once on removed and renamed tools", "No guided requirement capture until R11 decides a replacement", "The *_json folds wait for R10''s structured results"], "neutral": ["The status tools keep their names and stay the most-called; R9 adds bulk transitions to them"]}', NULL, '["After R16, tools/list shows 23 tools with GitHub off and 24 with it on", "tests/tool_surface_budget.json is lowered to the measured surface after each fold", "Every acceptance test that used a removed or renamed tool passes with its replacement", "The R6a acceptance and schema coverage tests still pass"]', '["Clients that call removed tool names break: likely, medium impact; changelog lists every replacement", "Generic ID tools hide which fields each record type has: possible, low impact; details keep per-type sections", "R10 slips and the *_json folds lose JSON output: possible, medium impact; fold them only with R10"]', '["Claude"]', '["Owner (heffrey78)"]', '2026-09-15 01:10:45', '2026-09-15 01:45:56', NULL, 0);
INSERT INTO "architecture" ("id", "type", "title", "status", "context", "decision_drivers", "considered_options", "decision_outcome", "consequences", "implementation_notes", "validation_criteria", "risk_assessment", "authors", "deciders", "created_at", "updated_at", "superseded_by", "revision") VALUES ('ADR-0003', 'ADR', 'Bulk and multi-step status changes and design links without new tools', 'Accepted', 'R9: status changes are about half of all tool calls, one record and one step per call (docs/tool-surface/usage-evidence.md). A task can''t link to the ADR it implements, and an ADR can''t link to the decision it replaces, so superseded_by stays NULL (F-19, F-30). ADR-0002 caps the surface at 23 tools and keeps status tools per record type; ADR-0001 makes relationships the only link store.', '["Routine status moves take one call", "No new tools (ADR-0002)", "One link store (ADR-0001)", "History still shows every step", "superseded_by and status never contradict the link"]', '["A new bulk status tool: one more tool against ADR-0002''s target", "One update_status tool for all record types: R15 kept status tools per type", "An explicit path parameter: callers would need to know the transition map", "Supersession only in architecture.superseded_by: a second link store, against ADR-0001", "A trigger that also sets Superseded: hides a status change inside a link write"]', '1. Each status tool also accepts a list (requirement_ids, task_ids, architecture_ids). Every ID moves independently in its own transaction and gets its own result; the call is an error only when every ID is refused. 2. update_requirement_status walks the shortest allowed path to new_status, but never through Approved or Validated: one call moves a requirement up to Approved or onward from it, and reaches Validated only as its target, because tasks and ADRs are planned against an approved requirement and validation is a deliberate step. Gates are checked for the whole path first, every step is applied in one transaction and logged as its own status change, and the comment is added once. Tasks and ADRs have no transition map yet (R8), so they move directly. 3. relationships gains task -> architecture implements (either order accepted) and architecture -> architecture supersedes (new -> old). Migration 14 rebuilds relationships to allow supersedes, keeping its views, triggers and indexes, and adds triggers that keep architecture.superseded_by equal to the incoming supersedes link. Creating a supersedes link moves the old ADR to Superseded in the same transaction. update_architecture_status refuses Superseded without such a link and refuses leaving Superseded while one exists.', '{"good": ["Approving many requirements through review is one call", "Tool count stays at 23", "Supersession is visible from both ADRs and in history"], "bad": ["Status and relationship definitions grow; the budget is raised on purpose", "One call can cross review states; R8''s enforce mode may restrict multi-step moves", "Migration 14 rebuilds the relationships table"], "neutral": ["List calls return a results array in structuredContent; single-ID calls keep their shape"]}', NULL, NULL, NULL, '["MCP User"]', NULL, '2026-09-15 17:04:20', '2026-09-15 21:26:43', NULL, 2);
INSERT INTO "architecture" ("id", "type", "title", "status", "context", "decision_drivers", "considered_options", "decision_outcome", "consequences", "implementation_notes", "validation_criteria", "risk_assessment", "authors", "deciders", "created_at", "updated_at", "superseded_by", "revision") VALUES ('ADR-0004', 'ADR', 'Workflow rules: one strictness setting, warnings carried by the existing responses', 'Accepted', 'R8: dependencies, parent completion with open subtasks and task skips are honour-system (F-24, F-25); ADR statuses have no rules beyond R9''s Superseded link (F-13); R7 leaves a task waiting on an abandoned dependency with nothing saying so. ADR-0002 caps the surface at 23 tools, so a rules tool or a per-rule parameter is out. The owner chose warn as the default and flagging only task skips and reopens (2026-09-15).', '["No new tool and no per-call parameter (ADR-0002)", "Existing projects keep today''s outcomes", "One place decides strictness, so rules read the same everywhere", "Abandoned dependencies stop being silent (R7 follow-up)"]', '["A strictness tool or parameter: more surface, against ADR-0002", "A project settings table: needs a tool or hand-edited SQL to set", "Enforce by default: breaks flows that move a task straight to Complete", "Off by default: the rules stay invisible to anyone who does not know the flag", "A full task transition map: more false alarms than the skips and reopens the lab actually hit"]', '1. LIFECYCLE_RULES picks off, warn or enforce, like LIFECYCLE_GITHUB. warn is the default: every call has the outcome it has today and a risky move only gains an explanation. enforce refuses the move; off checks nothing. An unrecognised value falls back to warn and is logged. 2. A rules module decides, per status move, why the move is risky. Handlers collect those reasons and hand them to one BaseHandler helper: it returns nothing in off mode, returns warnings in warn mode, and raises StatusRefused in enforce mode. Warnings ride on the existing status tool response, in the text and in structuredContent, per record for list moves. 3. The rules: unmet dependencies when a task starts or completes, with abandoned dependencies named as abandoned and the two ways out (delete the link, or abandon the waiting task); a parent task completing while a subtask is open; task skips and reopens, meaning Not Started or Blocked straight to Complete and reopening a Complete task; a requirement reaching Implemented while linked tasks are open; and ADR status moves outside the allowed set, with the TDD vocabulary kept as its own chain. 4. Rules that protect what the server maintains itself stay always on and outside the setting: the Validated gate, R9''s Superseded link and the requirement transition map.', '{"good": ["Risky moves explain themselves without changing any outcome", "A project that wants a hard gate sets one variable", "Tool count stays 23"], "bad": ["Warning text appears in responses that used to be silent", "Rules split across handlers must each remember to call the helper"], "neutral": ["structuredContent gains a warnings field only when there are warnings"]}', NULL, NULL, NULL, '["MCP User"]', NULL, '2026-09-16 00:30:31', '2026-09-16 00:54:21', NULL, 0);
INSERT INTO "architecture" ("id", "type", "title", "status", "context", "decision_drivers", "considered_options", "decision_outcome", "consequences", "implementation_notes", "validation_criteria", "risk_assessment", "authors", "deciders", "created_at", "updated_at", "superseded_by", "revision") VALUES ('ADR-0005', 'ADR', 'Exploratory work: a spike is a task whose deliverable is a decision', 'Proposed', 'REQ-0012 and REQ-0013 are open-ended in a way the roadmap requirements before them were not. R1 through R20 each closed a numbered finding from a dogfooding run: the defect had been observed, the fix was known in outline, and only the how was open. Reconciling requirements from an existing codebase and detecting drift against code are research. Some approaches will not work, and knowing which ones failed is most of what the work produces. The lifecycle model runs Draft, Under Review, Approved, Architecture, Ready, Implemented, Validated, which assumes at Draft that you already know what you want. Nothing in the task vocabulary records a negative result: under R8''s warn rules a task moving from Not Started or Blocked straight to Complete is flagged as a skip (ADR-0004), so a spike that ends by ruling an approach out trips the same warning as a task somebody abandoned. The honest outcome of research therefore looks like a gap in the tracker, which is a reason not to record it, which is how the knowledge gets lost. Three dogfooding runs have already produced findings that live only in lab notebooks for want of anywhere else to put them.', '["Research with no way to record a negative result silently punishes recording it", "ADR-0002 caps the tool surface, so a convention that needed a tool would not be worth its cost", "Proposed to Rejected already exists in the ADR status map and has never been used", "Dead ends are the expensive knowledge: with no record, the next person repeats the experiment"]', '["A distinct Spike task type or status: new vocabulary, a schema change and a second path through the rules, for something the existing statuses already express", "Keeping spikes out of the tracker in the lab notebooks: what happens today, and the reason the origins of R15 through R20 are recoverable only by reading three separate run notebooks", "A research requirement whose acceptance criterion is a decision rather than a behaviour: kept, and part of this decision rather than an alternative to it", "Recording a dead end only as a Deprecated requirement: loses which approaches were tried and why each one failed"]', 'A spike is an ordinary Task whose deliverable is a decision record rather than code, and it Completes whichever way the question resolves. The convention uses machinery that already exists and adds no tool, no status and no column. 1. The spike task is linked to the requirement it explores, like any other task. 2. Its deliverable is an ADR: a direction that works is Accepted; a direction ruled out is created Proposed and moved to Rejected, which the status map in architecture_handler.py already allows and which no ADR in this tracker has yet used. The Rejected ADR holds why, and that record is what the spike produced. 3. The task''s evidence field (migration 17) carries the finding and the commit or branch it was tried on, and the task moves to Complete with that evidence attached; completing a spike that ruled an approach out is not a skip. 4. A requirement whose spikes rule out every approach is Deprecated, as REQ-0002-FUNC-00 already was, rather than left open indefinitely.', '{"positive": ["Negative results become records instead of gaps, using statuses that already exist", "The R8 skip warning keeps its meaning, because a spike Completes carrying evidence rather than jumping", "No tool, status, column or migration: the tool surface budget is untouched", "A Rejected ADR is readable by anyone with the tracker, unlike a finding buried in a lab notebook"], "negative": ["A convention with nothing enforcing it, which is how R8''s honour-system rules already work and what the owner chose deliberately in ADR-0004", "Rejected ADRs accumulate against requirements that were never built, so query_architecture_decisions returns records for work that does not exist", "It asks a judgement of the author: whether an approach was genuinely ruled out or merely not finished"]}', 'Proposed, not Accepted, deliberately. Every ADR in this tracker so far records a choice the owner actually made, and ADR-0004 names the date it was made. This one records a way of working that has not been decided, so Proposed is its honest state. Rejecting it costs nothing and would itself be an instance of the convention working.', '["A spike that ruled an approach out leaves a Rejected ADR naming why, a Complete task carrying the evidence, and no warning implying something was skipped", "Someone reading the tracker a month later can tell which approaches to REQ-0012 and REQ-0013 were tried and rejected without opening a lab notebook"]', '["Rejected ADRs are read as decisions in force, Low, Medium, status is shown wherever an ADR is listed and Rejected is visibly distinct from Accepted", "The convention is skipped under time pressure and dead ends go unrecorded again, Medium, Medium, the spike task cannot Complete without evidence, the same discipline R12 already applies to ordinary tasks"]', '["Claude (brainstorm with Jeff Wikstrom, 2026-09-17)"]', NULL, '2026-09-17 22:50:39', '2026-09-17 22:50:39', NULL, 0);
INSERT INTO "architecture" ("id", "type", "title", "status", "context", "decision_drivers", "considered_options", "decision_outcome", "consequences", "implementation_notes", "validation_criteria", "risk_assessment", "authors", "deciders", "created_at", "updated_at", "superseded_by", "revision") VALUES ('ADR-0006', 'ADR', 'A project is its own record; membership is a part_of link from requirements only', 'Accepted', 'Requirements needed an owning concept with a canonical purpose (REQ-0015-FUNC-00). Three questions shaped the model: what a project is, how many projects a requirement may be in, and which records are members. The uses named were epics, roadmap items and layers of software, which cut across each other over the same requirements.', '["Epics, roadmap items and layers overlap over the same requirements", "The requirement transition map and its gates are always-on rules (ADR-0004) and should not bend to fit a container", "relationships is the only link store (ADR-0001)", "One membership to maintain, so export cannot disagree with the links"]', '["Own record type with part_of links (chosen)", "A top-level requirement of a new GOAL type with children under the existing parent link: no new table, but the goal would have to pass Draft, Approved and Validated", "Exactly one project per requirement: counts partition cleanly, but epics and layers cannot both be projects", "One project per requirement with nested projects: gives roll-ups, still no cross-cutting groupings", "Tasks and decisions as direct members: covers orphans, but a task could sit in a different project from its requirement"]', 'A project is a new record type in its own table (PROJ-0001) with a required purpose. Membership is a requirement -> project part_of row in relationships, with no uniqueness across projects, so a requirement can be in several. Only requirements are members; a task or decision belongs to a project through the requirement it implements or addresses. PROJECT_REQUIREMENT_IDS_SQL is the single definition of membership.', '{"positive": ["A requirement can sit in an epic and a layer at once", "No change to requirement statuses, gates or counters", "Deleting a requirement removes its memberships with its other links"], "negative": ["Per-project counts overlap and do not add up to the tracker totals", "A task or decision linked to no requirement is in no project", "Migration 19 rebuilds relationships and reviews, whose CHECK constraints name the record types"]}', NULL, NULL, NULL, '["Claude"]', '["Jeff Wikstrom"]', '2026-10-01 23:12:53', '2026-10-01 23:13:07', NULL, 0);
INSERT INTO "architecture" ("id", "type", "title", "status", "context", "decision_drivers", "considered_options", "decision_outcome", "consequences", "implementation_notes", "validation_criteria", "risk_assessment", "authors", "deciders", "created_at", "updated_at", "superseded_by", "revision") VALUES ('ADR-0007', 'ADR', 'Projects add two tools; everything else rides on existing ones', 'Accepted', 'Every tool definition costs client context on every request (roadmap R15, ADR-0002). A new record type could have brought create, update, status, query, details, delete and comment tools of its own. These choices were made during implementation and have not been separately confirmed by the owner.', '["Tool surface budget", "Per-type tools only where inputs differ (ADR-0002)", "Deletes only remove records nothing depends on"]', '["Two tools plus parameters on existing ones (chosen)", "A full per-type set including update_project_status and query_projects", "Membership only through create_relationship, with no bulk add or remove"]', 'Only create_project and update_project are new. A project is Active or Closed, set as an ordinary field of update_project, because closing has no gate. get_details, delete_record, add_comment and get_entity_history take a PROJ id through the existing prefix dispatch. There is no query_projects: the dashboard lists projects. Filtering is a project_id parameter on query_requirements, query_tasks and export_project_documentation. delete_record refuses a project that still holds requirements.', '{"positive": ["23 to 25 tools, 13,185 to 14,871 characters, rather than five or more new tools"], "negative": ["No way to list projects without the dashboard", "get_project_status, create_architectural_diagrams, query_architecture_decisions and trace_requirement know nothing of projects yet"]}', NULL, NULL, NULL, '["Claude"]', NULL, '2026-10-01 23:12:53', '2026-10-01 23:13:07', NULL, 0);
