INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (116, 'task', 'TASK-0027-00-00', 'status_change', 'In Progress', 'Complete', NULL, '2026-09-14 20:48:04', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (117, 'task', 'TASK-0019-00-00', 'field_edit', '["update_requirement edits content fields in one call; the change appears in details, trace and export", "At Approved or later a reason is required; without one the call is refused with that message", "Edits at Approved or later set the changed-since-approval marker, shown in get_requirement_details, trace_requirement and get_project_status", "New acknowledge_requirement_changes tool records who accepted the changes and clears the marker"]', '["update_requirement edits content fields in one call; the change appears in details, trace and export", "At Approved or later a reason is required; without one the call is refused with that message", "A requirement shows as changed since last review when a content edit comes after its latest status change; shown in get_requirement_details, trace_requirement and get_project_status", "The next status transition clears the marker and its comment serves as the acknowledgement; no stored marker and no acknowledgement tool"]', 'Claude Code', '2026-09-14 22:07:27', 'acceptance_criteria', 'Align with owner revision of 2026-09-14: marker is derived from edit and status events, no acknowledge_requirement_changes tool');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (118, 'task', 'TASK-0019-00-00', 'status_change', 'Not Started', 'In Progress', NULL, '2026-09-14 22:19:07', NULL, NULL);
