INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (156, 'requirement', 'REQ-0002-INTF-00', 'field_edit', '["Apply the R15 ADR''s keep, fold, conditional and remove decisions", "Folded capabilities stay reachable through the remaining tools'' parameters", "Opt-in features register their tools only when enabled", "Coordinate with R10 (*_json folding), R11 (interviews) and R13 (diagrams) so each tool changes once", "README, CLAUDE.md and a changelog entry list removed or renamed tools and their replacements"]', '["Apply ADR-0002: get_details, delete_record and add_comment replace the per-type ID-only tools; one query_relationships replaces three; one sync_github_tasks registered only when LIFECYCLE_GITHUB=on; the interview tools and the diagrams tool''s interactive parameter are removed; descriptions are trimmed", "Folded capabilities stay reachable through the remaining tools'' parameters", "Renamed tools get no aliases; a changelog lists every removed tool and its replacement, alongside README and CLAUDE.md", "Coordinate with R10 (*_json and project metrics folds), R11 (any interview replacement) and R13 (diagram output) so each tool changes once"]', 'Claude', '2026-09-15 13:39:19', 'functional_requirements', 'Align with accepted ADR-0002 and the owner''s decisions; R10 owns the *_json and project metrics folds');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (157, 'requirement', 'REQ-0002-INTF-00', 'field_edit', '["tools/list matches the ADR''s target tool count and stays within the recorded size budget", "Every acceptance test that used a removed or renamed tool passes using its replacement", "The MCP handshake smoke test and the install smoke workflow pass"]', '["tools/list matches ADR-0002''s target once R10''s folds land: 23 tools with GitHub off, 24 with it on. R16 alone reaches 27 and 28", "tests/tool_surface_budget.json is lowered to the measured surface in each change that folds or removes tools", "Every acceptance test that used a removed or renamed tool passes using its replacement", "The MCP handshake smoke test and the install smoke workflow pass"]', 'Claude', '2026-09-15 13:39:19', 'acceptance_criteria', 'Align with accepted ADR-0002 and the owner''s decisions; R10 owns the *_json and project metrics folds');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (158, 'requirement', 'REQ-0002-INTF-00', 'status_change', 'Draft', 'Under Review', NULL, '2026-09-15 13:39:30', NULL, NULL);
