INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (184, 'requirement', 'REQ-0001-INTF-00', 'field_edit', '["Remove the LLM-unavailable warning", "Return structuredContent JSON alongside the text summary", "Fold the *_json tools into their counterparts"]', '["Remove the LLM-unavailable warning from create_requirement", "Tools return structuredContent JSON alongside their text summary, without declaring an outputSchema (ADR-0002 budget rule)", "Fold query_requirements_json, query_tasks_json, query_architecture_decisions_json and get_project_metrics into structured results of query_requirements, query_tasks, query_architecture_decisions and get_project_status"]', 'Claude', '2026-09-15 14:26:17', 'functional_requirements', 'Align with ADR-0002: get_project_metrics folds under R10 as well, and structured results declare no outputSchema');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (185, 'requirement', 'REQ-0001-INTF-00', 'field_edit', '["create_requirement''s response is a single status line plus structured data", "The tool count drops by three with no loss of capability"]', '["create_requirement''s response is a single status line plus structured data", "query_requirements, query_tasks, query_architecture_decisions and get_project_status return structured results carrying what the folded tools returned", "The tool count drops by four with no loss of capability: 23 tools by default, 24 with LIFECYCLE_GITHUB=on (ADR-0002 target)", "tests/tool_surface_budget.json is lowered to the measured surface"]', 'Claude', '2026-09-15 14:26:17', 'acceptance_criteria', 'Align with ADR-0002: get_project_metrics folds under R10 as well, and structured results declare no outputSchema');
