INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (224, 'requirement', 'REQ-0001-INTF-00', 'status_change', 'Implemented', 'Validated', NULL, '2026-09-15 16:22:58', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (225, 'requirement', 'REQ-0003-FUNC-00', 'field_edit', 'No query returns tasks whose dependencies are complete, and task details omit dependencies and comments (F-21). Blocked shows only as a count, with no task or reason (F-29). Metrics report 100% while traceability tables are missing (F-32).', 'Task details (get_details) show comments since R16 but not dependencies: blocked-by and blocks need a separate query_relationships call (F-21). No query returns tasks whose dependencies are all Complete. The dashboard''s Blocked Items section works again since R3, but it only lists tasks with dependency links; a task marked Blocked without links shows only in the status count, and there is no field for the reason (F-29). The schema damage behind F-32 can no longer be served: since R3 a failed migration rolls back and stops the server.', 'MCP User', '2026-09-15 17:01:17', 'current_state', 'Brought up to date after R3, R10, R15 and R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (226, 'requirement', 'REQ-0003-FUNC-00', 'field_edit', 'An agent can ask for the next workable tasks, see why anything is blocked, and trust the health view.', 'An agent can ask for the next workable tasks and see why anything is blocked.', 'MCP User', '2026-09-15 17:01:17', 'desired_state', 'Brought up to date after R3, R10, R15 and R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (227, 'requirement', 'REQ-0003-FUNC-00', 'field_edit', '["A next-tasks tool returns not-started tasks whose dependencies are all complete, in priority order", "get_task_details shows blocked-by, blocks and review comments", "Tasks have a blocked reason; the dashboard lists blocked items with their reasons", "Project status includes a schema health check"]', '["query_tasks can return only Not Started tasks whose dependencies are all Complete, in priority order", "get_details on a task shows the tasks it depends on and the tasks it blocks", "A task can record why it is blocked; the dashboard lists every Blocked task with its reason and blocking items"]', 'MCP User', '2026-09-15 17:01:17', 'functional_requirements', 'Brought up to date after R3, R10, R15 and R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (228, 'requirement', 'REQ-0003-FUNC-00', 'field_edit', '["next-tasks excludes a task until its dependency is Complete", "A task marked Blocked with a reason appears by name on the dashboard", "A database missing a required table is reported as unhealthy"]', '["The ready-to-start query excludes a task until each of its dependencies is Complete", "get_details on a task lists the tasks it depends on and the tasks it blocks", "A task marked Blocked with a reason and no dependency links appears by name, with its reason, on the dashboard"]', 'MCP User', '2026-09-15 17:01:17', 'acceptance_criteria', 'Brought up to date after R3, R10, R15 and R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (229, 'requirement', 'REQ-0003-FUNC-00', 'field_edit', 'Closes F-21, F-29, F-32. Evidence: claude-lifecycle-lab/NOTES.md.', 'Closes F-21 and F-29; R3 removed F-32''s cause. Evidence: claude-lifecycle-lab/NOTES.md.', 'MCP User', '2026-09-15 17:01:17', 'business_value', 'Brought up to date after R3, R10, R15 and R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (230, 'requirement', 'REQ-0003-FUNC-00', 'field_edit', NULL, '["ADR-0002: prefer a query_tasks filter to a new tool; any new tool or parameter raises tests/tool_surface_budget.json in the same change"]', 'MCP User', '2026-09-15 17:01:17', 'technical_constraints', 'Brought up to date after R3, R10, R15 and R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (231, 'requirement', 'REQ-0003-FUNC-00', 'field_edit', NULL, '["A schema health check on the dashboard: since R3 a failed migration rolls back and stops the server, which removed F-32''s cause"]', 'MCP User', '2026-09-15 17:01:17', 'out_of_scope', 'Brought up to date after R3, R10, R15 and R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (232, 'requirement', 'REQ-0004-FUNC-00', 'field_edit', NULL, '["ADR-0002: configure strictness without adding a tool unless the tool surface budget is raised on purpose"]', 'MCP User', '2026-09-15 17:01:17', 'technical_constraints', 'Brought up to date after R16 and the R9 refresh');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (233, 'requirement', 'REQ-0004-FUNC-00', 'field_edit', NULL, '["Superseding an ADR: R9 ties Superseded to a supersedes link", "Content edits: R6a already limits ADR edits to Proposed and requires a reason for requirement edits at Approved or later"]', 'MCP User', '2026-09-15 17:01:17', 'out_of_scope', 'Brought up to date after R16 and the R9 refresh');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (234, 'requirement', 'REQ-0005-FUNC-00', 'field_edit', 'A task can''t be linked to the ADR it implements (F-19). Superseding an ADR leaves superseded_by NULL, with only a free-text comment linking the two (F-30). Status transitions were 54% of all calls, one hop per call (F-11).', 'A task can''t be linked to the ADR it implements: create_relationship rejects task -> architecture (F-19). Moving an ADR to Superseded leaves superseded_by NULL; no tool sets it and no relationship type links the two decisions (F-30, F-13). Status changes were 49% of calls in the original lab session and 47% in the re-run, one record and one step per call (F-11, docs/tool-surface/usage-evidence.md).', 'MCP User', '2026-09-15 17:01:17', 'current_state', 'Brought up to date after R10, R15 and R16: tool names, measured call share, ADR-0002 constraints');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (235, 'requirement', 'REQ-0005-FUNC-00', 'field_edit', 'Design decisions trace to the work that implements them, and routine status moves take one call.', 'Design decisions trace to the work that implements them and to the decisions that replace them, and routine status moves take one call.', 'MCP User', '2026-09-15 17:01:17', 'desired_state', 'Brought up to date after R10, R15 and R16: tool names, measured call share, ADR-0002 constraints');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (236, 'requirement', 'REQ-0005-FUNC-00', 'field_edit', '["Relationships support task implements ADR and ADR supersedes ADR", "Superseding sets superseded_by and moves the old ADR to Superseded", "A batch transition tool moves many entities, with per-item results"]', '["create_relationship accepts task implements ADR and ADR supersedes ADR", "A supersedes link sets the old decision''s superseded_by and moves it to Superseded; update_architecture_status refuses Superseded without one", "The three status tools accept a list of IDs and return a result for each", "update_requirement_status walks the allowed path to the requested status, logging each step"]', 'MCP User', '2026-09-15 17:01:17', 'functional_requirements', 'Brought up to date after R10, R15 and R16: tool names, measured call share, ADR-0002 constraints');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (237, 'requirement', 'REQ-0005-FUNC-00', 'field_edit', '["get_architecture_details lists implementing tasks and the superseding ADR", "Approving 8 requirements through Under Review takes one call"]', '["get_details on an ADR lists the tasks implementing it and the decision that supersedes it; get_details on a task lists the ADRs it implements", "Approving 8 Draft requirements through Under Review takes one call", "A batch with one refused ID still moves the others and names the refusal"]', 'MCP User', '2026-09-15 17:01:17', 'acceptance_criteria', 'Brought up to date after R10, R15 and R16: tool names, measured call share, ADR-0002 constraints');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (238, 'requirement', 'REQ-0005-FUNC-00', 'field_edit', 'Closes F-11, F-19, F-30. Evidence: claude-lifecycle-lab/NOTES.md.', 'Closes F-11, F-19, F-30 and the Superseded part of F-13. Evidence: claude-lifecycle-lab/NOTES.md, docs/tool-surface/usage-evidence.md.', 'MCP User', '2026-09-15 17:01:17', 'business_value', 'Brought up to date after R10, R15 and R16: tool names, measured call share, ADR-0002 constraints');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (239, 'requirement', 'REQ-0005-FUNC-00', 'field_edit', NULL, '["ADR-0002: bulk transitions extend the existing status tools instead of adding a tool; new parameters raise the tool surface budget in the same change", "ADR-0001: links are stored only in relationships"]', 'MCP User', '2026-09-15 17:01:17', 'technical_constraints', 'Brought up to date after R10, R15 and R16: tool names, measured call share, ADR-0002 constraints');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (240, 'requirement', 'REQ-0005-FUNC-00', 'field_edit', NULL, '["Drawing the new links in diagrams (R13)", "Transition rules for the other ADR statuses (R8)"]', 'MCP User', '2026-09-15 17:01:17', 'out_of_scope', 'Brought up to date after R10, R15 and R16: tool names, measured call share, ADR-0002 constraints');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (241, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', 'Interviews ask canned questions but only read undocumented magic answer keys, so natural answers produce a placeholder requirement (F-07). Sessions live in memory and vanish on restart (F-08). The architectural conversation discards its answers (F-15). MCP sampling code is never wired up.', 'R16 removed the four interview tools (ADR-0002). They asked canned questions, read undocumented answer keys and kept sessions in memory, so natural answers produced placeholder requirements (F-07, F-08, F-15). There is no guided capture now; agents call create_requirement directly. LLM sampling code is still in the handlers but never runs: nothing calls set_mcp_client, so requirement analysis, decomposition and ADR diagram suggestions are dead paths, and llm_decomposition_prompts.py is imported nowhere.', 'MCP User', '2026-09-15 17:01:18', 'current_state', 'R16 removed the interview tools; restated around what remains');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (242, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', 'Guided capture reliably produces complete requirements, or is replaced by a template the client''s own model fills in.', 'Guided capture either returns in a form that fills real fields without conversation tools, or is judged unnecessary; the dead sampling code is gone either way.', 'MCP User', '2026-09-15 17:01:18', 'desired_state', 'R16 removed the interview tools; restated around what remains');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (243, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', '["Questions map one-to-one onto requirement fields, and sessions persist in the database; or replace interviews with a requirement template", "Remove the dead sampling and question-generator code paths"]', '["Decide whether guided capture returns, for example as an MCP prompt or a requirement template the client''s model fills in", "Remove the dead sampling, decomposition and diagram-suggestion code paths and llm_decomposition_prompts.py"]', 'MCP User', '2026-09-15 17:01:18', 'functional_requirements', 'R16 removed the interview tools; restated around what remains');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (244, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', '["An interview answered in plain language yields a requirement with title, states and acceptance criteria filled", "An interview survives a server restart"]', '["If guided capture returns, plain-language answers yield a requirement with title, states and acceptance criteria filled", "No handler references mcp_client or MCP sampling"]', 'MCP User', '2026-09-15 17:01:18', 'acceptance_criteria', 'R16 removed the interview tools; restated around what remains');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (245, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', 'Closes F-07, F-08, F-15. Evidence: claude-lifecycle-lab/NOTES.md.', 'Follows up F-07, F-08 and F-15 after R16 removed the interview tools. Evidence: claude-lifecycle-lab/NOTES.md, docs/tool-surface/usage-evidence.md.', 'MCP User', '2026-09-15 17:01:18', 'business_value', 'R16 removed the interview tools; restated around what remains');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (246, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', NULL, '["ADR-0002: no multi-step conversation tools without persisted state; a new tool raises the tool surface budget"]', 'MCP User', '2026-09-15 17:01:18', 'technical_constraints', 'R16 removed the interview tools; restated around what remains');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (247, 'requirement', 'REQ-0007-FUNC-00', 'field_edit', 'Test results, commits and files have no structured home, so evidence ends up in free-text comments (F-26). Investigations and the decisions they lead to have nowhere to live (F-31).', 'Test results, commits and files have no structured home (F-26). Since R16 add_comment works on tasks and comments show in get_details and get_entity_history, but they are free text and export_project_documentation leaves them out. Investigations and the decisions they lead to have nowhere structured to live (F-31).', 'MCP User', '2026-09-15 17:01:18', 'current_state', 'Comments on tasks exist since R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (248, 'requirement', 'REQ-0008-FUNC-00', 'field_edit', 'Diagrams list entities without requirement-to-ADR-to-task edges, silently truncate to 10 or 5 items, and include deprecated records (F-16). Each call writes a new timestamped file (F-17).', 'The architecture diagram draws ADR boxes with no edges. full_project hangs records off category nodes, draws at most 20 requirement-to-task edges and no requirement-to-ADR edges, silently keeps the first 10 requirements, 10 tasks and 5 ADRs, cuts titles at 20 characters and includes deprecated records (F-16). directory_structure is a hard-coded stub. Each call writes a new timestamped file (F-17).', 'MCP User', '2026-09-15 17:01:18', 'current_state', 'Restated against the current diagram code, and the links R9 adds');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (249, 'requirement', 'REQ-0008-FUNC-00', 'field_edit', '["Edges drawn from relationships", "Truncation only when requested, and stated in the output", "Stable filenames that overwrite the previous render"]', '["Edges drawn from relationships, including the task-implements-ADR and ADR-supersedes-ADR links from R9", "Truncation only when requested, and stated in the output", "Stable filenames that overwrite the previous render", "Remove or replace the hard-coded directory_structure diagram"]', 'MCP User', '2026-09-15 17:01:18', 'functional_requirements', 'Restated against the current diagram code, and the links R9 adds');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (250, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', '[R14] Ergonomics: short IDs, subtask-aware progress, fast tests', '[R14] Ergonomics: short IDs and subtask-aware progress', 'MCP User', '2026-09-15 17:04:20', 'title', 'The test-suite part of F-28 is fixed; tool name updated after R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (251, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', 'Per-type numbering makes ''REQ-0001'' ambiguous (F-06). Subtasks double-count in requirement progress (F-22). The test suite takes 11 minutes with 4 failing tests, and benchmarks run by default (F-28).', 'Per-type numbering makes ''REQ-0001'' ambiguous: REQ-0001-FUNC-00, REQ-0001-TECH-00 and REQ-0001-INTF-00 all exist (F-06). Subtasks count toward requirement task_count alongside their parent, so a requirement with one task split in two reads 0/3 (F-22). The test-suite part of F-28 is fixed: on 2026-09-15 the default pytest run took 34 seconds, 250 passed and 3 skipped, with no failures.', 'MCP User', '2026-09-15 17:04:20', 'current_state', 'The test-suite part of F-28 is fixed; tool name updated after R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (252, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', 'IDs are easy to say, progress reflects the actual work, and the default test run is fast and green.', 'IDs are easy to say and progress reflects the actual work.', 'MCP User', '2026-09-15 17:04:20', 'desired_state', 'The test-suite part of F-28 is fixed; tool name updated after R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (253, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', '["Short aliases such as REQ-12 resolve in every tool", "Requirement progress counts leaf tasks only", "Benchmarks opt-in; default test run under 2 minutes"]', '["Short aliases such as REQ-12 resolve in every tool that takes an ID", "Requirement progress counts leaf tasks only"]', 'MCP User', '2026-09-15 17:04:20', 'functional_requirements', 'The test-suite part of F-28 is fixed; tool name updated after R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (254, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', '["get_requirement_details accepts a short alias", "The default pytest run is green and under 2 minutes"]', '["get_details accepts a short alias", "A requirement whose only task is split into two Complete subtasks reports 2 of 2 tasks complete"]', 'MCP User', '2026-09-15 17:04:20', 'acceptance_criteria', 'The test-suite part of F-28 is fixed; tool name updated after R16');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (255, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', 'Closes F-06, F-22, F-28. Evidence: claude-lifecycle-lab/NOTES.md.', 'Closes F-06 and F-22; F-28 is resolved. Evidence: claude-lifecycle-lab/NOTES.md.', 'MCP User', '2026-09-15 17:04:20', 'business_value', 'The test-suite part of F-28 is fixed; tool name updated after R16');
