INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (266, 'architecture', 'ADR-0003', 'field_edit', '1. Each status tool also accepts a list (requirement_ids, task_ids, architecture_ids). Every ID moves independently in its own transaction and gets its own result; the call is an error only when every ID is refused. 2. update_requirement_status walks the shortest allowed path to new_status: gates are checked for the whole path first, every step is applied in one transaction and logged as its own status change, and the comment is added once. Tasks and ADRs have no transition map yet (R8), so they move directly. 3. relationships gains task -> architecture implements (either order accepted) and architecture -> architecture supersedes (new -> old). Migration 14 rebuilds relationships to allow supersedes, keeping its views, triggers and indexes, and adds triggers that keep architecture.superseded_by equal to the incoming supersedes link. Creating a supersedes link moves the old ADR to Superseded in the same transaction. update_architecture_status refuses Superseded without such a link and refuses leaving Superseded while one exists.', '1. Each status tool also accepts a list (requirement_ids, task_ids, architecture_ids). Every ID moves independently in its own transaction and gets its own result; the call is an error only when every ID is refused. 2. update_requirement_status walks the shortest allowed path to new_status, but never through Approved: one call moves a requirement up to Approved or onward from it, not both, because tasks and ADRs are planned against an approved requirement. Gates are checked for the whole path first, every step is applied in one transaction and logged as its own status change, and the comment is added once. Tasks and ADRs have no transition map yet (R8), so they move directly. 3. relationships gains task -> architecture implements (either order accepted) and architecture -> architecture supersedes (new -> old). Migration 14 rebuilds relationships to allow supersedes, keeping its views, triggers and indexes, and adds triggers that keep architecture.superseded_by equal to the incoming supersedes link. Creating a supersedes link moves the old ADR to Superseded in the same transaction. update_architecture_status refuses Superseded without such a link and refuses leaving Superseded while one exists.', 'MCP User', '2026-09-15 17:05:17', 'decision_outcome', 'Existing tests showed a multi-step move could take a Draft requirement with no tasks straight to Validated');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (267, 'requirement', 'REQ-0005-FUNC-00', 'field_edit', '["create_relationship accepts task implements ADR and ADR supersedes ADR", "A supersedes link sets the old decision''s superseded_by and moves it to Superseded; update_architecture_status refuses Superseded without one", "The three status tools accept a list of IDs and return a result for each", "update_requirement_status walks the allowed path to the requested status, logging each step"]', '["create_relationship accepts task implements ADR and ADR supersedes ADR", "A supersedes link sets the old decision''s superseded_by and moves it to Superseded; update_architecture_status refuses Superseded without one", "The three status tools accept a list of IDs and return a result for each", "update_requirement_status walks the allowed path to the requested status, logging each step; one call never passes through Approved"]', 'MCP User', '2026-09-15 17:05:17', 'functional_requirements', 'ADR-0003: a multi-step move never passes through Approved');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (268, 'task', 'TASK-0046-00-00', 'field_edit', '["Draft to Approved in one call passes through Under Review and logs two status changes", "Gates apply to the whole path first: Ready to Validated with an open task is refused and the requirement stays Ready", "A target with no allowed path is refused, naming the statuses it can move to", "The text and structuredContent show the path"]', '["Draft to Approved in one call passes through Under Review and logs two status changes", "Approved to Validated in one call passes through Ready and Implemented", "A path through Approved is refused: Draft to Validated is still an invalid transition", "Gates apply to the whole path first: Ready to Validated with an open task is refused and the requirement stays Ready", "A target with no allowed path is refused, naming the statuses it can move to", "The text and structuredContent show the path"]', 'MCP User', '2026-09-15 17:05:17', 'acceptance_criteria', NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (269, 'task', 'TASK-0045-00-00', 'status_change', 'Not Started', 'In Progress', NULL, '2026-09-15 17:05:17', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (270, 'task', 'TASK-0046-00-00', 'status_change', 'Not Started', 'In Progress', NULL, '2026-09-15 17:12:15', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (271, 'architecture', 'ADR-0003', 'field_edit', '1. Each status tool also accepts a list (requirement_ids, task_ids, architecture_ids). Every ID moves independently in its own transaction and gets its own result; the call is an error only when every ID is refused. 2. update_requirement_status walks the shortest allowed path to new_status, but never through Approved: one call moves a requirement up to Approved or onward from it, not both, because tasks and ADRs are planned against an approved requirement. Gates are checked for the whole path first, every step is applied in one transaction and logged as its own status change, and the comment is added once. Tasks and ADRs have no transition map yet (R8), so they move directly. 3. relationships gains task -> architecture implements (either order accepted) and architecture -> architecture supersedes (new -> old). Migration 14 rebuilds relationships to allow supersedes, keeping its views, triggers and indexes, and adds triggers that keep architecture.superseded_by equal to the incoming supersedes link. Creating a supersedes link moves the old ADR to Superseded in the same transaction. update_architecture_status refuses Superseded without such a link and refuses leaving Superseded while one exists.', '1. Each status tool also accepts a list (requirement_ids, task_ids, architecture_ids). Every ID moves independently in its own transaction and gets its own result; the call is an error only when every ID is refused. 2. update_requirement_status walks the shortest allowed path to new_status, but never through Approved or Validated: one call moves a requirement up to Approved or onward from it, and reaches Validated only as its target, because tasks and ADRs are planned against an approved requirement and validation is a deliberate step. Gates are checked for the whole path first, every step is applied in one transaction and logged as its own status change, and the comment is added once. Tasks and ADRs have no transition map yet (R8), so they move directly. 3. relationships gains task -> architecture implements (either order accepted) and architecture -> architecture supersedes (new -> old). Migration 14 rebuilds relationships to allow supersedes, keeping its views, triggers and indexes, and adds triggers that keep architecture.superseded_by equal to the incoming supersedes link. Creating a supersedes link moves the old ADR to Superseded in the same transaction. update_architecture_status refuses Superseded without such a link and refuses leaving Superseded while one exists.', 'MCP User', '2026-09-15 17:12:15', 'decision_outcome', 'A move ending at Deprecated could otherwise route through Validated, claiming a validation nobody did');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (272, 'task', 'TASK-0046-00-00', 'field_edit', '["Draft to Approved in one call passes through Under Review and logs two status changes", "Approved to Validated in one call passes through Ready and Implemented", "A path through Approved is refused: Draft to Validated is still an invalid transition", "Gates apply to the whole path first: Ready to Validated with an open task is refused and the requirement stays Ready", "A target with no allowed path is refused, naming the statuses it can move to", "The text and structuredContent show the path"]', '["Draft to Approved in one call passes through Under Review and logs two status changes", "Approved to Validated in one call passes through Ready and Implemented", "A path through Approved is refused, naming Approved as the stop: Draft to Validated is still an invalid transition", "Implemented to Deprecated passes through Ready, never Validated", "Gates apply to the whole move: Ready to Validated with an open task is refused and the requirement stays Ready", "A target with no allowed path is refused, naming the statuses it can move to", "The text and structuredContent show the path of a multi-step move; one-step results are unchanged"]', 'MCP User', '2026-09-15 17:12:15', 'acceptance_criteria', NULL);
