INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (290, 'requirement', 'REQ-0003-FUNC-00', 'field_edit', '["query_tasks can return only Not Started tasks whose dependencies are all Complete, in priority order", "get_details on a task shows the tasks it depends on and the tasks it blocks", "A task can record why it is blocked; the dashboard lists every Blocked task with its reason and blocking items"]', '["query_tasks with ready: true returns Not Started tasks whose dependencies are all Complete, highest priority first. A task''s dependencies are the tasks it depends on or requires, and the tasks that block it", "get_details on a task lists Depends On and Blocks", "The comment given when a task moves to Blocked is kept as its blocked reason until it leaves Blocked, and details show it", "get_project_status lists every Blocked task with its reason and unmet dependencies, and every Not Started task waiting on dependencies, in the text and in structuredContent"]', 'MCP User', '2026-09-15 21:40:16', 'functional_requirements', 'Design settled before approval');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (291, 'requirement', 'REQ-0003-FUNC-00', 'field_edit', '["ADR-0002: prefer a query_tasks filter to a new tool; any new tool or parameter raises tests/tool_surface_budget.json in the same change"]', '["ADR-0002: no new tool. The ready filter is a query_tasks parameter and the reason reuses update_task_status''s comment; the budget rises in the same change", "blocked_reason is a tasks column (migration 15) that only update_task_status writes"]', 'MCP User', '2026-09-15 21:40:16', 'technical_constraints', 'Design settled before approval');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (292, 'requirement', 'REQ-0003-FUNC-00', 'status_change', 'Draft', 'Under Review', NULL, '2026-09-15 21:41:00', NULL, NULL);
