INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (309, 'requirement', 'REQ-0004-FUNC-00', 'field_edit', 'Dependencies are recorded but never enforced or warned about (F-24). A parent task can complete while subtasks are open, tasks can jump from Not Started to Complete, and Implemented is ungated (F-25). ADR status has no transition rules (F-13).', 'Dependencies are recorded but never enforced or warned about (F-24). A parent task can complete while subtasks are open, tasks can jump from Not Started to Complete, and Implemented is ungated (F-25). ADR status has no transition rules beyond R9''s Superseded link (F-13). R7 leaves a task waiting on an Abandoned dependency forever: only Complete releases it, and the dashboard lists the dependency without saying it was abandoned.', 'MCP User', '2026-09-16 00:21:47', 'current_state', 'Owner decision on abandoned dependencies (2026-09-15), after R7 shipped');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (310, 'requirement', 'REQ-0004-FUNC-00', 'field_edit', '["A project-level strictness setting: off, warn or enforce", "Rules cover unmet dependencies, parent completion with open subtasks, task transitions, the Implemented gate and ADR transitions"]', '["A project-level strictness setting: off, warn or enforce", "Rules cover unmet dependencies, parent completion with open subtasks, task transitions, the Implemented gate and ADR transitions", "An abandoned dependency never counts as resolved: a task waiting on one stays blocked, and both the dashboard and the warning say which dependency was abandoned and how to clear it, by deleting the link or abandoning the waiting task too"]', 'MCP User', '2026-09-16 00:21:47', 'functional_requirements', 'Owner decision on abandoned dependencies (2026-09-15), after R7 shipped');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (311, 'requirement', 'REQ-0004-FUNC-00', 'field_edit', '["In warn mode, starting a task with unmet dependencies succeeds and says why it is risky", "In enforce mode, the same call is refused with the blocking task IDs", "Default behaviour is unchanged for existing projects"]', '["In warn mode, starting a task with unmet dependencies succeeds and says why it is risky", "In enforce mode, the same call is refused with the blocking task IDs", "A task whose dependency is Abandoned is reported as waiting on an abandoned task, by name, on the dashboard and in the warning; in enforce mode starting it is refused until the link is deleted or the task is abandoned too", "Default behaviour is unchanged for existing projects"]', 'MCP User', '2026-09-16 00:21:47', 'acceptance_criteria', 'Owner decision on abandoned dependencies (2026-09-15), after R7 shipped');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (312, 'requirement', 'REQ-0004-FUNC-00', 'field_edit', '["Superseding an ADR: R9 ties Superseded to a supersedes link", "Content edits: R6a already limits ADR edits to Proposed and requires a reason for requirement edits at Approved or later"]', '["Superseding an ADR: R9 ties Superseded to a supersedes link", "Content edits: R6a already limits ADR edits to Proposed and requires a reason for requirement edits at Approved or later", "Cascading abandonment: abandoning a task never abandons the tasks it depends on, which may serve other work, nor the tasks depending on it, which may reach their goal another way (owner decision, 2026-09-15)"]', 'MCP User', '2026-09-16 00:21:47', 'out_of_scope', 'Owner decision on abandoned dependencies (2026-09-15), after R7 shipped');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (313, 'requirement', 'REQ-0003-FUNC-00', 'status_change', 'Approved', 'Ready', NULL, '2026-09-16 00:21:54', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (314, 'requirement', 'REQ-0003-FUNC-00', 'status_change', 'Ready', 'Implemented', NULL, '2026-09-16 00:21:54', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (315, 'requirement', 'REQ-0003-FUNC-00', 'status_change', 'Implemented', 'Validated', NULL, '2026-09-16 00:21:54', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (316, 'requirement', 'REQ-0004-FUNC-00', 'field_edit', '["A project-level strictness setting: off, warn or enforce", "Rules cover unmet dependencies, parent completion with open subtasks, task transitions, the Implemented gate and ADR transitions", "An abandoned dependency never counts as resolved: a task waiting on one stays blocked, and both the dashboard and the warning say which dependency was abandoned and how to clear it, by deleting the link or abandoning the waiting task too"]', '["LIFECYCLE_RULES chooses off, warn or enforce. warn is the default: it changes no outcome and explains the risk. enforce refuses the move and names what blocks it", "Rules cover unmet dependencies, a parent task completing with open subtasks, task skips and reopens (Not Started or Blocked straight to Complete, and reopening a Complete task), a requirement reaching Implemented with open tasks, and ADR status moves", "An abandoned dependency never counts as resolved: a task waiting on one stays blocked, and both the dashboard and the warning say which dependency was abandoned and how to clear it, by deleting the link or abandoning the waiting task too", "Warnings appear in the response text and in structuredContent, once per record moved"]', 'MCP User', '2026-09-16 00:28:51', 'functional_requirements', 'Design settled before approval: LIFECYCLE_RULES, warn by default, skips and reopens only');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (317, 'requirement', 'REQ-0004-FUNC-00', 'field_edit', '["In warn mode, starting a task with unmet dependencies succeeds and says why it is risky", "In enforce mode, the same call is refused with the blocking task IDs", "A task whose dependency is Abandoned is reported as waiting on an abandoned task, by name, on the dashboard and in the warning; in enforce mode starting it is refused until the link is deleted or the task is abandoned too", "Default behaviour is unchanged for existing projects"]', '["With LIFECYCLE_RULES unset, moving a task straight from Not Started to Complete still succeeds and says the task was never started", "In warn mode, starting a task with unmet dependencies succeeds and names them", "In enforce mode, the same call is refused with the blocking task IDs", "A task whose dependency is Abandoned is reported as waiting on an abandoned task, by name, on the dashboard and in the warning; in enforce mode starting it is refused until the link is deleted or the task is abandoned too", "With LIFECYCLE_RULES=off nothing is warned about and nothing is refused beyond the rules that already exist", "A list move reports its warnings per task"]', 'MCP User', '2026-09-16 00:28:51', 'acceptance_criteria', 'Design settled before approval: LIFECYCLE_RULES, warn by default, skips and reopens only');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (318, 'requirement', 'REQ-0004-FUNC-00', 'field_edit', '["ADR-0002: configure strictness without adding a tool unless the tool surface budget is raised on purpose"]', '["ADR-0002: no new tool. Strictness is the LIFECYCLE_RULES environment variable (off, warn, enforce), like LIFECYCLE_GITHUB, and warnings ride on the existing status tool responses", "Warn is the default so outcomes stay as they are today; only the explanation is new (owner decision, 2026-09-15)", "Task moves are flagged only for skips and reopens, not through a full transition map (owner decision, 2026-09-15)", "The Validated gate and the R9 Superseded rule stay always on: they are not part of the strictness setting"]', 'MCP User', '2026-09-16 00:28:51', 'technical_constraints', 'Design settled before approval: LIFECYCLE_RULES, warn by default, skips and reopens only');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (319, 'requirement', 'REQ-0004-FUNC-00', 'status_change', 'Draft', 'Under Review', NULL, '2026-09-16 00:29:14', NULL, NULL);
