INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (341, 'requirement', 'REQ-0008-FUNC-00', 'field_edit', 'The architecture diagram draws ADR boxes with no edges. full_project hangs records off category nodes, draws at most 20 requirement-to-task edges and no requirement-to-ADR edges, silently keeps the first 10 requirements, 10 tasks and 5 ADRs, cuts titles at 20 characters and includes deprecated records (F-16). directory_structure is a hard-coded stub. Each call writes a new timestamped file (F-17).', 'Verified on 2026-09-15 against export_handler.py. The architecture diagram draws ADR boxes with no edges. full_project hangs records off category nodes, silently keeps the first 10 requirements, 10 tasks and 5 ADRs, draws at most 20 edges and only requirement-to-task ones, and includes deprecated records (only styling them grey). The requirements, tasks and dependencies diagrams cut titles at 30 characters without escaping mermaid punctuation. directory_structure returns a hard-coded src/docs/tests stub that has nothing to do with the project. Every call writes a new timestamped file into exports/ (F-16, F-17). Since the finding was written, R9 added two more link types the diagrams ignore: task implements ADR, and ADR supersedes ADR.</current_state>' || char(10) || '<desired_state>Diagrams show the real graph from relationships, completely unless a limit is asked for, at stable paths.</desired_state>' || char(10) || '<functional_requirements>["Edges come from relationships: requirement to task (implements), requirement to ADR (addresses), task to ADR (implements), ADR to ADR (supersedes), task to task (parent and dependencies)", "Nothing is dropped silently: everything is drawn unless a limit is requested, and whatever is left out is stated in the response", "Deprecated requirements and decisions are left out by default, and the response says so", "Each diagram type writes to a stable filename that overwrites the previous render", "directory_structure is removed rather than returning a hard-coded stub", "Node labels keep enough of the title to be readable and escape the punctuation that breaks mermaid"]</functional_requirements>' || char(10) || '<acceptance_criteria>["The full-project diagram shows requirement-to-ADR and requirement-to-task edges for every non-deprecated record, with no limit given", "A task implementing an ADR and an ADR superseding another are drawn as edges", "With a limit, the response says how many of each kind were drawn and how many were left out", "Two calls of the same diagram type leave one file, not two", "directory_structure is refused as an unknown diagram type, naming the types that exist", "A title containing quotes or brackets renders without breaking the diagram"]</acceptance_criteria>' || char(10) || '<technical_constraints>["ADR-0002: no new tool. A limit parameter on create_architectural_diagrams raises the budget in the same change; removing directory_structure lowers it", "Breaking for anyone parsing timestamped diagram filenames or calling directory_structure: the CHANGELOG records both"]</technical_constraints>' || char(10), 'MCP User', '2026-09-16 01:15:57', 'current_state', 'Re-reviewed against the merged code; design settled before approval');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (342, 'requirement', 'REQ-0008-FUNC-00', 'field_edit', 'Verified on 2026-09-15 against export_handler.py. The architecture diagram draws ADR boxes with no edges. full_project hangs records off category nodes, silently keeps the first 10 requirements, 10 tasks and 5 ADRs, draws at most 20 edges and only requirement-to-task ones, and includes deprecated records (only styling them grey). The requirements, tasks and dependencies diagrams cut titles at 30 characters without escaping mermaid punctuation. directory_structure returns a hard-coded src/docs/tests stub that has nothing to do with the project. Every call writes a new timestamped file into exports/ (F-16, F-17). Since the finding was written, R9 added two more link types the diagrams ignore: task implements ADR, and ADR supersedes ADR.</current_state>' || char(10) || '<desired_state>Diagrams show the real graph from relationships, completely unless a limit is asked for, at stable paths.</desired_state>' || char(10) || '<functional_requirements>["Edges come from relationships: requirement to task (implements), requirement to ADR (addresses), task to ADR (implements), ADR to ADR (supersedes), task to task (parent and dependencies)", "Nothing is dropped silently: everything is drawn unless a limit is requested, and whatever is left out is stated in the response", "Deprecated requirements and decisions are left out by default, and the response says so", "Each diagram type writes to a stable filename that overwrites the previous render", "directory_structure is removed rather than returning a hard-coded stub", "Node labels keep enough of the title to be readable and escape the punctuation that breaks mermaid"]</functional_requirements>' || char(10) || '<acceptance_criteria>["The full-project diagram shows requirement-to-ADR and requirement-to-task edges for every non-deprecated record, with no limit given", "A task implementing an ADR and an ADR superseding another are drawn as edges", "With a limit, the response says how many of each kind were drawn and how many were left out", "Two calls of the same diagram type leave one file, not two", "directory_structure is refused as an unknown diagram type, naming the types that exist", "A title containing quotes or brackets renders without breaking the diagram"]</acceptance_criteria>' || char(10) || '<technical_constraints>["ADR-0002: no new tool. A limit parameter on create_architectural_diagrams raises the budget in the same change; removing directory_structure lowers it", "Breaking for anyone parsing timestamped diagram filenames or calling directory_structure: the CHANGELOG records both"]</technical_constraints>' || char(10), 'Verified on 2026-09-15 against export_handler.py. The architecture diagram draws ADR boxes with no edges. full_project hangs records off category nodes, silently keeps the first 10 requirements, 10 tasks and 5 ADRs, draws at most 20 edges and only requirement-to-task ones, and includes deprecated records (only styling them grey). The requirements, tasks and dependencies diagrams cut titles at 30 characters without escaping mermaid punctuation. directory_structure returns a hard-coded src/docs/tests stub that has nothing to do with the project. Every call writes a new timestamped file into exports/ (F-16, F-17). Since the finding was written, R9 added two more link types the diagrams ignore: task implements ADR, and ADR supersedes ADR.', 'MCP User', '2026-09-16 01:16:46', 'current_state', 'Repairing a mangled update: the previous call folded every field into current_state as literal text');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (343, 'requirement', 'REQ-0008-FUNC-00', 'field_edit', 'Diagrams show the real graph from relationships, completely, at stable paths.', 'Diagrams show the real graph from relationships, completely unless a limit is asked for, at stable paths.', 'MCP User', '2026-09-16 01:16:46', 'desired_state', 'Repairing a mangled update: the previous call folded every field into current_state as literal text');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (344, 'requirement', 'REQ-0008-FUNC-00', 'field_edit', '["Edges drawn from relationships, including the task-implements-ADR and ADR-supersedes-ADR links from R9", "Truncation only when requested, and stated in the output", "Stable filenames that overwrite the previous render", "Remove or replace the hard-coded directory_structure diagram"]', '["Edges come from relationships: requirement to task (implements), requirement to ADR (addresses), task to ADR (implements), ADR to ADR (supersedes), task to task (parent and dependencies)", "Nothing is dropped silently: everything is drawn unless a limit is requested, and whatever is left out is stated in the response", "Deprecated requirements and decisions are left out by default, and the response says so", "Each diagram type writes to a stable filename that overwrites the previous render", "directory_structure is removed rather than returning a hard-coded stub", "Node labels keep enough of the title to be readable and escape the punctuation that breaks mermaid"]', 'MCP User', '2026-09-16 01:16:46', 'functional_requirements', 'Repairing a mangled update: the previous call folded every field into current_state as literal text');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (345, 'requirement', 'REQ-0008-FUNC-00', 'field_edit', '["The full-project diagram shows requirement to ADR and requirement to task edges for all non-deprecated records"]', '["The full-project diagram shows requirement-to-ADR and requirement-to-task edges for every non-deprecated record, with no limit given", "A task implementing an ADR and an ADR superseding another are drawn as edges", "With a limit, the response says how many of each kind were drawn and how many were left out", "Two calls of the same diagram type leave one file, not two", "directory_structure is refused as an unknown diagram type, naming the types that exist", "A title containing quotes or brackets renders without breaking the diagram"]', 'MCP User', '2026-09-16 01:16:46', 'acceptance_criteria', 'Repairing a mangled update: the previous call folded every field into current_state as literal text');
