INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (364, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', 'Per-type numbering makes ''REQ-0001'' ambiguous: REQ-0001-FUNC-00, REQ-0001-TECH-00 and REQ-0001-INTF-00 all exist (F-06). Subtasks count toward requirement task_count alongside their parent, so a requirement with one task split in two reads 0/3 (F-22). The test-suite part of F-28 is fixed: on 2026-09-15 the default pytest run took 34 seconds, 250 passed and 3 skipped, with no failures.', 'Verified on 2026-09-15. Per-type numbering makes a bare number ambiguous: in this tracker requirement number 1 is four records (FUNC, INTF, NFUNC, TECH) and number 2 is another four, so the REQ-12 form the finding suggested cannot resolve (F-06). Nothing resolves aliases today: every tool needs the full stored ID. Requirement progress double counts: create_task links every task to its requirements, subtasks included, and the task_count and tasks_completed triggers count all implements links, so a requirement whose one task is split in two reads 3 tasks (F-22). The test-suite part of F-28 is fixed: the default pytest run is green in well under a minute.', 'MCP User', '2026-09-16 01:43:31', 'current_state', 'Re-reviewed against the merged code; alias shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (365, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', 'IDs are easy to say and progress reflects the actual work.', 'IDs can be typed without zero padding or the trailing version, and progress counts the work that is actually done.', 'MCP User', '2026-09-16 01:43:31', 'desired_state', 'Re-reviewed against the merged code; alias shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (366, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', '["Short aliases such as REQ-12 resolve in every tool that takes an ID", "Requirement progress counts leaf tasks only"]', '["Every tool that takes a record ID also accepts a short form: REQ-12-FUNC for REQ-0012-FUNC-00, TASK-12 for TASK-0012-00-00, TASK-12-1 for TASK-0012-01-00, ADR-4 for ADR-0004", "Full stored IDs keep working exactly as they do now", "An alias matching nothing is refused as unknown; one matching more than one record is refused with the candidates named", "task_count and tasks_completed count leaf tasks only: a task with a parent is counted through its parent rather than twice"]', 'MCP User', '2026-09-16 01:43:31', 'functional_requirements', 'Re-reviewed against the merged code; alias shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (367, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', '["get_details accepts a short alias", "A requirement whose only task is split into two Complete subtasks reports 2 of 2 tasks complete"]', '["get_details accepts REQ-12-FUNC and TASK-12 and returns the same record as the full ID", "An alias that matches two records is refused, naming both", "A requirement whose only task is split into two Complete subtasks reports 2 of 2 tasks complete", "An existing database gets the corrected counters by migration, with no status touched"]', 'MCP User', '2026-09-16 01:43:31', 'acceptance_criteria', 'Re-reviewed against the merged code; alias shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (368, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', '["ADR-0002: aliases must not add tools"]', '["ADR-0002: no new tool, and the resolver adds no tool parameters, so the budget does not move", "Aliases resolve in one place in BaseHandler so every tool behaves the same way", "Stored IDs never change: an alias is only an input form (owner decision, 2026-09-15)"]', 'MCP User', '2026-09-16 01:43:31', 'technical_constraints', 'Re-reviewed against the merged code; alias shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (369, 'requirement', 'REQ-0001-NFUNC-00', 'field_edit', '["A fast default test run: done (34 s, green, 2026-09-15)"]', '["A fast default test run: done (34 s, green, 2026-09-15)", "Renumbering or renaming records: aliases resolve to the IDs already stored"]', 'MCP User', '2026-09-16 01:43:31', 'out_of_scope', 'Re-reviewed against the merged code; alias shape settled with the owner');
