INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (384, 'requirement', 'REQ-0007-FUNC-00', 'field_edit', 'Test results, commits and files have no structured home (F-26). Since R16 add_comment works on tasks and comments show in get_details and get_entity_history, but they are free text and export_project_documentation leaves them out. Investigations and the decisions they lead to have nowhere structured to live (F-31).', 'Verified on 2026-09-16. Test results, commits and files have no structured home: the tasks table has no column for them, so evidence goes into free-text comments (F-26), as it did in the lab where ''21 tests passing'' was a comment. Since R16 add_comment works on tasks and comments show in get_details and get_entity_history, but export_project_documentation contains no reference to comments at all, so none of it reaches the exported docs. Investigations and the decisions they lead to have nowhere structured to live (F-31). R7 set the precedent for this shape: blocked_reason is a task column that only update_task_status writes.', 'MCP User', '2026-09-16 11:07:46', 'current_state', 'Re-reviewed against the merged code; evidence shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (385, 'requirement', 'REQ-0007-FUNC-00', 'field_edit', 'Tasks carry links to commits, files and test runs, plus dated notes.', 'A task carries the commit and the evidence behind its status, and both reach the exported documentation.', 'MCP User', '2026-09-16 11:07:46', 'desired_state', 'Re-reviewed against the merged code; evidence shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (386, 'requirement', 'REQ-0007-FUNC-00', 'field_edit', '["Attach commits, file paths and test-run summaries to tasks", "Task notes with timestamps, shown in details and export"]', '["update_task_status accepts an optional commit and an optional evidence summary, kept on the task the way blocked_reason is", "Both show in get_details and in get_entity_history''s record of the move", "export_project_documentation includes a task''s commit and evidence, and the comments already stored against records"]', 'MCP User', '2026-09-16 11:07:46', 'functional_requirements', 'Re-reviewed against the merged code; evidence shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (387, 'requirement', 'REQ-0007-FUNC-00', 'field_edit', '["Completing a task can reference a commit and a test summary that appear in export"]', '["Completing a task with a commit and a test summary shows both in its details", "The exported task documentation contains that commit and summary", "The exported documentation contains comments made with add_comment", "A later status move without those fields leaves the recorded commit and evidence in place"]', 'MCP User', '2026-09-16 11:07:46', 'acceptance_criteria', 'Re-reviewed against the merged code; evidence shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (388, 'requirement', 'REQ-0007-FUNC-00', 'field_edit', NULL, '["ADR-0002: no new tool. Two parameters on update_task_status raise the budget in the same change (owner decision, 2026-09-16)", "commit and evidence are task columns that only update_task_status writes, as blocked_reason is (migration 17)"]', 'MCP User', '2026-09-16 11:07:46', 'technical_constraints', 'Re-reviewed against the merged code; evidence shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (389, 'requirement', 'REQ-0007-FUNC-00', 'field_edit', NULL, '["A typed evidence table with one row per commit, file or test run: reconsider if free-text evidence proves too loose", "Attaching files or pull requests as first-class records"]', 'MCP User', '2026-09-16 11:07:46', 'out_of_scope', 'Re-reviewed against the merged code; evidence shape settled with the owner');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (390, 'requirement', 'REQ-0007-FUNC-00', 'status_change', 'Draft', 'Under Review', NULL, '2026-09-16 11:07:46', NULL, NULL);
