INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (401, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', '[R11] Interviews that fill real fields', '[R11] Fields that get filled, and requirements that stay fresh', 'MCP User', '2026-09-16 11:36:38', 'title', 'Reshaped with the owner after measuring the tracker: the gap is unfilled fields and drift, not guided questioning');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (402, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', 'R16 removed the four interview tools (ADR-0002). They asked canned questions, read undocumented answer keys and kept sessions in memory, so natural answers produced placeholder requirements (F-07, F-08, F-15). There is no guided capture now; agents call create_requirement directly. LLM sampling code is still in the handlers but never runs: nothing calls set_mcp_client, so requirement analysis, decomposition and ADR diagram suggestions are dead paths, and llm_decomposition_prompts.py is imported nowhere.', 'Measured in this tracker on 2026-09-16. Guided capture is not the gap: every requirement has its core filled by calling create_requirement directly (18/18 current_state, desired_state, functional_requirements, acceptance_criteria, business_value), and the interview tools R16 removed produced worse records than typing them out (F-07, F-08, F-15). The gap is one field-set down: the curated fields R6b made reachable are mostly empty. nonfunctional_requirements 0/18, business_rules 0/18, validation_metrics 0/18; out_of_scope 5/18 and technical_constraints 7/18, both only because they were filled during a re-review. Tasks: definition_of_done 0/69, implementation_plan 4/69, test_plan 12/69. Decisions: validation_criteria 1/4, risk_assessment 1/4, implementation_notes 0/4. validation_metrics being empty is the one that bites, since it is where a measurable target like ''p95 under 50 ms'' would live. Requirements also drift: six needed their current_state re-verified against the code this session, and R14''s own finding was stale by the time it was reached. Separately, the LLM sampling code can never run: nothing calls set_mcp_client, so about 766 lines are dead (requirement_handler 418-692, architecture_handler 581-752, llm_decomposition_prompts.py).', 'MCP User', '2026-09-16 11:36:38', 'current_state', 'Reshaped with the owner after measuring the tracker: the gap is unfilled fields and drift, not guided questioning');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (403, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', 'Guided capture either returns in a form that fills real fields without conversation tools, or is judged unnecessary; the dead sampling code is gone either way.', 'The fields worth filling get filled, a client that wants guided capture has it without server-side conversation state, and a requirement shows when it was last checked against reality.', 'MCP User', '2026-09-16 11:36:38', 'desired_state', 'Reshaped with the owner after measuring the tracker: the gap is unfilled fields and drift, not guided questioning');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (404, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', '["Decide whether guided capture returns, for example as an MCP prompt or a requirement template the client''s model fills in", "Remove the dead sampling, decomposition and diagram-suggestion code paths and llm_decomposition_prompts.py"]', '["create_requirement and create_task warn when a record is thin for its kind, through the existing workflow rules: an NFUNC requirement with no validation_metrics, a P0 task with no test_plan, and the like", "An MCP prompt offers guided capture: it returns a template the client''s own model fills in and then passes to create_requirement in one call, with no session kept on the server", "A requirement shows when it was last verified against reality, and the dashboard lists the ones that have gone stale, the way it lists requirements changed since review", "The dead sampling, decomposition and diagram-suggestion code paths and llm_decomposition_prompts.py are removed"]', 'MCP User', '2026-09-16 11:36:38', 'functional_requirements', 'Reshaped with the owner after measuring the tracker: the gap is unfilled fields and drift, not guided questioning');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (405, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', '["If guided capture returns, plain-language answers yield a requirement with title, states and acceptance criteria filled", "No handler references mcp_client or MCP sampling"]', '["Creating an NFUNC requirement with no validation_metrics succeeds and names the missing field; with LIFECYCLE_RULES=enforce it is refused", "Creating a P0 task with no test_plan warns the same way", "With LIFECYCLE_RULES=off neither warns", "prompts/list offers the capture prompt, and the requirement produced by following it has the curated fields filled", "A requirement whose content changed after its last verification shows as stale in its details and on the dashboard", "No handler references mcp_client or MCP sampling"]', 'MCP User', '2026-09-16 11:36:38', 'acceptance_criteria', 'Reshaped with the owner after measuring the tracker: the gap is unfilled fields and drift, not guided questioning');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (406, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', 'Follows up F-07, F-08 and F-15 after R16 removed the interview tools. Evidence: claude-lifecycle-lab/NOTES.md, docs/tool-surface/usage-evidence.md.', 'Closes F-07, F-08 and F-15 by answering them with evidence rather than a rebuild, and targets what the tracker shows is actually missing: unfilled curated fields and requirement drift. Evidence: field counts measured 2026-09-16, claude-lifecycle-lab/NOTES.md.', 'MCP User', '2026-09-16 11:36:38', 'business_value', 'Reshaped with the owner after measuring the tracker: the gap is unfilled fields and drift, not guided questioning');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (407, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', '["ADR-0002: no multi-step conversation tools without persisted state; a new tool raises the tool surface budget"]', '["ADR-0002: no new tool. MCP prompts are a separate primitive and do not count against the tool budget, which is what removed the four interview tools (owner decision, 2026-09-16)", "Thin-record warnings reuse BaseHandler._rule_warnings from R8, so off, warn and enforce behave as they already do", "Staleness is derived from lifecycle events, not stored, the way changes_since_review is"]', 'MCP User', '2026-09-16 11:36:38', 'technical_constraints', 'Reshaped with the owner after measuring the tracker: the gap is unfilled fields and drift, not guided questioning');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (408, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', NULL, '["Reviving the interview tools or any multi-step conversation with state on the server (F-08)", "Making any field mandatory: the rules warn, and a project chooses to enforce"]', 'MCP User', '2026-09-16 11:36:38', 'out_of_scope', 'Reshaped with the owner after measuring the tracker: the gap is unfilled fields and drift, not guided questioning');
