INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (441, 'relationship', 'REQ-0011-FUNC-00-REQ-0009-FUNC-00', 'created', NULL, NULL, 'MCP User', '2026-09-16 16:39:52', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (442, 'requirement', 'REQ-0010-FUNC-00', 'field_edit', '["Creation starts the verification clock: a record untouched since it was created is not reported as never verified, in its details or on the dashboard", "Staleness is judged against an age threshold rather than the bare absence of a verifying event, and the report says how long it has been", "get_project_status names every requirement whose linked tasks are all Complete but whose status is earlier than Implemented, as work awaiting a decision", "query_requirements can filter for those requirements, the way query_tasks filters for ready to start"]', '["Creation starts the verification clock: a record untouched since it was created is not reported as never verified, in its details or on the dashboard", "Staleness is judged against an age threshold rather than the bare absence of a verifying event, and the report says how long it has been", "get_project_status names every requirement whose linked tasks are all Complete but whose status is earlier than Implemented, as work awaiting a decision", "query_requirements can filter for those requirements, the way query_tasks filters for ready to start", "An empty ready-to-start result says which case it is: no tasks remain, every remaining task is blocked, or the only startable work is already in progress"]', 'MCP User', '2026-09-16 16:40:58', 'functional_requirements', NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (443, 'requirement', 'REQ-0010-FUNC-00', 'field_edit', '["A requirement created and left alone is not listed as never verified, in get_details or on the dashboard", "A requirement untouched past the staleness threshold is listed, and the entry says how long since it was last verified", "A project whose tasks are all Complete and whose requirements are all Approved names those requirements on the dashboard instead of reporting 0% complete", "query_requirements returns exactly those requirements when asked for the ones whose work is done"]', '["A requirement created and left alone is not listed as never verified, in get_details or on the dashboard", "A requirement untouched past the staleness threshold is listed, and the entry says how long since it was last verified", "A project whose tasks are all Complete and whose requirements are all Approved names those requirements on the dashboard instead of reporting 0% complete", "query_requirements returns exactly those requirements when asked for the ones whose work is done", "Asking for ready-to-start tasks when the only startable task is already In Progress says so, rather than answering that no tasks were found"]', 'MCP User', '2026-09-16 16:41:01', 'acceptance_criteria', NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (444, 'requirement', 'REQ-0011-FUNC-00', 'field_edit', '["An amendment is recorded against an Accepted decision with its text, author, reason and date, without altering the original decision text", "get_details renders amendments with the decision, in order, clearly marked as later corrections rather than as the original", "export_project_documentation carries amendments alongside the decision", "get_entity_history shows an amendment as its own event"]', '["update_architecture records an amendment against an Accepted decision: dated, attributed, carrying its reason, appended rather than replacing any decision field", "The original decision text is never altered by an amendment; the record shows the original and the correction together", "get_details renders amendments with the decision, in order, marked as later corrections rather than as the original text, and export_project_documentation carries them", "get_entity_history shows an amendment as its own event, distinct from a field edit and from a comment"]', 'MCP User', '2026-09-16 17:13:06', 'functional_requirements', NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (445, 'requirement', 'REQ-0011-FUNC-00', 'field_edit', '["Amending an Accepted ADR leaves the original Decision text byte-identical and shows the amendment with it in get_details", "A reader of the exported documentation sees the amendment without following a link or scrolling to comments", "Amending a Proposed ADR is refused with guidance to edit it instead", "The immutability rule is unchanged: update_architecture still refuses to edit an Accepted decision''s text"]', '["Amending an Accepted ADR through update_architecture leaves the original Decision text byte-identical and shows the amendment with it in get_details", "A reader of the exported documentation sees the amendment without following a link or scrolling to the comments", "Amending a Proposed ADR is refused with guidance to edit it instead", "Editing an Accepted decision''s content fields is still refused, with guidance naming both amendment and supersession", "An amendment appears in get_entity_history as its own event"]', 'MCP User', '2026-09-16 17:13:08', 'acceptance_criteria', NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (446, 'requirement', 'REQ-0011-FUNC-00', 'field_edit', '["ADR-0002: no new tool. An amendment should ride on an existing tool - add_comment with a kind, or update_architecture with an amendment reason - rather than adding one", "The decision on which of those to use is open and should be made before implementation"]', '["ADR-0002: no new tool. Amendments ride on update_architecture, which already owns decision content and already refuses edits once a decision leaves Proposed (owner decision, 2026-09-16)", "R6a''s immutability rule is unchanged: update_architecture still refuses to rewrite an Accepted decision''s content fields, and an amendment is a distinct operation rather than a relaxation of that rule", "Where an amendment lives is open - a column on architecture, or a distinct lifecycle event the way staleness and changes-since-review are derived from events. It has to survive export and render with the decision, which rules out anything that only get_details can reach"]', 'MCP User', '2026-09-16 17:13:11', 'technical_constraints', NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (447, 'requirement', 'REQ-0006-FUNC-00', 'field_edit', '["Creating an NFUNC requirement with no validation_metrics succeeds and names the missing field; with LIFECYCLE_RULES=enforce it is refused", "Creating a P0 task with no test_plan warns the same way", "With LIFECYCLE_RULES=off neither warns", "prompts/list offers the capture prompt, and the requirement produced by following it has the curated fields filled", "A requirement whose content changed after its last verification shows as stale in its details and on the dashboard", "No handler references mcp_client or MCP sampling"]', '["Creating an NFUNC requirement with no validation_metrics succeeds and names the missing field; with LIFECYCLE_RULES=enforce it is refused", "Creating a P0 task with no test_plan warns the same way", "With LIFECYCLE_RULES=off neither warns", "prompts/list offers the capture prompt, and the requirement produced by following it has the curated fields filled", "A requirement whose content changed after its last verification shows as stale in its details and on the dashboard", "A requirement untouched since it was created is not reported as stale or as never verified, in its details or on the dashboard: creation starts the clock rather than tripping the alarm", "No handler references mcp_client or MCP sampling"]', 'MCP User', '2026-09-16 17:13:15', 'acceptance_criteria', 'F-43, found in the linkcheck dogfooding run and reproduced in this tracker: the staleness criterion is satisfied by code that fires on records created seconds earlier, because it asserted only that the message appears and never that it should not. Adding the negative case so the criterion can tell correct behaviour from the defect. R17 (REQ-0010-FUNC-00) carries the fix.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (448, 'requirement', 'REQ-0002-NFUNC-00', 'field_edit', '["The budget check runs in CI and names the handler and size that exceeded the budget", "The inventory covers every registered tool and states the tool count and definition size the target would reach", "The ADR is Accepted before any tool is removed or renamed"]', '["The budget check runs in CI and names the handler and size that exceeded the budget", "The inventory covers every registered tool and states the tool count and definition size the target would reach", "The ADR is Accepted before any tool is removed or renamed", "The usage evidence accounts for every call the server received, including calls refused before a handler runs, so that server-side and client-side call counts agree for the same session"]', 'MCP User', '2026-09-16 17:13:18', 'acceptance_criteria', 'F-53, found in the linkcheck dogfooding run: this requirement asks its usage evidence to cover failed calls, but no acceptance criterion pinned that, and the call log cannot see calls refused before a handler runs - the run ended with 9 errors server-side and 11 client-side. Adding the criterion that would have caught it. R18 (REQ-0006-TECH-00) carries the fix.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (449, 'requirement', 'REQ-0010-FUNC-00', 'field_edit', '["Creation starts the verification clock: a record untouched since it was created is not reported as never verified, in its details or on the dashboard", "Staleness is judged against an age threshold rather than the bare absence of a verifying event, and the report says how long it has been", "get_project_status names every requirement whose linked tasks are all Complete but whose status is earlier than Implemented, as work awaiting a decision", "query_requirements can filter for those requirements, the way query_tasks filters for ready to start", "An empty ready-to-start result says which case it is: no tasks remain, every remaining task is blocked, or the only startable work is already in progress"]', '["Creation starts the verification clock: a record untouched since it was created is not reported as never verified, in its details or on the dashboard", "Staleness is judged against an age threshold rather than the bare absence of a verifying event, and the report says how long it has been", "The staleness line in get_details states the two facts it holds rather than inventing a third: when the content changed, and when it was last checked. It never labels the last-checked time as the moment the record went stale, which is what it does today. get_project_status already renders this correctly and is the wording to follow", "The changed-since-review line carries the time of the edit it reports", "get_project_status names every requirement whose linked tasks are all Complete but whose status is earlier than Implemented, as work awaiting a decision", "query_requirements can filter for those requirements, the way query_tasks filters for ready to start", "An empty ready-to-start result says which case it is: no tasks remain, every remaining task is blocked, or the only startable work is already in progress"]', 'MCP User', '2026-09-16 20:58:36', 'functional_requirements', NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (450, 'requirement', 'REQ-0010-FUNC-00', 'field_edit', '["A requirement created and left alone is not listed as never verified, in get_details or on the dashboard", "A requirement untouched past the staleness threshold is listed, and the entry says how long since it was last verified", "A project whose tasks are all Complete and whose requirements are all Approved names those requirements on the dashboard instead of reporting 0% complete", "query_requirements returns exactly those requirements when asked for the ones whose work is done", "Asking for ready-to-start tasks when the only startable task is already In Progress says so, rather than answering that no tasks were found"]', '["A requirement created and left alone is not listed as never verified, in get_details or on the dashboard", "A requirement untouched past the staleness threshold is listed, and the entry says how long since it was last verified", "A stale requirement''s details give the time its content changed and the time it was last checked, and no label claims it has been stale since the moment it was checked", "A requirement edited at a reviewed status shows the time of that edit on its changed-since-review line", "A Validated requirement edited in place shows both warnings; commenting on it afterwards clears the staleness warning and leaves the review warning standing", "A project whose tasks are all Complete and whose requirements are all Approved names those requirements on the dashboard instead of reporting 0% complete", "query_requirements returns exactly those requirements when asked for the ones whose work is done", "Asking for ready-to-start tasks when the only startable task is already In Progress says so, rather than answering that no tasks were found"]', 'MCP User', '2026-09-16 20:58:39', 'acceptance_criteria', NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (451, 'requirement', 'REQ-0010-FUNC-00', 'field_edit', '["ADR-0002: no new tool. The requirement filter is a query_requirements parameter and the new dashboard section rides on get_project_status; the tool surface budget rises in the same change", "Staleness stays derived from lifecycle events rather than a stored column, as R11 established, and ordering uses event ids because timestamps are second-resolution"]', '["ADR-0002: no new tool. The requirement filter is a query_requirements parameter and the new dashboard section rides on get_project_status; the tool surface budget rises in the same change", "Staleness stays derived from lifecycle events rather than a stored column, as R11 established, and ordering uses event ids because timestamps are second-resolution", "Staleness and changed-since-review stay two signals on two lines rather than one merged line, and the dashboard keeps both sections. They answer different questions: a comment clears staleness but not re-review, and a Draft requirement can go stale but can never be changed since review, which covers reviewed statuses only. Only the wording was ever at fault (owner decision, 2026-09-16)"]', 'MCP User', '2026-09-16 20:58:41', 'technical_constraints', NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (452, 'requirement', 'REQ-0006-TECH-00', 'status_change', 'Draft', 'Under Review', NULL, '2026-09-17 00:45:20', NULL, NULL);
