INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (506, 'requirement', 'REQ-0013-FUNC-00', 'created', NULL, NULL, 'Claude (brainstorm with Jeff Wikstrom, 2026-09-17)', '2026-09-17 22:45:50', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (507, 'relationship', 'REQ-0012-FUNC-00-REQ-0013-FUNC-00', 'created', NULL, NULL, 'MCP User', '2026-09-17 22:46:12', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (508, 'requirement', 'REQ-0012-FUNC-00', 'field_edit', '["Parsing code on the server. An AST gives structure without meaning, and a requirement is meaning; the client''s model reads the code", "Applying amendments without review. The output is proposed changes, and Draft plus the Approved gate is where a person still signs off", "Similarity search or vector embeddings over the requirement set", "Drift between a requirement and the code that implements it once both exist, which the anchors and drift requirement covers"]', '["Parsing code on the server. An AST gives structure without meaning, and a requirement is meaning; the client''s model reads the code", "Applying amendments without review. The output is proposed changes, and Draft plus the Approved gate is where a person still signs off", "Similarity search or vector embeddings over the requirement set", "Drift between a requirement and the code that implements it once both exist, which REQ-0013-FUNC-00 covers"]', 'Claude (brainstorm with Jeff Wikstrom, 2026-09-17)', '2026-09-17 22:46:14', 'out_of_scope', NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (509, 'architecture', 'ADR-0005', 'created', NULL, NULL, 'Claude (brainstorm with Jeff Wikstrom, 2026-09-17)', '2026-09-17 22:50:39', NULL, NULL);
