INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (535, 'requirement', 'REQ-0007-TECH-00', 'created', NULL, NULL, 'Claude (brainstorm with Jeff Wikstrom, 2026-09-28)', '2026-09-28 16:51:41', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (536, 'requirement', 'REQ-0007-TECH-00', 'field_edit', '["A script exports the tracker to one text file of INSERT statements, read through SQLite read-only rather than by copying the database file, so the WAL is included without a checkpoint step", "The dump carries data and the schema_version rows only, and no CREATE TABLE, CREATE TRIGGER or CREATE VIEW: lifecycle-schema.sql plus migrations.py stay the single definition of the schema", "A companion import restores the dump into a freshly initialised database, which has already run its migrations, and the schema_version rows tell it where those migrations left off", "The export is byte-identical when run twice against an unchanged database: rows are ordered by primary key and nothing about the export itself - a timestamp, a hostname, a row count - is written into the file", "A local hook in .pre-commit-config.yaml regenerates the dump on every commit, stages it when its content changed, and does nothing at all when it did not, so a commit that touched no tracker data carries no dump diff", "The hook exports the repository''s own database rather than whatever LIFECYCLE_DB points at, so a session pointed at another database cannot overwrite the committed dump with a different tracker", "README documents what the file is, that the database itself is local and deliberately ignored, how to restore one from a clone, and that the dump is generated and never hand-edited"]', '["A script exports the tracker to one text file of INSERT statements, read through SQLite read-only rather than by copying the database file, so the WAL is included without a checkpoint step", "The dump carries data and the schema_version rows only, and no CREATE TABLE, CREATE TRIGGER or CREATE VIEW: lifecycle-schema.sql plus migrations.py stay the single definition of the schema", "A restore script rebuilds a usable database from the dump alone: it initialises an empty database so the migrations run, then loads the dump in one transaction. It needs no running server, no MCP client and no existing database", "Restore refuses to overwrite a database that already holds records. It names what it would destroy, by table and count, and proceeds only on an explicit flag from the caller", "Restore can build into a path the caller names, so a rebuild can be inspected and compared before it replaces anything", "Restore refuses a dump whose schema_version rows are ahead of the migrations present in the checkout, rather than loading records the code cannot read", "Restore verifies itself: the table counts after loading match the counts the dump contains, or it fails and leaves no partly loaded database behind", "The export is byte-identical when run twice against an unchanged database: rows are ordered by primary key and nothing about the export itself - a timestamp, a hostname, a row count - is written into the file", "A local hook in .pre-commit-config.yaml regenerates the dump on every commit, stages it when its content changed, and does nothing at all when it did not, so a commit that touched no tracker data carries no dump diff", "The hook exports the repository''s own database rather than whatever LIFECYCLE_DB points at, so a session pointed at another database cannot overwrite the committed dump with a different tracker", "README documents what the file is, that the database itself is local and deliberately ignored, how to export and how to rebuild one from a clone, and that the dump is generated and never hand-edited"]', 'MCP User', '2026-09-28 16:57:27', 'functional_requirements', 'Restore was one line among the export requirements; making it a first-class script raises the overwrite, schema-version and partial-load cases the original text did not answer.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (537, 'requirement', 'REQ-0007-TECH-00', 'field_edit', '["Changing the tracker and then committing leaves a dump at HEAD containing that change, with no checkpoint, restart or manual export step", "Running the export twice against an unchanged database produces byte-identical files", "A commit that changes only code produces no diff in the dump", "Export, import into a freshly migrated database, and export again produces a file identical to the first, with the same row counts in every table and the same schema_version rows", "A clone containing only the dump yields a working tracker whose requirement, task, decision, relationship and event counts match the database it came from", "The dump contains no CREATE TABLE, CREATE TRIGGER or CREATE VIEW statement", "Pointing LIFECYCLE_DB at a different database and committing does not change the dump of the repository''s tracker", "README has a section covering what the file is, how to restore it, and that it is generated"]', '["Changing the tracker and then committing leaves a dump at HEAD containing that change, with no checkpoint, restart or manual export step", "Running the export twice against an unchanged database produces byte-identical files", "A commit that changes only code produces no diff in the dump", "Export, import into a freshly migrated database, and export again produces a file identical to the first, with the same row counts in every table and the same schema_version rows", "A clone containing only the dump yields a working tracker whose requirement, task, decision, relationship and event counts match the database it came from", "The restored database is usable with no further step: the server starts against it and a tool call returns the restored records", "Restore run against a database that already holds records exits non-zero, writes nothing, and names the counts it would have destroyed", "Restore run with the explicit flag against that same database replaces it and reports what it replaced", "Restore of a dump whose schema_version is ahead of the checkout''s migrations is refused, naming both versions, and nothing is written", "A restore interrupted partway leaves no database that a later run or the server would treat as complete", "The dump contains no CREATE TABLE, CREATE TRIGGER or CREATE VIEW statement", "Pointing LIFECYCLE_DB at a different database and committing does not change the dump of the repository''s tracker", "README has a section covering what the file is, how to export it, how to rebuild a database from it, and that it is generated"]', 'MCP User', '2026-09-28 16:57:27', 'acceptance_criteria', 'Restore was one line among the export requirements; making it a first-class script raises the overwrite, schema-version and partial-load cases the original text did not answer.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (538, 'requirement', 'REQ-0007-TECH-00', 'field_edit', '["Determinism is the requirement the rest depends on. An export that varies between identical runs puts a diff in every commit, which is the signal that always fires and teaches the reader to ignore it (roadmap R17)", "Never copy the database file. Reading through SQLite with file:lifecycle.db?mode=ro sees the WAL and takes a consistent read snapshot even while the server is running; copying the file is the bug this requirement exists to fix", "No CI can verify this. The database is local by design, so nothing in a pull request can tell that a dump is stale, and the hook is the only enforcement point. That makes it an honour-system rule like the configurable workflow rules, and ADR-0004 is the precedent for accepting one deliberately", "The full dump measures 451,062 characters today. .pre-commit-config.yaml already runs check-added-large-files, whose default limit is 500 KB, so the data-only dump has to stay under it or the limit has to be raised deliberately", "lifecycle_events is 534 of the 809 stored rows and grows without bound. It cannot be dropped from the dump to save space: staleness, verification and changes-since-review are all derived from events rather than stored in a column", "The hook goes in the existing local hooks section of .pre-commit-config.yaml, not a hand-installed .git/hooks/pre-commit that a fresh clone would silently lack", "tests/conftest.py fails any test that spawns git or gh, so the round-trip test exercises the export and import scripts against a temporary database and never the hook itself", "scripts/ holds the repository''s existing tooling and is where these belong; the Makefile gets a target so the export is runnable without a commit"]', '["Determinism is the requirement the rest depends on. An export that varies between identical runs puts a diff in every commit, which is the signal that always fires and teaches the reader to ignore it (roadmap R17)", "Never copy the database file. Reading through SQLite with file:lifecycle.db?mode=ro sees the WAL and takes a consistent read snapshot even while the server is running; copying the file is the bug this requirement exists to fix", "Restore runs the migrations and then loads data. It never executes DDL from the dump, because that is what keeps the schema single-sourced in lifecycle-schema.sql and migrations.py, and the schema_version rows in the dump are what tell it where those migrations left off", "The load is one transaction, so a failure rolls back and leaves no half-populated database - the same discipline migrations.py already applies to each migration", "No CI can verify the export is current. The database is local by design, so nothing in a pull request can tell that a dump is stale, and the hook is the only enforcement point. That makes it an honour-system rule like the configurable workflow rules, and ADR-0004 is the precedent for accepting one deliberately", "The full dump measures 451,062 characters today. .pre-commit-config.yaml already runs check-added-large-files, whose default limit is 500 KB, so the data-only dump has to stay under it or the limit has to be raised deliberately", "lifecycle_events is 534 of the 809 stored rows and grows without bound. It cannot be dropped from the dump to save space: staleness, verification and changes-since-review are all derived from events rather than stored in a column", "The hook goes in the existing local hooks section of .pre-commit-config.yaml, not a hand-installed .git/hooks/pre-commit that a fresh clone would silently lack", "tests/conftest.py fails any test that spawns git or gh, so the round-trip test exercises the export and restore scripts against a temporary database and never the hook itself", "scripts/ holds the repository''s existing tooling and is where these belong; the Makefile gets targets so export and restore are runnable without a commit"]', 'MCP User', '2026-09-28 16:57:27', 'technical_constraints', 'Restore was one line among the export requirements; making it a first-class script raises the overwrite, schema-version and partial-load cases the original text did not answer.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (539, 'requirement', 'REQ-0007-TECH-00', 'field_edit', '["Making the dump the source of truth. The database stays authoritative and the dump is a derivative; a text file that had to be edited to change a requirement would bypass the tools, the rules and the event log", "Committing the binary database, in any form, including alongside the dump", "Resolving a merge conflict inside the dump. Two divergent trackers produce a conflict that is visible, which is already better than a binary file, but reconciling them by hand is not a workflow this requirement provides", "Concurrent editing by several people, which the single local database does not support and which this does not change", "Backups anywhere outside the repository", "Pruning or compacting the event log, which would be a change to what the tracker stores rather than to how it travels"]', '["Making the dump the source of truth. The database stays authoritative and the dump is a derivative; a text file that had to be edited to change a requirement would bypass the tools, the rules and the event log", "Committing the binary database, in any form, including alongside the dump", "Restoring individual records or a subset of the tracker. Restore rebuilds a whole database from a whole dump; recovering one requirement from an old dump is a manual job", "Migrating a dump backwards into an older schema than it was written from", "Resolving a merge conflict inside the dump. Two divergent trackers produce a conflict that is visible, which is already better than a binary file, but reconciling them by hand is not a workflow this requirement provides", "Concurrent editing by several people, which the single local database does not support and which this does not change", "Backups anywhere outside the repository", "Pruning or compacting the event log, which would be a change to what the tracker stores rather than to how it travels"]', 'MCP User', '2026-09-28 16:57:27', 'out_of_scope', 'Restore was one line among the export requirements; making it a first-class script raises the overwrite, schema-version and partial-load cases the original text did not answer.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (540, 'requirement', 'REQ-0014-FUNC-00', 'created', NULL, NULL, 'Claude (brainstorm with Jeff Wikstrom, 2026-09-28)', '2026-09-28 17:06:15', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (541, 'requirement', 'REQ-0006-INTF-00', 'created', NULL, NULL, 'Claude (brainstorm with Jeff Wikstrom, 2026-09-28)', '2026-09-28 17:16:59', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (542, 'requirement', 'REQ-0005-INTF-00', 'field_edit', '["Requirements, tasks and decisions are listed, filtered and opened in a view a person reads directly", "Status moves are made from that view, including the list form the status tools already accept", "A record''s links are shown from its own end, as R23 made get_details do, and the relationship graph is navigable rather than rendered to a file someone opens", "The dashboard''s existing sections - blocked and waiting work, work complete and decision pending, staleness - are surfaced as they are, without a second definition of any of them"]', '["Status moves are made from the surface, including the list form the status tools already accept, and land through the tools so the database and the event log cannot tell them from a move made by an agent", "The surface reaches a record from the dashboard''s own sections - blocked and waiting work, work complete and decision pending, staleness - so the thing a signal names is the thing that can then be acted on", "Reading, filtering and navigating the records is a given rather than a deliverable here: REQ-0006-INTF-00 provides it as a generated file, and this requirement adds the ability to act on what is being read", "Whatever form the surface takes, it is a client of the MCP server and holds no lifecycle rule of its own"]', 'MCP User', '2026-09-28 17:17:19', 'functional_requirements', 'Its open question about what the surface is, is half answered: the read-only half became REQ-0006-INTF-00, a generated single-file viewer. Narrowing this to the acting surface so the two records do not overlap.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (543, 'requirement', 'REQ-0005-INTF-00', 'field_edit', '["Someone who has never used the tracker can find the blocked work, the work awaiting a decision, and what is ready to start, without asking an agent", "A status move made in the surface is indistinguishable, in the database and in the event log, from the same move made through the tool", "Moving several records at once uses the list form the status tools already accept rather than a loop", "A record''s decisions, tasks and requirement links are all reachable from that record", "tools/list is unchanged: no tool is added by this requirement"]', '["A status move made in the surface is indistinguishable, in the database and in the event log, from the same move made through the tool", "Moving several records at once uses the list form the status tools already accept rather than a loop", "A refusal from a rule or a gate is shown as the server worded it, rather than reinterpreted", "Acting on a record is reachable from the dashboard signal that named it", "tools/list is unchanged: no tool is added by this requirement"]', 'MCP User', '2026-09-28 17:17:19', 'acceptance_criteria', 'Its open question about what the surface is, is half answered: the read-only half became REQ-0006-INTF-00, a generated single-file viewer. Narrowing this to the acting surface so the two records do not overlap.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (544, 'requirement', 'REQ-0005-INTF-00', 'field_edit', '["No new tools. Everything here is served by tools that already exist and already return structuredContent for exactly this purpose (R10, ADR-0002). A surface that needed new tools would be redesigning the server rather than reading it", "The server keeps no session. Server-side state is what sank the interview tools (F-08) and what R16 removed; this is a client of the MCP server, not a mode of it", "Every figure shown comes from the definition that already computes it - WORK_COMPLETE_WHERE, TASK_DEPENDENCIES_SQL, the staleness derivation - never a reimplementation, or the surface and the tools will disagree about the same record", "Open: what the surface is. A terminal client, a local web app, or a rendering inside the MCP client that already receives the structured responses. They differ in who runs them and what they cost to keep alive, and the choice is not made here"]', '["No new tools. Everything here is served by tools that already exist and already return structuredContent for exactly this purpose (R10, ADR-0002). A surface that needed new tools would be redesigning the server rather than reading it", "The server keeps no session. Server-side state is what sank the interview tools (F-08) and what R16 removed; this is a client of the MCP server, not a mode of it", "Every figure shown comes from the definition that already computes it - WORK_COMPLETE_WHERE, TASK_DEPENDENCIES_SQL, the staleness derivation - never a reimplementation, or the surface and the tools will disagree about the same record", "Open: what the acting surface is. A terminal client, a local web app, or a rendering inside the MCP client that already receives the structured responses. The read-only case is settled and is not one of these: REQ-0006-INTF-00 is a generated file with no connection at all, which is precisely why it cannot act", "Acting requires a live connection to the server, which is the whole of the difference in cost between this requirement and REQ-0006-INTF-00"]', 'MCP User', '2026-09-28 17:17:19', 'technical_constraints', 'Its open question about what the surface is, is half answered: the read-only half became REQ-0006-INTF-00, a generated single-file viewer. Narrowing this to the acting surface so the two records do not overlap.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (545, 'requirement', 'REQ-0005-INTF-00', 'field_edit', '["Any change to the tools, the schema or the stored data", "Editing record content, which the update tools already do and which a first surface does not need", "Replacing the MCP interface: an agent driving the tracker stays the primary path"]', '["Any change to the tools, the schema or the stored data", "Editing record content, which the update tools already do and which a first surface does not need", "Reading, listing, filtering and navigating the tracker, which REQ-0006-INTF-00 delivers without a server", "Replacing the MCP interface: an agent driving the tracker stays the primary path"]', 'MCP User', '2026-09-28 17:17:19', 'out_of_scope', 'Its open question about what the surface is, is half answered: the read-only half became REQ-0006-INTF-00, a generated single-file viewer. Narrowing this to the acting surface so the two records do not overlap.');
