INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (560, 'requirement', 'REQ-0014-FUNC-00', 'field_edit', '["A requirement whose implementing tasks are all Complete or Abandoned, with at least one Complete, can move to Validated", "The always-on gate narrows to the case with no evidence: a requirement with tasks but not one Complete is still refused, naming the abandoned tasks and pointing at Deprecated rather than Validated", "A requirement with a task that is Not Started, In Progress or Blocked is refused exactly as it is today", "The abandoned case becomes a configurable rule through BaseHandler._rule_warnings: off checks nothing, warn moves the requirement and names the abandoned tasks in the response text and structuredContent, enforce raises StatusRefused before anything is written", "tasks_completed keeps meaning Complete, so no progress figure reports work that was abandoned as work that was done", "A separate notion of having no open tasks - no implementing task Not Started, In Progress or Blocked - becomes the basis of the gate and of WORK_COMPLETE_WHERE, defined once and read by the gate, the dashboard section and query_requirements(work_complete=True), the way WORK_COMPLETE_WHERE is read by two of them today", "The dashboard''s Work Complete, Decision Pending section shows a requirement whose only unfinished tasks are abandoned, because that requirement is exactly one awaiting a decision", "Both the refusal and the warning name the tasks and their statuses, in the style the gate''s message already uses"]', '["A requirement whose implementing tasks are all Complete or Abandoned, with at least one Complete, can move to Validated", "The always-on gate narrows to the case with no evidence: a requirement with tasks but not one Complete is still refused, naming the abandoned tasks and pointing at Deprecated rather than Validated", "A requirement with a task that is Not Started, In Progress or Blocked is refused exactly as it is today", "The abandoned case becomes a configurable rule through BaseHandler._rule_warnings: off checks nothing, warn moves the requirement and names the abandoned tasks in the response text and structuredContent, enforce raises StatusRefused before anything is written", "The Implemented gate stops counting Abandoned as open work. It is a warning rather than a block, but a warning that can never be cleared is the signal that always fires, so an abandoned task is named as abandoned and not reported as a task that is not Complete", "tasks_completed keeps meaning Complete, so no progress figure reports work that was abandoned as work that was done", "Whether a requirement has open work is derived rather than stored - no counter column, no trigger change and no migration - so it cannot go stale and existing databases need nothing done to them", "One definition of being ready to validate - tasks exist, at least one is Complete, none is open - is read by the Validated gate, the dashboard''s Work Complete, Decision Pending section and query_requirements(work_complete=True), so all three agree about the same requirement", "A requirement whose every task is Abandoned is absent from Work Complete, Decision Pending, because nothing was completed and the decision it awaits is to deprecate it rather than to validate it", "Both the refusal and the warning name the tasks and their statuses, in the style the gate''s message already uses"]', 'MCP User', '2026-09-28 17:39:39', 'functional_requirements', 'Folding in the Implemented gate, which has the same blind spot: OPEN_TASKS_SQL also tests t.status != ''Complete'', so an abandoned task warns forever, and a warning that can never be cleared is the signal R17 exists to prevent. Also correcting the counter constraint - reading the code shows the open-work question is derivable in the WHERE fragment, so no column, trigger or migration is needed.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (561, 'requirement', 'REQ-0014-FUNC-00', 'field_edit', '["A requirement with one Complete and one Abandoned implementing task moves to Validated, and the response names the abandoned task", "Under LIFECYCLE_RULES=enforce that same move is refused and nothing is written; under off it succeeds with no mention of the abandoned task", "A requirement whose every implementing task is Abandoned is refused, the message names those tasks and says to deprecate it instead", "A requirement with a Not Started, In Progress or Blocked task is refused with the same message it gives today", "A requirement whose only unfinished tasks are abandoned appears in the dashboard''s Work Complete, Decision Pending section and in query_requirements(work_complete=True)", "That requirement''s progress figure reports its Complete tasks over its total and does not read 100%", "An existing database with an abandoned task has correct counts after the migration, with no manual step", "The gate, the dashboard section and the work_complete filter never disagree about whether one requirement has open tasks, because all three read one definition", "tests/tool_surface_budget.json is unchanged"]', '["A requirement with one Complete and one Abandoned implementing task moves to Validated, and the response names the abandoned task", "Under LIFECYCLE_RULES=enforce that same move is refused and nothing is written; under off it succeeds with no mention of the abandoned task", "A requirement whose every implementing task is Abandoned is refused, the message names those tasks and says to deprecate it instead", "A requirement with a Not Started, In Progress or Blocked task is refused with the same message it gives today", "A requirement with an abandoned task and no open tasks moving to Implemented is not told that tasks are not Complete; the abandoned task is named as abandoned", "A requirement whose only unfinished tasks are abandoned appears in the dashboard''s Work Complete, Decision Pending section and in query_requirements(work_complete=True)", "A requirement whose every task is Abandoned appears in neither", "That requirement''s progress figure reports its Complete tasks over its total and does not read 100%", "The gate, the dashboard section and the work_complete filter never disagree about whether one requirement is ready to validate, because all three read one definition", "No migration is added: schema_version is unchanged by this work, and an existing database needs no recomputation", "tests/tool_surface_budget.json is unchanged"]', 'MCP User', '2026-09-28 17:39:39', 'acceptance_criteria', 'Folding in the Implemented gate, which has the same blind spot: OPEN_TASKS_SQL also tests t.status != ''Complete'', so an abandoned task warns forever, and a warning that can never be cleared is the signal R17 exists to prevent. Also correcting the counter constraint - reading the code shows the open-work question is derivable in the WHERE fragment, so no column, trigger or migration is needed.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (562, 'requirement', 'REQ-0014-FUNC-00', 'field_edit', '["The counter change is a migration that also recomputes existing rows, the way migration 16 did for the leaf-task rule. lifecycle-schema.sql is the version 0 baseline and is never edited to change the schema", "The leaf-task rule (F-22, migration 16) still holds: a task something points at as its parent is counted through its subtasks, so the open-task notion counts leaves, not parents", "This narrows the always-on gate rather than removing it. The always-on set stays the Validated gate, R9''s Superseded link and the requirement transition map (ADR-0004); what moves into the configurable rules is the abandoned case alone", "One definition of having no open tasks, following WORK_COMPLETE_WHERE. Two definitions would let the gate and the dashboard disagree about the same requirement", "No new tool and no new parameter: tests/tool_surface_budget.json is unchanged by this requirement", "An enforce refusal raises StatusRefused before the transaction opens, so a refused multi-ID status move leaves nothing written for that record"]', '["No migration and no new column. WORK_COMPLETE_WHERE is a WHERE fragment on requirements, so having no open work is expressible as a correlated NOT EXISTS over relationships and tasks - the same choice CLAUDE.md records for staleness and changes-since-review, which are derived from events rather than kept in a column", "The leaf rule keeps one home. The subquery reuses the same is-leaf condition migration 16''s counter triggers use, rather than restating it, so a parent task is still counted through its subtasks (F-22)", "This narrows the always-on gate rather than removing it. The always-on set stays the Validated gate, R9''s Superseded link and the requirement transition map (ADR-0004); what moves into the configurable rules is the abandoned case alone", "Two definitions would let the gate and the dashboard disagree about one requirement, which is the failure WORK_COMPLETE_WHERE was introduced to prevent", "No new tool and no new parameter: tests/tool_surface_budget.json is unchanged by this requirement", "An enforce refusal raises StatusRefused before the transaction opens, so a refused multi-ID status move leaves nothing written for that record"]', 'MCP User', '2026-09-28 17:39:39', 'technical_constraints', 'Folding in the Implemented gate, which has the same blind spot: OPEN_TASKS_SQL also tests t.status != ''Complete'', so an abandoned task warns forever, and a warning that can never be cleared is the signal R17 exists to prevent. Also correcting the counter constraint - reading the code shows the open-work question is derivable in the WHERE fragment, so no column, trigger or migration is needed.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (563, 'requirement', 'REQ-0014-FUNC-00', 'field_edit', '["A column recording why a task was abandoned. The warning names which tasks were abandoned, not why; a reason column would have to be settable through the tools and visible in details and export, or listed in tests/test_schema_coverage.py", "Changing what Abandoned means anywhere else: task dependencies, subtask rules and the open-work counts already treat it as finished and stay as they are", "Deprecating an all-abandoned requirement automatically. The refusal names Deprecated as the move to make; making it is the reader''s decision", "Reopening an abandoned task, which the task status tool already allows and which the workflow rules already comment on", "The Implemented gate, which is already a configurable warning rather than an always-on rule"]', '["A column recording why a task was abandoned. The warning names which tasks were abandoned, not why; a reason column would have to be settable through the tools and visible in details and export, or listed in tests/test_schema_coverage.py", "Changing what Abandoned means anywhere else: task dependencies, subtask rules and the open-work counts already treat it as finished and stay as they are", "Deprecating an all-abandoned requirement automatically. The refusal names Deprecated as the move to make; making it is the reader''s decision", "Reopening an abandoned task, which the task status tool already allows and which the workflow rules already comment on"]', 'MCP User', '2026-09-28 17:39:39', 'out_of_scope', 'Folding in the Implemented gate, which has the same blind spot: OPEN_TASKS_SQL also tests t.status != ''Complete'', so an abandoned task warns forever, and a warning that can never be cleared is the signal R17 exists to prevent. Also correcting the counter constraint - reading the code shows the open-work question is derivable in the WHERE fragment, so no column, trigger or migration is needed.');
