INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (588, 'task', 'TASK-0090-00-00', 'status_change', 'Not Started', 'In Progress', NULL, '2026-09-28 18:31:19', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (589, 'task', 'TASK-0090-00-00', 'field_edit', '["Reads through SQLite with file:...?mode=ro, so the WAL is included and no checkpoint, copy or server shutdown is needed", "Captures requirements, tasks, architecture decisions, relationships, comments and the lifecycle events the derived figures need", "JSON columns arrive parsed rather than as stored strings, the way the handlers already parse them for structuredContent", "The database file, its -wal and its -shm are unchanged after the generator runs", "Runs against a database being written by a live server without failing or blocking it"]', '["Reads through SQLite with file:...?mode=ro, so the WAL is included and no checkpoint, copy or server shutdown is needed", "Never uses immutable=1, which would tell SQLite to ignore the WAL and reintroduce the stale read this exists to avoid", "Captures requirements, tasks, architecture decisions, relationships, comments and the lifecycle events the derived figures need", "JSON columns arrive parsed rather than as stored strings, using the handlers'' own field lists so the viewer and get_details agree about which columns those are", "A JSON column that will not parse is reported as missing rather than as an empty list, because an empty list reads as a field nobody filled in", "The database file and its -wal are byte-identical after the generator runs. The -shm is excluded deliberately: it is the WAL''s shared-memory index, SQLite writes a read mark into it whenever any reader attaches, and it holds no records", "The whole snapshot is one read transaction, so the tables cannot be read either side of another process''s write and disagree with each other", "Runs against a database being written by a live server without failing or blocking it", "A missing or unreadable database is reported rather than rendered as an empty project"]', 'MCP User', '2026-09-28 18:34:31', 'acceptance_criteria', 'The criterion named the -shm, which no read-only snapshot of a WAL database can leave untouched: SQLite writes a read mark into the shared-memory index whenever a reader attaches. Corrected to the two files that hold tracker data.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (590, 'task', 'TASK-0090-00-00', 'status_change', 'In Progress', 'Complete', NULL, '2026-09-28 18:34:41', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (591, 'task', 'TASK-0091-00-00', 'status_change', 'Not Started', 'In Progress', NULL, '2026-09-28 18:39:23', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (592, 'task', 'TASK-0091-00-00', 'status_change', 'In Progress', 'Complete', NULL, '2026-09-28 18:44:47', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (593, 'task', 'TASK-0092-00-00', 'status_change', 'Not Started', 'In Progress', NULL, '2026-09-28 19:11:14', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (594, 'task', 'TASK-0092-00-00', 'field_edit', '["Assert the generated file contains no http:// or https:// reference, and no fetch, XMLHttpRequest, form or WebAssembly token", "Open the file with networking disabled and assert the records render", "Diff two runs against an unchanged database and assert the only difference is the generation time"]', '["Assert the page''s own markup - everything outside the embedded data block - names no host and contains no fetch, XMLHttpRequest, form, WebAssembly, service worker or localStorage. Asserted against the whole file it would fail on a record that merely mentions one, and a task''s github_issue_url is a stored column", "Assert nothing in the file is loaded at all: no src, no href, no link element, no @import", "Assert a record whose text contains a URL keeps it, so preserving content and naming no host are separately true", "Assert a record''s title cannot inject markup: exactly one script block in the page, and the data block cannot be closed early by a value containing its closing tag", "Open the file with networking disabled and assert the records render", "Two runs against an unchanged database differ only in the generation time, and two runs at the same instant are byte-identical", "Move the written file away from the database and assert it still shows the records"]', 'MCP User', '2026-09-28 19:17:26', 'test_plan', 'The plan said to assert no http:// or XMLHttpRequest anywhere in the generated file. Both are wrong as written: record text may legitimately contain either, and this repository''s own tracker contains both because this very test plan is stored in it. Restated as the property that matters - the page''s own markup loads nothing and reaches for nothing.');
