INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (646, 'requirement', 'REQ-0015-FUNC-00', 'field_edit', '["A project is a record with a title and a required purpose, and optional success criteria and out-of-scope lists", "A requirement can belong to several projects at once", "Membership can be set when a project is created, when a requirement is created, and changed later", "Requirements and tasks can be queried by project", "Export of the whole tracker opens with every project, its purpose and its requirements", "Export of one project holds only its requirements, their tasks and their decisions, and opens with its purpose", "Project details show its purpose, its requirements and how far they have got", "The dashboard lists active projects with their progress", "Projects take comments, history, short IDs and delete like other records", "Projects travel in the tracker dump and appear in the viewer"]', '["A project is a record with a title and a required purpose, and optional success criteria and out-of-scope lists", "A requirement can belong to several projects at once", "Membership can be set when a project is created, when a requirement is created, and changed later", "Requirements, tasks and decisions can be queried by project", "Export of the whole tracker opens with every project, its purpose and its requirements", "Export of one project holds only its requirements, their tasks and their decisions, and opens with its purpose", "Diagrams can be drawn for one project", "The capture and reconcile prompts place a new requirement in its projects", "Project details show its purpose, its requirements and how far they have got", "The dashboard lists active projects with their progress", "Projects take comments, history, short IDs and delete like other records", "Projects travel in the tracker dump and appear in the viewer"]', 'Claude', '2026-10-01 23:53:31', 'functional_requirements', 'Owner asked on 2026-10-01 for project to be added to the diagram tool, the decision query and the prompts, which were out of scope when first written. Dashboard scoping and a list tool stay out.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (647, 'requirement', 'REQ-0015-FUNC-00', 'field_edit', '["Scoping get_project_status to one project", "Scoping create_architectural_diagrams to one project", "A project filter on query_architecture_decisions", "Nested projects", "Tasks or decisions as direct members of a project"]', '["Scoping get_project_status to one project", "A tool that lists projects, including Closed ones", "Nested projects", "Tasks or decisions as direct members of a project"]', 'Claude', '2026-10-01 23:53:31', 'out_of_scope', 'Owner asked on 2026-10-01 for project to be added to the diagram tool, the decision query and the prompts, which were out of scope when first written. Dashboard scoping and a list tool stay out.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (648, 'task', 'TASK-0111-00-00', 'created', NULL, NULL, 'MCP User', '2026-10-01 23:53:31', NULL, NULL);
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (649, 'architecture', 'ADR-0007', 'amendment', NULL, '2026-10-01: query_architecture_decisions and create_architectural_diagrams now take project_id, and both prompts name project_ids (TASK-0111). Still without projects: get_project_status scoping, trace_requirement, and any way to list Closed projects. The surface is 25 tools and 14,933 characters.', 'Claude', '2026-10-01 23:53:31', 'decision_outcome', 'The consequences list named endpoints that have since gained project support.');
INSERT INTO "lifecycle_events" ("id", "entity_type", "entity_id", "event_type", "from_value", "to_value", "actor", "occurred_at", "field", "reason") VALUES (650, 'task', 'TASK-0111-00-00', 'status_change', 'Not Started', 'Complete', NULL, '2026-10-01 23:53:38', NULL, NULL);
