INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (25, 'architecture', 'ADR-0001', 'heffrey78 (owner), recorded by Claude', 'Accepted with revisions: (1) Remove tasks.parent_task_id with ALTER TABLE ... DROP COLUMN (SQLite >= 3.35; bundled 3.46/3.50 verified) instead of a table rebuild; drop the task_hierarchy view first, it is the only object blocking the drop. (2) Repair scope: legacy tables already dropped by the partial migration 7 cannot be recovered; the repair only recreates views and triggers over relationships. (3) Roll-out: R3 ships as one PR stacked on the Now-horizon PR, because switching readers before copying legacy links, or dropping tables before readers move, breaks existing databases in between. Implementation: migrations 6 and 7 become no-ops; a transactional migration 8 consolidates links, drops legacy tables and the column, and recreates views/triggers; the runner fails startup on error.', '2026-09-14 17:56:25', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (26, 'architecture', 'ADR-0001', 'MCP User', 'Accepted by owner with the revisions in the review.', '2026-09-14 17:56:27', 0);
