INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (31, 'task', 'TASK-0009-00-00', 'MCP User', 'Scope per ADR-0001 review: recreate views and triggers only; links in already-dropped tables are unrecoverable.', '2026-09-14 18:01:23', 0);
