INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (34, 'task', 'TASK-0008-00-00', 'MCP User', 'Transactional runner (BEGIN IMMEDIATE + schema_version row, MigrationError stops startup). Migration 8 consolidates links and ALTER TABLE DROP COLUMN parent_task_id; tasks keeps PK/CHECK/defaults. Failing-migration test proves rollback.', '2026-09-14 18:08:02', 0);
