INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (49, 'requirement', 'REQ-0002-FUNC-00', 'MCP User', 'Replaced by R6a REQ-0009-FUNC-00 (edit records safely) and R6b REQ-0005-TECH-00 (curate the schema) after owner review on 2026-09-14. Decisions: requirement and task edits happen in place with before/after history, and requirements at Approved or later need a reason and show a changed-since-approval marker (no forced re-approval round trip; strict mode deferred to R8); a newly discovered requirement that amends or replaces one is a new requirement linked by refines/supersedes (supersedes deferred to R9); ADR content editable only while Proposed, then supersede; curated schema coverage; task IDs fixed; delete only unlinked early-stage records; include get_entity_history; optional if_revision concurrency check. Recorded as new requirements because requirements cannot be edited yet, which is the gap R6a closes.', '2026-09-14 20:13:28', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (50, 'task', 'TASK-0016-00-00', 'MCP User', 'REVISED (owner decision 2026-09-14): no stored changed-since-approval marker. Migration 9 adds only revision counters (requirements, tasks, architecture) and field/reason columns on lifecycle_events. The marker is derived from history instead (see TASK-0019). Recorded as a same-status comment because tasks cannot be edited until R6a lands.', '2026-09-14 20:28:05', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (51, 'task', 'TASK-0019-00-00', 'MCP User', 'REVISED (owner decision 2026-09-14): no acknowledge_requirement_changes tool and no stored marker. A requirement shows changed since last review when a content edit event exists after its most recent status change; the next status transition clears it, and that transition comment serves as the acknowledgement. Remaining acceptance criteria stand: one-call edits visible in details/trace/export, reason required at Approved or later, marker shown in details, trace and project status. This also supersedes R6a wording "re-approval clears it" (requirements cannot be edited or commented on yet).', '2026-09-14 20:28:06', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (52, 'task', 'TASK-0016-00-00', 'MCP User', 'Branch roadmap/r6-foundations. Migration 9: revision counters + lifecycle_events field/reason.', '2026-09-14 20:30:26', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (53, 'task', 'TASK-0018-00-00', 'MCP User', 'additionalProperties:false applied centrally in server list_tools so every current and future tool is covered.', '2026-09-14 20:30:27', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (54, 'task', 'TASK-0026-00-00', 'MCP User', 'Separate migration 10 drops decomposition_candidates and depth triggers and rebuilds requirement_hierarchy without decomposition columns; column drop becomes migration 11 (TASK-0027).', '2026-09-14 20:30:29', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (55, 'task', 'TASK-0016-00-00', 'MCP User', 'Migration 9: revision INTEGER NOT NULL DEFAULT 0 on requirements/tasks/architecture; field and reason on lifecycle_events. Test proves existing events unchanged; copies of lab (v6) and roadmap (v8) DBs migrate with 97/105 events byte-identical.', '2026-09-14 20:33:34', 0);
