INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (180, 'task', 'TASK-0047-00-00', 'MCP User', 'Committed 6120f6d on roadmap/r9-design-traceability (not pushed). create_relationship accepts task implements ADR (either order, stored task -> ADR) and ADR supersedes ADR (newer -> older; one transaction moves the older one to Superseded; refused for itself, already superseded, superseded source, unknown IDs). Migration 14 rebuilds relationships with supersedes in its CHECK, recreates views/triggers/indexes from stored SQL, back-fills from superseded_by, and adds set/clear_superseded_by triggers. Status tool: Superseded needs the link; leaving Superseded needs it removed. Tried on a copy of this tracker: 91 links, counts and all four views unchanged. Budget 23 tools / 12,341 chars. 264 passed (coverage 69.4%), lint clean, smoke 23 tools.', '2026-09-15 17:22:15', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (181, 'task', 'TASK-0048-00-00', 'MCP User', 'Committed 2f0429c on roadmap/r9-design-traceability (not pushed). ADR details list Implemented By (tasks) and Supersedes, and show Superseded By in basic information; task details list Implements Decisions; sections only when links exist (BaseHandler._format_linked). superseded_by moved from the schema coverage pending list to system columns. 266 passed (coverage 69.5%), lint clean, smoke 23 tools.', '2026-09-15 17:25:44', 0);
