INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (218, 'requirement', 'REQ-0006-FUNC-00', 'MCP User', 'Owner direction (2026-09-15): R11 comes last, after R13, R14 and R12. Guided capture may return as an MCP prompt or as a skill rather than as tools; that is to be explored when R11 starts. The dead sampling code (about 766 lines: requirement_handler 418-692, architecture_handler 581-752, llm_decomposition_prompts.py) can be deleted independently of that decision.', '2026-09-16 01:15:26', 0);
