INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (241, 'task', 'TASK-0067-00-00', 'MCP User', 'Committed d3c678a on roadmap/r12-evidence (not pushed). update_task_status takes optional commit and evidence and keeps them on the task like blocked_reason: omitting them on a later move leaves them, passing new ones replaces them; both show in details. Migration 17 adds commit_ref and evidence; schema coverage lists them as status-tool maintained. Budget 23 tools / 12,749 chars (Task 2,985). Two migration tests now compare against LATEST rather than a hard-coded number. 336 passed (coverage 72.1%), lint clean, smoke 23 tools.', '2026-09-16 11:11:31', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (242, 'task', 'TASK-0068-00-00', 'MCP User', 'Committed d7dbc1b on roadmap/r12-evidence (not pushed). Exported task documentation carries the commit and evidence behind a task''s status, and all three exported files carry the comments stored against their records; records without either export as before. 339 passed (coverage 72.2%), lint clean, smoke 23 tools.', '2026-09-16 11:13:37', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (243, 'task', 'TASK-0069-00-00', 'MCP User', 'Committed f056c52 on roadmap/r12-evidence (not pushed). README documents commit and evidence on update_task_status, that they persist across later moves, and what the exported task file carries; CLAUDE.md records that evidence rides on the status move like the Blocked comment does; CHANGELOG covers the two parameters, migration 17 and the fuller export. tests/test_r12_acceptance.py covers REQ-0007-FUNC-00''s four criteria. Budget unchanged at 23 tools / 12,749 chars. CI command 343 passed (coverage 72.2%); default run incl. property tests 346 passed; lint clean; smoke 23 tools.', '2026-09-16 11:16:22', 0);
