INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (260, 'requirement', 'REQ-0006-FUNC-00', 'MCP User', 'Merged in #2203 (60a0963); all tasks Complete; CI green; tests/test_r11_acceptance.py covers each acceptance criterion, including the sweep proving no source file references mcp_client or sampling. Reshaped before it was built: the measured gap was unfilled curated fields and drift, not guided questioning, so the interview tools stay removed and capture is an MCP prompt instead.', '2026-09-16 12:35:00', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (261, 'requirement', 'REQ-0006-FUNC-00', 'Claude (linkcheck dogfooding run, 2026-09-16)', 'Re-verified against reality in the linkcheck dogfooding run. The staleness signal delivered here fires on records created seconds earlier: a brand-new requirement already reads "Never verified: nobody has commented on this or moved it since it was written", so a fresh project wears the badge on every record from day one (F-43). The acceptance criterion this requirement was validated against - "a requirement whose content changed after its last verification shows as stale" - is satisfied by that behaviour, so the criterion was too weak rather than the code merely wrong: the tests asserted the message appears and never that it should not. R17 (REQ-0010-FUNC-00) carries the correction and refines this requirement. The capture prompt and the thin-record rule both worked well in the same run and need nothing.', '2026-09-16 16:39:55', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (262, 'requirement', 'REQ-0003-FUNC-00', 'Claude (linkcheck dogfooding run, 2026-09-16)', 'Re-verified in the linkcheck dogfooding run. The ready filter delivered here answered "what now?" at every step of an eight-task project without being reasoned around, and task details showing Depends On and Blocks meant the shape of the work stayed in the record rather than in my head. Two gaps at the edges. The dashboard reported "Requirements Completion: 0.0% (0/6)" at the moment the last task completed, because nothing prompts the requirement whose tasks are all done (F-52); R17 (REQ-0010-FUNC-00) carries that and refines this requirement. Separately, "No tasks found" is returned when the only startable task is already In Progress, which cannot be told from "the plan is finished" or "the plan is blocked" (F-49, not yet carried by any requirement).', '2026-09-16 16:39:59', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (263, 'requirement', 'REQ-0002-NFUNC-00', 'Claude (linkcheck dogfooding run, 2026-09-16)', 'This requirement''s functional requirement that usage evidence cover "failed or retried calls" is not met in substance. A call refused by schema validation never reaches a handler, and only handlers write the call log, so those calls are invisible: the linkcheck run ended with 9 errors in the server log and 11 in the lab driver''s client-side log, and only the client''s could explain the difference (F-53). The instrument is blind to precisely the calls where a client got the interface wrong. R18 (REQ-0006-TECH-00) carries the repair and refines this requirement. The surface evidence itself held up well: 9 of the 23 listed tools were never called once across a complete project lifecycle - requirements, architecture, tasks, implementation and validation - which is a stronger version of the argument made here.', '2026-09-16 16:40:03', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (264, 'requirement', 'REQ-0004-TECH-00', 'Claude (linkcheck dogfooding run, 2026-09-16)', 'The honest-errors work delivered here holds: no tool defect produced an error across the linkcheck run. A new failure mode turned up at the edge of it. Bulk status moves take requirement_ids while the single form takes requirement_id, one character apart, and passing a list to the singular returns "is not of type ''string''" - naming the offending value and never the parameter in the same schema that accepts exactly what was passed (F-54). An error can be perfectly honest about what it refused and still point the reader in the wrong direction: I had begun writing up a defect that did not exist before reading the schema. R19 (REQ-0003-INTF-00) carries it and refines this requirement.', '2026-09-16 16:40:07', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (265, 'requirement', 'REQ-0009-FUNC-00', 'Claude (linkcheck dogfooding run, 2026-09-16)', 'The rule established here - ADR content is editable only while Proposed, otherwise supersede it - is right, and the linkcheck run found the cost of it having no middle weight. That project''s ADR-0001 says the pool defaults "to something modest like 16"; the benchmark the same ADR called for measured 32, and the code now says 32, so the accepted record contradicts the system it describes. The remedies are a comment that renders below the decision rather than with it, or a whole superseding ADR to correct one number (F-51). R20 (REQ-0011-FUNC-00) proposes dated amendments that render with the decision and leave the original intact; it refines this requirement and deliberately does not touch the immutability rule. Which existing tool should carry an amendment is an open question recorded in its technical constraints.', '2026-09-16 16:40:12', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (266, 'requirement', 'REQ-0006-TECH-00', 'MCP User', 'Approved for execution together: R19''s suggestion and R18''s logging both need validation moved out of the MCP layer and into the server''s own routing path, so they are one change.', '2026-09-17 00:45:20', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (267, 'requirement', 'REQ-0003-INTF-00', 'MCP User', 'Approved for execution together: R19''s suggestion and R18''s logging both need validation moved out of the MCP layer and into the server''s own routing path, so they are one change.', '2026-09-17 00:45:20', 0);
