INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (280, 'requirement', 'REQ-0010-FUNC-00', 'MCP User', 'Executing R17. Scope unchanged from the Draft; three decisions taken at implementation: creation starts the verification clock, staleness gains an age threshold (LIFECYCLE_STALE_AFTER, default 14 days) alongside the changed case, and the dashboard''s staleness section is retitled Needs Verification so it can carry both honestly.', '2026-09-17 13:20:02', 0);
