INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (285, 'requirement', 'REQ-0010-FUNC-00', 'MCP User', 'Merged to main as 3950826 (PR #2205). All four tasks Complete, all eight acceptance criteria covered by tests/test_r17_acceptance.py, and the shipped behaviour checked against this tracker: it named this requirement under Work Complete, Decision Pending, which is the prompt this move answers. Left at Implemented rather than Validated: validation is the deliberate human check.', '2026-09-17 14:36:22', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (286, 'requirement', 'REQ-0011-FUNC-00', 'MCP User', 'Executing R20. The requirement left where an amendment lives open between a column on architecture and a distinct lifecycle event; taking the event, because lifecycle_events.event_type has no CHECK constraint (so no migration), because it gives get_entity_history its own event for free, and because leaving the architecture row untouched makes "the original decision text is never altered" literally true rather than merely intended. Amendments ride on update_architecture via a new amendment parameter, refused unless the decision is Accepted.', '2026-09-17 18:27:36', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (287, 'task', 'TASK-0083-00-00', 'MCP User', 'Amendments implemented as lifecycle events on the working tree; tests being brought green before these close.', '2026-09-17 18:30:06', 0);
