INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (290, 'requirement', 'REQ-0011-FUNC-00', 'MCP User', 'Merged to main as ccd338e (PR #2206). All three tasks Complete, all five acceptance criteria covered by tests/test_r20_acceptance.py plus a sixth for an amendment passed beside a field edit. The open design question is settled in the code: an amendment is a lifecycle event, not a column, so no migration was needed and the decision''s own row is never touched. R6a''s immutability wording assertions pass untouched, so the rule was extended rather than relaxed. Left at Implemented rather than Validated: validation is the deliberate human check.', '2026-09-17 20:01:08', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (291, 'requirement', 'REQ-0010-FUNC-00', 'MCP User', 'Validated after merge. Both acceptance suites pass on main (392 passed, 3 skipped at ccd338e), every linked task is Complete, and each requirement was exercised against this tracker''s own data rather than only in tests: R17''s dashboard named REQ-0010 and then REQ-0011 as awaiting a decision and went quiet once each was moved, and R20''s amendment path was checked end to end through the server layer, leaving the decision''s stored row untouched.', '2026-09-17 21:19:00', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (292, 'requirement', 'REQ-0011-FUNC-00', 'MCP User', 'Validated after merge. Both acceptance suites pass on main (392 passed, 3 skipped at ccd338e), every linked task is Complete, and each requirement was exercised against this tracker''s own data rather than only in tests: R17''s dashboard named REQ-0010 and then REQ-0011 as awaiting a decision and went quiet once each was moved, and R20''s amendment path was checked end to end through the server layer, leaving the decision''s stored row untouched.', '2026-09-17 21:19:00', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (293, 'requirement', 'REQ-0012-FUNC-00', 'MCP User', 'Reviewed with the owner in the brainstorm that produced them. R21''s design question (prompt vs tool) is settled in its own technical constraints; R23 is rendering only.', '2026-09-18 11:18:36', 0);
