INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (297, 'requirement', 'REQ-0012-FUNC-00', 'MCP User', 'Straight to Ready rather than through Architecture: R23 is rendering with no design question, and R21''s one design choice (a prompt, not a tool) is already fixed by ADR-0002 and recorded in its technical constraints. ADR-0005 addresses R21 but proposes a working convention, not R21''s design.', '2026-09-18 11:18:46', 0);
