INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (303, 'task', 'TASK-0088-00-00', 'MCP User', 'Closes F-41, open since the R15 re-run on 2026-09-14. The consequences repr was not part of F-41 and was found the same way: by reading a record this tracker had just stored.', '2026-09-18 11:28:14', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (304, 'task', 'TASK-0086-00-00', 'MCP User', 'Only a derived requirement shows an Origin line. A line on every stated one would fire on the whole tracker, which is the signal R17 warns about.', '2026-09-18 11:28:22', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (305, 'requirement', 'REQ-0012-FUNC-00', 'MCP User', 'All four tasks Complete on branch roadmap/r21-r23-reconcile-and-details. Full suite: 409 passed, 3 skipped (baseline 392 + 17 new). Left at Implemented rather than Validated: validation is the deliberate human check, and neither requirement has been exercised against this tracker''s own data yet, because the running MCP server still holds the pre-change code until it is restarted.', '2026-09-18 11:28:30', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (306, 'requirement', 'REQ-0004-INTF-00', 'MCP User', 'All four tasks Complete on branch roadmap/r21-r23-reconcile-and-details. Full suite: 409 passed, 3 skipped (baseline 392 + 17 new). Left at Implemented rather than Validated: validation is the deliberate human check, and neither requirement has been exercised against this tracker''s own data yet, because the running MCP server still holds the pre-change code until it is restarted.', '2026-09-18 11:28:30', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (307, 'requirement', 'REQ-0004-INTF-00', 'MCP User', 'Merged to main as 9442df7 (PR #2207, squash). Suite green on main: 410 passed, 3 skipped. Exercised against this tracker''s own records rather than only in tests: ADR-0005 shows its authors as a readable list and its consequences as lines, and REQ-0012-FUNC-00 shows both its Addresses Decisions and its Linked Requirements sections, which was the case that read as unlinked before. Ready for validation on this evidence; left at Implemented because validation is the deliberate human check.', '2026-09-20 13:41:12', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (308, 'requirement', 'REQ-0012-FUNC-00', 'MCP User', 'Merged to main as 9442df7 (PR #2207, squash). Suite green on main: 410 passed, 3 skipped. Half of this is exercised and half is not. The provenance half ran for real on 2026-09-19: a UI discussion was reconciled against the stored set, six of seven candidates were already covered by Validated requirements, and the one genuinely new item became REQ-0005-INTF-00 in Draft with origin derived-from-transcript, which renders as an Origin line. The prompt half has not been run in its current form: that same reconciliation exposed the retrieval defect (listing 25 requirements returned 72,858 characters and was refused), and the search-per-candidate rewrite landed in the same PR afterwards. Not ready for validation until a reconciliation has been run with the prompt as it now reads.', '2026-09-20 13:41:16', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (309, 'requirement', 'REQ-0004-INTF-00', 'MCP User', 'Rendering fixes confirmed: ADR authors as readable list, consequences render lists, requirement details show decision and requirement links. Both tasks Complete.', '2026-09-28 16:09:48', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (310, 'requirement', 'REQ-0012-FUNC-00', 'MCP User', 'Stays at Implemented, not Validated. Reviewed 2026-09-28: of the nine tests in tests/test_r21_acceptance.py, four exercise the origin column end to end and five assert that particular sentences exist in the prompt string. Acceptance criterion 1 (a transcript producing exactly one create, one update and one already-covered) and the validation metric (no proposal duplicating a stored requirement) are both untested, and neither can be tested by asserting prompt substrings - they need a prepared corpus with a ground-truth mapping and a model in the loop, which is an eval rather than a pytest.' || char(10) || char(10) || 'Measured the same day, the comparison the prompt depends on reaches 5.8% of each stored record: search_text is one substring against title and desired_state only, 4,572 of the 79,488 characters in this tracker''s 26 requirements. Twelve of 26 plausible queries against stored, Validated features returned nothing - "staleness" against R17, "prompt" against R11 and R21, "bulk status" against R9 - and an empty search is the path the prompt answers with NEW. The prompt itself is sound; what it compares against is not adequate to a large set. Recorded as REQ-0003-NFUNC-00, which this requirement now depends on: R21 is validatable once search recall is a measured number.', '2026-09-28 16:43:05', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (311, 'requirement', 'REQ-0014-FUNC-00', 'MCP User', 'Provenance, recorded 2026-09-28: this was hit in real use, not anticipated. The owner is running lifecycle-mcp on several projects at work and met the case there - a requirement holding an Abandoned task that could not be moved to Validated. The current_state on this record was reconstructed by reading the gate and the counter triggers in this checkout; the encounter that prompted it came from another project''s database.' || char(10) || char(10) || 'That makes the P1 honest rather than precautionary: nothing is stuck in this repository''s own tracker, where all 89 tasks are Complete and none are Abandoned, but something is stuck elsewhere. It also means the abandoned-task case is reachable by ordinary use of the tool, which the empty count here would otherwise argue against.', '2026-09-28 17:10:35', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (312, 'requirement', 'REQ-0006-INTF-00', 'MCP User', 'Approved for decomposition. Scope settled against REQ-0005-INTF-00: this is the read-only half, delivered as a generated single file with no connection, and REQ-0005 keeps the acting surface. Delivery choice settled too - data embedded by a generator rather than sql.js reading the db in the browser, because a file:// page cannot fetch a local .db.', '2026-09-28 17:27:50', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (313, 'requirement', 'REQ-0014-FUNC-00', 'MCP User', 'Approved with the Implemented gate folded in. Design settled while reading the code: derived rather than stored, so no column, no trigger change and no migration. One predicate - has tasks, at least one Complete, none open - is read by the Validated gate, the Work Complete section and the work_complete filter.', '2026-09-28 17:39:51', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (314, 'requirement', 'REQ-0014-FUNC-00', 'MCP User', 'Implemented on branch roadmap/req-0014-abandoned-work. Full suite: 425 passed, 3 skipped; ruff check and format clean on the changed files; the 11 pre-existing ruff findings on main are unchanged. Not validated: the behaviour is proven by tests, but the running MCP server still has the old module loaded, so it has not been exercised through a live client, and the case that prompted this is on another project''s database.', '2026-09-28 17:51:26', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (315, 'requirement', 'REQ-0007-INTF-00', 'MCP User', 'Approved. The open question is resolved in the record: keep refusing, because re-parenting must go through _apply_edit to be recorded as a field_edit, and fix the message plus add the drift test.', '2026-09-28 18:03:47', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (316, 'requirement', 'REQ-0007-INTF-00', 'MCP User', 'Implemented on branch roadmap/req-0014-abandoned-work, alongside REQ-0014-FUNC-00. Full suite 434 passed, 3 skipped; lint and format clean. The drift test was verified by breaking it deliberately and reverting.', '2026-09-28 18:07:22', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (317, 'requirement', 'REQ-0007-INTF-00', 'MCP User', 'Validated through a live client after reconnecting the server, 2026-09-28. A task parent request was refused naming update_task and its parent_task_id, with the field_edit reason and the empty-string hint, and the word invalid absent. A requirement superseding a task was still refused as "Invalid relationship: requirement -> task (supersedes)", so the distinction between a link this tool does not make and a link that cannot exist holds in practice. Neither call wrote anything. The drift test guards the pair lists against separating again.', '2026-09-28 18:23:37', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (318, 'requirement', 'REQ-0014-FUNC-00', 'MCP User', 'Validated 2026-09-28 on the test suite plus two live checks, by the owner''s decision. What was exercised through a live client after reconnecting: the derived predicate runs in get_project_status and query_requirements(work_complete=True), and the always-on refusal for open tasks gives its new wording and writes nothing. What was not exercised live, and rests on the 15 tests in tests/test_abandoned_work.py: abandoned work validating and being named, the enforce refusal, off staying silent, the all-abandoned refusal pointing at Deprecated, and the Implemented gate no longer reporting abandoned tasks as not Complete. This tracker has no Abandoned task to try them against; the case that prompted the requirement is on a work project''s database, so the first real abandoned task there is the honest confirmation.', '2026-09-28 18:26:58', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (319, 'requirement', 'REQ-0006-INTF-00', 'MCP User', 'All six tasks Complete; the last three commits and TASK-0095 are in #2216 against main, because #2212-#2214 were merged into a branch main had already moved past and never reached it. Exercised against this repository''s live tracker: make viewer writes exports/lifecycle-mcp-tracker.html (801 KB), which opens with nothing installed and nothing fetched; the dashboard figures come from the server''s own definitions and match get_project_status; search finds terms only in acceptance criteria; every one of 357 links is an in-page anchor landing on a record; headless Chrome runs the page''s script and opens the record an anchor names. Left at Implemented until #2216 is on main and the owner has looked at the page.', '2026-09-28 20:19:10', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (320, 'requirement', 'REQ-0006-INTF-00', 'MCP User', 'Validated 2026-09-28 by the owner after #2216 merged. Confirmed on main (2299a5e): snapshot, figures, render, browse and links modules, scripts/tracker_viewer.py, the make viewer target and six test files. The page was generated from this repository''s live tracker and reviewed by the owner across the series: it opens with nothing installed and nothing fetched, holds no write path, shows dashboard figures computed by the server''s own definitions, searches every field and comment, and every link lands on a record in the page. The work reached main in three PRs (#2209, #2211, #2216) because two stacked merges stranded commits on intermediate branches; #2216 carried #2212-#2214 onto main.', '2026-09-28 20:37:06', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (321, 'requirement', 'REQ-0007-TECH-00', 'MCP User', 'Approved for decomposition. Two findings from reading the code first. Only relationships has INSERT triggers (counters, superseded_by, the circular-parent guard) and none writes lifecycle_events, so loading rows does not fabricate history. And apply_all_migrations takes a target_version, which corrects the earlier claim that an older dump restores because "the migrations run first and carry it forward": migrations run on an empty database carry nothing. The restore builds the schema to the dump''s own version, loads the rows, then runs the remaining migrations over the data - the same path an existing database takes.', '2026-09-28 20:41:00', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (322, 'requirement', 'REQ-0007-TECH-00', 'MCP User', 'All four tasks Complete. Export, restore, hook, make targets and docs are on branch tracker/req-0007-dump, and this repository''s tracker is committed as lifecycle-data.sql for the first time. One criterion is met in configuration but not in effect: the pre-commit framework is not installed or declared, so the tracker-dump hook does not yet run on commits, and installing it would also activate a mypy --strict hook that blocks every commit (175 errors). Left at Implemented until the owner decides how the hook is activated.', '2026-09-28 22:50:36', 0);
INSERT INTO "reviews" ("id", "entity_type", "entity_id", "reviewer", "comment", "created_at", "resolved") VALUES (323, 'requirement', 'REQ-0015-FUNC-00', 'MCP User', 'Approved by the owner on 2026-10-01, after the implementation was reviewed in session. Recorded after the work: the requirement was stated in conversation on 2026-09-30 and built the same day.', '2026-10-01 23:12:37', 0);
